// Auto-generated grammar notes for all books
// Do not edit manually - regenerate with scripts/generate-book-data
//
// Shape: bookGrammar[bookId][difficulty] = GrammarNote[][]
// - Outer array: one entry per book"part"(chapter-like split).
// - Single-part books are still wrapped as [notes] for uniformity.

export interface GrammarNote {
 pattern: string;
 meaning: string;
 example: string;
 jlpt: string;
 tip: string;
}

/** Per-part notes for (book, difficulty). Returns [] if missing. */
export function getGrammarForPart(bookId: string, difficulty: string, partIdx: number): GrammarNote[] {
 const parts = bookGrammar[bookId]?.[difficulty];
 if (!parts || !Array.isArray(parts)) return [];
 // Support both shapes: GrammarNote[] (legacy flat) and GrammarNote[][] (parts).
 if (parts.length === 0) return [];
 if (!Array.isArray((parts as unknown[])[0])) return [];
 return ((parts as unknown) as GrammarNote[][])[partIdx] ?? [];
}

/** Flattened notes for (book, difficulty) — concatenates all parts. */
export function getGrammarFlat(bookId: string, difficulty: string): GrammarNote[] {
 const parts = bookGrammar[bookId]?.[difficulty];
 if (!parts || !Array.isArray(parts)) return [];
 if (parts.length === 0) return [];
 if (!Array.isArray((parts as unknown[])[0])) return parts as unknown as GrammarNote[];
 return (parts as unknown as GrammarNote[][]).flat();
}

export const bookGrammar: Record<string, Record<string, GrammarNote[][]>> = {"a-aki":{"simplified":[[{"example":"たくさん書いてありました","tip":"Used with transitive verbs to focus on the result of an action rather than the actor.","meaning":"Represents a state that remains as a result of a conscious action.","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"Use this for natural laws, machines (pressing buttons), or a fixed sequence of events.","meaning":"When A happens, B follows naturally or inevitably.","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"Indicates that information was heard or read from another source (hearsay).","tip":"Unlike 'looks like', hearsay 'sou desu' always follows the dictionary (plain) form.","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"Using 'ni omou' often suggests an emotional reaction or subjective viewpoint.","meaning":"To have a certain thought or feeling instinctively.","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"While a certain state or situation continues.","tip":"Often suggests that if not done now, the opportunity will be lost (e.g., 'while it's summer').","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form form)","example":"夏休みに海へ行こう","tip":"For group 2 verbs (ru-verbs), replace 'ru' with 'you'. For group 1 (u-verbs), change the 'u' sound to 'o' and add 'u'.","meaning":"The Volitional form expresses intention or an invitation."},{"example":"話しているのを見ると","tip":"Use 'no' instead of 'koto' when followed by verbs of direct perception like seeing, hearing, or waiting.","meaning":"Nominalizes a verb, turning an action into a Noun or object.","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"Suggests a logical inference based on evidence, similar to 'it seems like'.","meaning":"Expresses a guess or appearance based on what the speaker observed."}]],"intermediate":[[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"Focuses on preparation. Doing something now for later readiness.","meaning":"Doing something in advance or for future use.","jlpt":"N4"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. Often expresses a logical consequence.","meaning":"The conjunction 'if' or 'when'.","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"Seems like / heard that (indicates inference based on evidence).","tip":"Used when there is a basis for a guess but not 100% certainty.","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"Used to explain the extent of a state or feeling by giving an example.","meaning":"To the extent of / as much as (very).","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"When/if (followed by a natural or inevitable result).","tip":"In this context, it indicates a discovery that happens naturally when an action is taken."},{"meaning":"Despite / even though (often shows regret or dissatisfaction at the end of a sentence).","tip":"When at the end of a sentence, it often implies 'I wish it were so' or 'despite the situation'.","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"When it comes to / once someone becomes... (emphasizes special status or rank).","tip":"Used for high-ranking positions or important situations where expectations naturally change."}]],"original":[[{"meaning":"将来の使用のために何かを事前にする、または何かを特定の状態のままにしておく (to do something in advance for future use or to leave something in a certain state)。","tip":"会話では、これはしばしば短縮されます: ～ておく は ～とく (becomes ～toku) となります。","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"観察または情報に基づいた推測を示す表現で、「～のようだ (it seems like)」または「～らしい (apparently)」。","jlpt":"N4","tip":"「よだ (yoda)」とは異なり、「～らしい (rashii)」は、結論に客観的な根拠や噂がある場合に使用されます。","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"動詞の文語的または形式的な否定形で、～ない と同等です。","tip":"文学やことわざでよく見られます。「する (suru)」は「せぬ (senu)」に、「くる (kuru)」は「こぬ (konu)」になります。","jlpt":"N3"},{"meaning":"特定の高いレベルや特別な地位に達すると、物事が自然に変化したり深刻になったりすることを強調します。","tip":"役割、職業、または特別な状況に使用され、より高い期待基準を示します。","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"行為または状態の程度または範囲を示します。「～の程度まで (to the extent that...)」。","jlpt":"N3","tip":"これを感情や出来事の極端な限界と比較することで、描写に劇的さや強調を加えることができます。"},{"meaning":"何かが特定の方法であるはずだ、またはあったはずだという期待や信念を示し、それがそうでない場合に後悔や驚きを伴うことが多いです。","jlpt":"N3","tip":"「～のに (noni)」が続く場合、現実が期待と反対であることを強く示唆します。","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"理由や原因を表現する形式的または文語的な方法で、「～なので (because)」または「～が原因で (due to)」。","tip":"これは非常に堅苦しく形式的です。現代の会話では、「～ので (node)」または「～から (kara)」を使用します。一部の表現では、「ゆえ (yue)」に短縮されます。","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]]},"kumo-no-ito":{"simplified":[[{"pattern":"Plain past + ことがある","example":"いいことをしたことがあります","tip":"The verb must be in the past tense to express experience; if used with the Dictionary form, it means something happens occasionally.","meaning":"Used to describe past experiences (have done something before)","jlpt":"N4"},{"example":"生きたいと思っているはずだ","pattern":"Dictionary form + はずだ","meaning":"Expresses a strong conviction or expectation that something is true (should be, ought to be)","jlpt":"N4","tip":"This indicates a logical conclusion based on facts or common sense rather than just a guess."},{"tip":"When zako (the copula) is used at the end of a sentence like からです, it emphasizes the explanatory nature of the statement.","jlpt":"N4","meaning":"Used to give a reason or explanation (because)","example":"思っているはずだと思ったからです","pattern":"Clause + からだ"},{"meaning":"Used to express an attempt or intention to do an action that was either unsuccessful or interrupted (tried to)","jlpt":"N4","tip":"This is often followed by a contrastive conjunction like が to indicate the attempt failed or changed.","pattern":"Volitional form + とする","example":"踏もうとしましたが"},{"meaning":"Used to define or name a person, place, or thing (called, named)","jlpt":"N4","tip":"This is very common when introducing a specific name or title that the listener might not be familiar with.","pattern":"Noun + という + Noun","example":"犍陀多という男"},{"tip":"The present progressive form と思っている is often used to show that the intention has been held for some time.","jlpt":"N4","meaning":"Used to express a decision or an intention formed in the speaker's mind (think of doing)","pattern":"Volitional form + と思う","example":"助けようと思いました"}],[{"tip":"Used for objective reasons or polite explanations; more formal than から.","pattern":"Plain past/Dictionary form + ので","jlpt":"N4","meaning":"Indicates a reason or cause for a subsequent action or state.","example":"疲れたので、少し休みました。"},{"example":"行けるかもしれない！","tip":"Often used when there is about a 50% chance or less of something being true.","pattern":"Dictionary form + かもしれない","jlpt":"N4","meaning":"Indicates a possibility that something might happen or be true."},{"example":"もう少しで出られるかもしれない","meaning":"Indicates that something is on the verge of happening or almost complete.","tip":"When used with quantifiers like もう少し, it indicates the threshold or proximity to a change.","pattern":"Noun + で","jlpt":"N3"}],[{"pattern":"Dictionary form + と","meaning":"When/if; expresses a natural consequence or a discovery when one action is performed.","jlpt":"N4","example":"気がつくと","tip":"In this context, it marks a discovery: 'When he noticed...'. It often describes something that happens automatically or unexpectedly."},{"example":"ついてきていました","tip":"Used here to show the sinners are following 'up' toward where the protagonist is.","pattern":"Te-form + くる","jlpt":"N4","meaning":"To come towards the speaker; indicates an action moving toward the current point in time or space."},{"pattern":"Te-form + しまう","meaning":"To do something completely; often implies regret, accident, or an irreversible state.","jlpt":"N4","example":"切れてしまう","tip":"The speaker uses this because the thread breaking would be a disastrous, unintended event."},{"jlpt":"N4","meaning":"To become; describes a change in state.","pattern":"I-adjective (remove い) + くなる","tip":"For Na-adjectives and Nouns, use になる instead of くなる.","example":"怖くなりました"},{"example":"落ちていきました","tip":"Used here to describe the motion of falling 'away' from the viewer down into hell.","pattern":"Te-form + いく","meaning":"To go away from the speaker; indicates an action moving away from the current point in time or space.","jlpt":"N4"}],[{"pattern":"Volitional form + とする/としました","meaning":"To try to do or attempt to do something; describes an effort or onset of an action.","jlpt":"N4","tip":"This pattern often implies that the attempt was made but the result may be unsuccessful or interrupted.","example":"自分だけ助かろうとしました。"},{"example":"糸を切ってしまったのです。","tip":"In this context, it emphasizes the irreversible and unfortunate nature of the thread snapping.","jlpt":"N4","meaning":"To do something completely, or to do something accidentally/unintentionally with a sense of regret.","pattern":"Te-form + しまう/しまった"},{"tip":"When used with adjectives, you must drop the final い or な before adding そう. For いい (good), it becomes よさそう.","example":"とても悲しそうなかおをしました。","pattern":"I-adjective (remove い) + そうな","jlpt":"N3","meaning":"To look like; to appear to be a certain way based on visual impression."}]],"intermediate":[[{"meaning":"To do something for someone of lower status or for an animal.","example":"助けてやったのです。","jlpt":"N4","pattern":"Te-form + やる","tip":"This is a less polite version of ～てあげる and should be used with caution when referring to humans."},{"tip":"Use this when you have a logical reason or evidence for your conclusion.","pattern":"Dictionary form + はずだ","jlpt":"N4","meaning":"Expression of high confidence or expectation that something is true.","example":"生きたいと思っているはずだ"},{"example":"水晶のような水を通して","meaning":"To look like or be similar to something.","tip":"This creates a simile; for modifying verbs or adjectives, use ～のように instead.","pattern":"Noun + のような","jlpt":"N4"},{"example":"何とも言えないよい香り","meaning":"Indescribable or beyond words; used to emphasize a quality.","pattern":"何とも言えない + Noun","jlpt":"N3","tip":"This is a set phrase often used to describe strong sensory experiences like smells, colors, or feelings."},{"jlpt":"N3","pattern":"Volitional form + と考える","tip":"This feels more deliberate and thought-out than the spontaneous intention of ～と思う.","example":"地獄から救い出してやろうと考えました。","meaning":"The Volitional form followed by と考える indicates a decision or intention the speaker has been contemplating."},{"example":"地獄の底めがけて","meaning":"Aiming for, heading toward, or targeting a specific direction/goal.","tip":"This is a more formal or descriptive way than using に to indicate movement toward a target.","jlpt":"N1","pattern":"Noun + めがけて"}],[{"jlpt":"N4","example":"よじ登り始めました","tip":"Used for the intentional beginning of a continuous action or process.","meaning":"To start doing something","pattern":"Masu-stem + 始める"},{"meaning":"Might; perhaps; indicates a possibility","pattern":"Dictionary form + かもしれない","tip":"This expresses a subjective guess or possibility, often about 50% certainty.","example":"行けるかもしれない","jlpt":"N4"},{"meaning":"Thinking of doing; intending to do","pattern":"Volitional form + と思う","example":"休もうと思いました","tip":"The Volitional form followed by this pattern expresses a decision or plan made by the speaker.","jlpt":"N4"},{"pattern":"Masu-stem + ながら","meaning":"While doing; doing two things at once","tip":"The main action comes second in the sentence; the 'while' action is secondary.","example":"光りながら","jlpt":"N4"},{"example":"登り続ければ","tip":"Focuses on the condition required for a specific result to occur.","jlpt":"N4","meaning":"If (conditional)","pattern":"Conditional form form (ば)"},{"jlpt":"N3","tip":"Unlike simple aspect markers, this emphasizes the persistent continuation of an action.","example":"登り続ければ","pattern":"Masu-stem + 続ける","meaning":"To continue doing something"}],[{"example":"切れてしまうかもしれない","tip":"In speech, this often contracts to ～ちゃう, but here it emphasizes the unfortunate and irreversible nature of the thread snapping.","jlpt":"N4","pattern":"Te-form + しまう","meaning":"To do something accidentally, or to finish something completely (often with regret)"},{"meaning":"Might; perhaps; there is a possibility that...","tip":"This expresses a subjective guess or worry about a future event or current state.","example":"切れてしまうかもしれない","jlpt":"N4","pattern":"Dictionary form + かもしれない"},{"tip":"It expresses a strong feeling of contradiction, regret, or frustration between the effort made and the result.","example":"登ってきたのに","jlpt":"N4","pattern":"Dictionary form + のに","meaning":"Even though; despite the fact that..."},{"example":"驚くと同時に","tip":"Used when two actions or states occur exactly at the same time. Note that it can also follow Nouns.","pattern":"Dictionary form + と同時に","jlpt":"N3","meaning":"At the same time as; simultaneously with..."},{"meaning":"Without even having time to...; in no time...","example":"言う間もなく","tip":"This emphasizes the extreme speed of an event, meaning something happened before the subject could even perform the named action.","pattern":"Dictionary form + 間もなく","jlpt":"N2"},{"jlpt":"N2","pattern":"Plain past + 瞬間","example":"出た瞬間でした","tip":"This emphasizes that the following action happened immediately after the first action, almost like a trigger.","meaning":"The moment that...; as soon as..."}],[{"jlpt":"N4","meaning":"Expresses that there is nothing else or nothing more than what is specified (only/just)","pattern":"Dictionary form + だけ","example":"垂れているだけでした","tip":"When combined with the copula as in 'だけでした', it emphasizes the exclusivity of the state."},{"tip":"In this context, it emphasizes the irreversible and unfortunate nature of the thread breaking.","example":"切ってしまったのでしょう","pattern":"Te-form + しまう","jlpt":"N4","meaning":"Indicates the completion of an action, often with a sense of regret, or that something happened accidentally/unintentionally"},{"pattern":"Dictionary form + でしょう","jlpt":"N4","meaning":"Expresses a conjecture or a polite way to state an opinion about a probability (probably/must be)","tip":"It is often used when the speaker is making an inference based on the circumstances.","example":"切ってしまったのでしょう"},{"meaning":"Indicates an attempt to do something or that someone is about to perform an action","jlpt":"N4","pattern":"Volitional form + とする","example":"助かろうとした","tip":"This specific patterns shows the subject's intention or effort at a particular moment."},{"example":"悲しそうな","tip":"When used with an I-adjective like '悲しい', you must drop the final 'い' before adding 'そうな'.","meaning":"Indicates that something appears or looks like a certain state based on outward appearance","jlpt":"N3","pattern":"Stem + そうな"},{"pattern":"Noun + のように","jlpt":"N3","meaning":"Used to describe doing something in the same manner as something else or following a certain likeness (like/as)","tip":"This is used for metaphors or to describe a representative manner of action.","example":"いつものように"},{"tip":"In this literary context, it describes the scent gradually moving through and filling the space.","example":"広がっていくのでした。","pattern":"Te-form + いく","jlpt":"N3","meaning":"Indicates an action or state that starts from the present/reference point and continues into the future or away from the speaker"}]],"original":[[{"meaning":"Used to describe something by comparing it to something else (simile).","jlpt":"N4","example":"蓮の花は、みんな玉のようにまっ白で","pattern":"Noun + のように","tip":"Focus on how 'Noun A' shares a specific quality with 'Noun B'. It functions like an adverb."},{"meaning":"An explanatory or emphasis marker used to provide context or justification. In polite speech, it becomes ～のでございます.","jlpt":"N4","pattern":"Dictionary form + のだ/のでございます","example":"三途の河や針の山の景色が、丁度覗き眼鏡を見るように、はっきりと見えるのでございます。","tip":"Use this when providing an explanation for a situation or highlighting a reason."},{"jlpt":"N4","meaning":"To try to do something, or to be about to perform an action.","tip":"The verb 致す is the humble version of する. This pattern often implies the attempt didn't succeed or was interrupted.","pattern":"Volitional form + と（する/致す）","example":"踏み殺そうと致しましたが"},{"meaning":"Expresses a strong conviction or certainty that something is true.","jlpt":"N3","pattern":"Noun / Dictionary form + に違いない","example":"命のあるものに違いない。","tip":"Unlike かもしれない (might), this shows the speaker is quite sure based on some evidence."},{"jlpt":"N2","meaning":"Even though; despite being (concessive). Used to express contrast.","tip":"When used with Nouns or Adjectives, it means 'although' rather than 'while'. Often used in formal idiomatic expressions.","example":"これも小さいながら","pattern":"Stem / Noun + ながら"},{"tip":"The verb する becomes せずに. It describes an action done while omitting another expected action.","pattern":"Plain negative (minus ない) + ずに","example":"とうとうその蜘蛛を殺さずに助けてやった","jlpt":"N3","meaning":"Without doing (an action). A more formal or written version of ～ないで."},{"meaning":"To do something for someone as a favor (explicitly giving a benefit).","jlpt":"N4","pattern":"Te-form + やる/あげる","example":"この男を地獄から救い出してやろうと御考えになりました。","tip":"やろう is the Volitional form of やる. Use やる when the recipient is of lower status, like an animal or a criminal."},{"tip":"The main action comes after the ながら. The subject must be the same for both actions.","example":"地獄の容子を御覧になりながら","pattern":"Masu-stem + ながら","jlpt":"N4","meaning":"While performing one action, performing another simultaneously."}],[{"pattern":"Plain past + り + Plain past + りする","meaning":"Listing multiple actions or states in no particular order, implying others might exist","jlpt":"N4","tip":"Always end the list with a form of the verb する to complete the grammatical structure.","example":"浮いたり沈んだりしていた"},{"meaning":"To be in the process of doing something, or on the verge of a state","jlpt":"N4","pattern":"Masu-stem + かける","example":"死にかかった蛙","tip":"Used for actions that have started but are not yet finished, or states that are about to happen."},{"tip":"In the text, 居りました is the humble/polite version of 居ました (the past of いる).","example":"もがいてばかり居りました","pattern":"Te-form + ばかりいる","jlpt":"N4","meaning":"Doing nothing but a specific action; constantly doing something"},{"tip":"When を follows a location with verbs like 'walk', 'fly', or 'pass', it indicates the path or space being traversed.","example":"中を、遠い遠い天上から","pattern":"Noun + を + Verb of motion","jlpt":"N4","meaning":"Through or along a space (used with verbs of motion)"},{"tip":"This is a formal equivalent of に違いない and is often found in literature or formal documents.","example":"ぬけ出せるのに相違ございません","pattern":"Noun / Clause + に相違ない/に相違ございません","jlpt":"N2","meaning":"Without a doubt; certain to be (very formal)"},{"example":"極楽へはいる事さえも出来ましょう","tip":"When used with particles like に or へ, it can either replace them or follow them. Here it emphasizes that even 'entering heaven' is possible.","jlpt":"N3","meaning":"Even; emphasizing an extreme case to imply others are obvious","pattern":"Noun / Masu-stem + さえ"},{"tip":"筈 (はず) indicates a strong expectation based on logic. はございません is a formal negation of はない.","example":"沈められる事もある筈はございません","pattern":"Dictionary form + 筈はございません","jlpt":"N4","meaning":"It is expected that... not; there is no expectation/possibility that..."},{"pattern":"Masu-stem + 始める","meaning":"To begin doing something","jlpt":"N4","tip":"Attached directly to the stem of the verb to indicate the initiation of an action.","example":"のぼり始めました"},{"jlpt":"N2","meaning":"To do something completely, thoroughly, or to the very end","pattern":"Masu-stem + 切る","example":"慣れ切っているのでございます","tip":"Expresses that an action has been finished entirely or performed with great intensity."},{"tip":"Commonly used with いくら (no matter how much) to express that an effort will be in vain.","example":"焦って見た所で","pattern":"Plain past + 所で","meaning":"Even if... (used for hypothetical situations with a negative or futile outcome)","jlpt":"N2"},{"tip":"Indicates a plan or internal intent at the time of the action.","example":"休むつもりで","pattern":"Dictionary form + つもり","jlpt":"N4","meaning":"With the intention of doing something"},{"jlpt":"N2","meaning":"Worth doing; the result was worth the effort previously spent","pattern":"Plain past + 甲斐がある","example":"のぼった甲斐があって","tip":"Often follows a verb expressing effort (like 'stepping up' or 'studying') to show a positive reward."},{"pattern":"Dictionary form + かも知れない/かも知れません","meaning":"It might be/perhaps (expressing a possibility)","jlpt":"N4","tip":"Indicates an objective possibility, often used when the speaker is unsure but guessing.","example":"わけがないかも知れません"}],[{"example":"落ちてしまわなければなりません","jlpt":"N4","meaning":"Must; have to; it is necessary to do something","tip":"This is the formal way to express obligation. In casual speech, it often shortens to ～なきゃ or ～なくちゃ.","pattern":"Plain negative (minus い) + ければなりません"},{"tip":"Use this when you have strong evidence or conviction about a situation. The informal version uses に違いない.","pattern":"Dictionary form + に違いありません","jlpt":"N4","example":"落ちてしまうのに違いありません","meaning":"Must be; no doubt that; certain that"},{"pattern":"Te-form + しまう","tip":"In this context, it emphasizes the tragic and irreversible nature of falling back into hell.","meaning":"To do something completely, or to do something accidentally/regrettably","example":"落ちてしまうのに違いありません","jlpt":"N4"},{"example":"堪える事が出来ましょう","jlpt":"N4","meaning":"Can do; be able to do (potential capability)","tip":"Adding the Volitional form ～ましょう here creates a rhetorical question: 'Could it possibly be able to...?'.","pattern":"Dictionary form + 事ができる"},{"example":"蟻の行列のように","jlpt":"N3","meaning":"Like; similar to; in the manner of","tip":"Use this pattern to describe an action or state by comparing it to something else (simile).","pattern":"Noun + のように"},{"jlpt":"N3","example":"口を開いたまま","meaning":"Leave as is; while remaining in a certain state","tip":"This expresses that a condition continues unchanged while another action or state exists.","pattern":"Plain past + まま"},{"pattern":"Noun + ばかり","tip":"It suggests that no other actions or things are happening except for the one mentioned.","meaning":"Nothing but; only; just","jlpt":"N3","example":"眼ばかり動かして居りました"},{"tip":"The primary action usually comes after the ながら Clause. Here it describes the manner of climbing.","pattern":"Stem + ながら","example":"一列になりながら","jlpt":"N3","meaning":"While; at the same time as"},{"example":"断れたと致しましたら","jlpt":"N3","meaning":"Assuming that; supposing that; if we assume...","tip":"致しましたら is the humble/polite form of したら. It is used to set up a hypothetical scenario.","pattern":"Plain past + と致しましたら (と仮定したら)"},{"pattern":"Dictionary form + のと + Dictionary form + のとで","tip":"This structure is used to list multiple reasons or factors that lead to a specific result or state.","meaning":"Because of A and B; due to the combination of A and B","jlpt":"N3","example":"驚いたのと恐しいのとで"},{"pattern":"Noun + の中に","tip":"In this context, it functions similarly to うちに, meaning 'while there is still time' or 'before the window of opportunity closes'.","meaning":"Before it's too late; while a certain state still continues","example":"今の中にどうかしなければ","jlpt":"N2"}],[{"pattern":"Te-form + しまう","jlpt":"N4","tip":"In this context, it emphasizes the finality and the sadness of the event.","meaning":"Regretfully or completely finishing an action; used here for an unfortunate outcome.","example":"沈んでしまいますと"},{"example":"沈んでしまいますと","meaning":"When / Whenever; indicates a natural or inevitable consequence of an action.","jlpt":"N4","pattern":"Dictionary form + と","tip":"It often connects a specific action to a resulting state that follows immediately."},{"meaning":"Looking like; appearing to be.","example":"悲しそうな御顔","pattern":"Stem + そうな + Noun","jlpt":"N4","tip":"When attached to an adjective stem, it describes a visual impression or feeling."},{"jlpt":"N4","pattern":"Stem + ながら","tip":"The primary action is usually the one described by the verb that follows the ～ながら Clause.","example":"なさりながら","meaning":"While doing; expresses two actions occurring simultaneously by the same person."},{"tip":"Attached to the Masu-stem to indicate the start of a continuous action.","pattern":"Stem + 始める","jlpt":"N4","meaning":"To begin doing something.","example":"御歩きになり始めました"},{"meaning":"To try to; to attempt to.","example":"ぬけ出そうとする","tip":"This pattern expresses an attempt or intention to perform an action, often right before it happens.","pattern":"Volitional form + とする","jlpt":"N3"},{"tip":"何とも云えない is a common set phrase meaning 'indescribable' or 'exquisite'.","jlpt":"N3","pattern":"Plain negative + Noun","example":"云えない好い匂","meaning":"Cannot say / Unspeakable; used here as an idiomatic expression for 'indescribable'."},{"tip":"のでございましょう is the ultra-polite version of でしょう used in formal storytelling.","jlpt":"N3","pattern":"Dictionary form + でしょう/でしょう","example":"思召されたのでございましょう","meaning":"Probably; must be. Used to express a polite conjecture."}]]},"rashomon":{"simplified":[[{"pattern":"Te-form + いる","jlpt":"N5","tip":"Think of this as the past version of ～ている. It describes what was happening at a specific point in time.","example":"雨がやむのを待っていました。","meaning":"Indicates an ongoing action in the past (past continuous)."},{"tip":"Use this when you need to follow a verb with a particle like を or は. It acts like'the act of'or'the fact that'.","jlpt":"N4","pattern":"Dictionary form + の (nominalizer)","meaning":"Changes a verb or phrase into a Noun so it can be used as an object.","example":"雨がやむのを待っていました。"},{"tip":"Unlike と which lists everything, や implies there are other things in the list that aren't mentioned.","pattern":"Noun + や〜など","jlpt":"N4","meaning":"Used to give examples among many possibilities, meaning'such as'or'and etc.'","example":"地震や火事などの災害"},{"meaning":"Indicates a change in state or becoming a certain way.","example":"貧しくなっていました。","tip":"For い-adjectives, change the final い to く before adding なる. For nouns and な-adjectives, use に.","jlpt":"N4","pattern":"I-adjective + くなる / Na-adjective + になる"},{"example":"住むようになりました。","meaning":"Indicates a change in a situation or habit over time (to reach the point where...).","pattern":"Dictionary form + ようになる","jlpt":"N4","tip":"This often describes a gradual change from one state (not doing) to another (doing)."},{"tip":"Use this pattern when'B'always or naturally follows'A', like'if you press this button, the light turns on'.","jlpt":"N4","pattern":"Dictionary form + と","example":"夕方になると","meaning":"Indicates a natural consequence or a repeatable cause-and-effect relationship (if/when)."},{"example":"みんな怖がって","meaning":"Used to describe someone else's outward signs of emotion or feeling.","tip":"In Japanese, you usually only use feeling words like 怖い (scary) for yourself. Use ～がる to describe how others are acting/feeling.","jlpt":"N3","pattern":"I-adjective + がる"}],[{"meaning":"Don't have to; no need to do (something)","example":"「もう来なくていい」","tip":"This is the negative form of ～てもいい. It is used to give permission or express that an action is unnecessary.","jlpt":"N4","pattern":"Plain negative + くていい"},{"example":"死んでしまう","meaning":"To do something completely or an accidental, regrettable action","jlpt":"N4","pattern":"Te-form + しまう","tip":"In casual speech, this often contracts to ～ちゃう, but in written text, it highlights the finality or unwanted nature of the situation."},{"jlpt":"N4","pattern":"Conditional form + ばいい","tip":"When combined with a question word like どうやって, it expresses the speaker's uncertainty about the best course of action.","example":"生きていけばいいか","meaning":"If... then it's good (Used for seeking advice or wondering what to do)"},{"meaning":"While doing; performing two actions simultaneously","example":"考えながら","tip":"The action after ながら is the main focus. Attach it to the stem (ます-form) of the verb.","pattern":"Masu-stem + ながら","jlpt":"N4"},{"tip":"Use this when a physical or environmental change (like weather or feelings) starts to happen or move toward you.","jlpt":"N4","pattern":"Te-form + くる","meaning":"To indicate a change that has begun and is continuing toward the present","example":"寒くなってきたので"},{"pattern":"Volitional form + と思う","jlpt":"N4","tip":"The Volitional form form (意向形) followed by と思う expresses a internal decision or plan that the speaker has made.","meaning":"To think of doing; to intend to do (something)","example":"寝ようと思いました"},{"tip":"Use this when you have a logical reason to believe something is true. Here, the man expects only the dead to be there because of the location.","pattern":"Dictionary form + はず","jlpt":"N4","example":"死んだ人しかいないはずです","meaning":"Expectation; it should be; it is supposed to be"}],[{"jlpt":"N5","tip":"Used when something is physically inside a space or object. Always follows a Noun + の.","meaning":"Indicates location or existence (in, inside)","example":"部屋の中に火の光が見えました。","pattern":"Noun + のの中に"},{"meaning":"Present continuous form (is doing) or resultative state (is done)","tip":"While often translated as'-ing', it can also describe a state that began in the past and continues to the present.","jlpt":"N4","pattern":"Te-form + いる","example":"こんな夜に火を使っているのは不思議です。"},{"jlpt":"N4","meaning":"Nominalizer (turns a verb into a Noun)","tip":"Use this to make a whole sentence or verb phrase the subject of the sentence, often followed by an adjective.","example":"火を使っているのは不思議です。","pattern":"Clause + のは"},{"example":"一番上まで登ると、部屋の中に火の光が見えました。","pattern":"Dictionary form + と","jlpt":"N4","tip":"When used with a past tense verb in the second Clause, it usually describes something the speaker discovered after doing an action.","meaning":"Natural consequence or unexpected discovery (when / if)"},{"jlpt":"N3","meaning":"Each / at a time (indicates a steady distribution)","tip":"Attach this to numbers or counters to show that an action is performed in specific increments.","example":"髪の毛を一本ずつ抜いていました。","pattern":"～ずつ"}],[{"pattern":"Te-form + (connective)","jlpt":"N5","meaning":"The'Te-form'used to connect two or more actions in chronological order.","example":"男はそれを見て、とても怒りました。","tip":"Think of this as saying'and'between verbs. The tense of the entire sentence is determined by the final verb."},{"pattern":"Plain past + Noun","jlpt":"N5","example":"死んだ人","tip":"In Japanese, you can put a verb directly before a Noun to describe it, like'the person who died'.","meaning":"Using the past tense (Plain past) of a verb to modify a Noun, creating a relative Clause."},{"jlpt":"N5","pattern":"Te-form + いる","meaning":"Expresses an action currently in progress.","example":"何をしている！","tip":"This is the equivalent of'-ing'in English. In casual speech, the'i'is often dropped."},{"jlpt":"N4","pattern":"Masu-stem + なさい","example":"言いなさい！","tip":"Attach this to the Stem (masu-form minus'masu'). It is more authoritative than'te-kudasai'but softer than the bare imperative.","meaning":"A polite but firm command usually used by superiors or parents."},{"meaning":"An expression of surprise, disbelief, or disdain towards an action or state.","tip":"This particle highlights something the speaker finds shocking or unexpected. It often implies a negative feeling like'to think that...'or'things like...'.","example":"髪を抜くなんて","pattern":"Clause + なんて","jlpt":"N3"},{"pattern":"Clause + なんて","jlpt":"N3","meaning":"An exclamation used to emphasize the degree of an adjective, often translated as'What a...'or'How...!'","tip":"This is often paired with'da'or'darou'at the end of the sentence to show the speaker's strong emotion.","example":"なんて悪い人だ！"}],[{"meaning":"Used to indicate the content of a thought, statement, or action (quotation).","example":"蛇の肉を魚の肉だとうそをついて売っていました。","pattern":"Dictionary form + と","jlpt":"N5","tip":"Think of this as quotation marks. It is used here to show what the lie actually was."},{"tip":"Use the Dictionary form of a verb before this. It indicates a strong intention that you have already decided on.","pattern":"Dictionary form + つもり","jlpt":"N4","example":"この髪を抜いて、かつらを作るつもりでした。","meaning":"Expresses intent, plan, or purpose."},{"tip":"Attach this to the stem of a verb. The main focus is always on the second action.","pattern":"Masu-stem + ながら","jlpt":"N4","example":"おばあさんは震えながら言いました。","meaning":"Indicates two actions happening simultaneously by the same person."},{"meaning":"Expresses a possibility or a softened opinion (maybe/it might be).","example":"悪いことかもしれませんが、……","jlpt":"N4","pattern":"Dictionary form + かもしれない","tip":"In polite speech, use the form ending in ＋ません. It expresses uncertainty."},{"jlpt":"N4","pattern":"Te-form + もいい","tip":"This follows the て-form of a verb. In this text, the speaker is using it to justify a moral choice to himself.","meaning":"Asks for or gives permission to do an action.","example":"悪いことをしてもいいのだな。"},{"tip":"Here, it emphasizes the finality and negative outcome of death if the character does not act.","jlpt":"N4","pattern":"Te-form + しまう","example":"そうしないと死んでしまうからです。","meaning":"Indicates that an action will be completed, or expresses regret/unintentionality."},{"tip":"When following a verb, use the Dictionary form. It shows a clear objective or reason for an action.","pattern":"Dictionary form + ために","jlpt":"N3","example":"生きるために、蛇の肉を……","meaning":"Indicates a purpose, goal, or for the sake of something/someone."}],[{"jlpt":"N5","tip":"In this context (門の下を), it describes moving through or looking across an area.","meaning":"Indicates the object of an action or a path through/along a space.","example":"門の下を","pattern":"Noun + を"},{"example":"死んでしまう","pattern":"Te-form + しまう","jlpt":"N4","tip":"Use this when something happens that you didn't want to happen, or to emphasize it is finished.","meaning":"Expresses completion of an action, often with a sense of regret, accident, or finality."},{"pattern":"Dictionary form + な (prohibition)","example":"怒るなよ","meaning":"A strong negative imperative used to forbid someone from doing something.","tip":"The particle な added directly to the Dictionary form makes a command'Don't do it!'. Adding よ softens the tone slightly.","jlpt":"N4"},{"pattern":"Plain negative + と","example":"そうしないと","tip":"Often translated as'if I don't...'or'unless...'. It marks an inevitable consequence.","meaning":"Indicates that if a certain condition is not met, a negative result will follow.","jlpt":"N4"},{"jlpt":"N4","tip":"For 五段 verbs like 脱ぐ, change the final vowel to the'a'sound and add せる. In this story, it implies a forced action.","meaning":"The Causative form, used to indicate making or letting someone do an action.","example":"服を脱がせて","pattern":"Causative form + せる / させる"},{"example":"急いで降りていきました","pattern":"Te-form + いく","jlpt":"N4","meaning":"Indicates an action that moves away from the speaker's current location or perspective.","tip":"Use this when an action involves moving'away'or continuing into the future."},{"tip":"This structure turns the entire preceding Clause into the'reason'for the previous statement.","meaning":"Added at the end of a sentence to provide an explanation or reason for something.","jlpt":"N4","pattern":"Clause + からだ","example":"死んでしまうからだ"},{"meaning":"Used to embed a question (who, what, where, etc.) within a sentence.","tip":"The particle か marks the end of the embedded question. It is often followed by verbs like 知る (to know) or 分かる (to understand).","jlpt":"N3","pattern":"（疑問詞）～か","example":"どこへ行ったのか"}]],"intermediate":[[{"jlpt":"N4","tip":"Use this pattern instead of こと when describing immediate sensory perceptions like seeing, hearing, or waiting for an action to occur.","example":"雨がやむのを待っていた。","pattern":"Dictionary form + の","meaning":"The nominalizing particle used to turn a verb into a Noun, often representing an action or event happening before your eyes."},{"tip":"For the verb いる (to exist), the stem is just い. This expresses that the person hasn't seen anyone yet but judged from the situation that they \"look like\"they would be there.","jlpt":"N4","example":"雨宿りをする人がいそうだが、誰もいない。","meaning":"Indicates that something looks like or appears to be a certain way based on visual evidence.","pattern":"Masu-stem + そうだ"},{"meaning":"Used to indicate the extent or degree of a situation, often translated as'to the extent that'.","pattern":"Noun + ほど","example":"薪として売っていたほどだという。","tip":"Think of this as'so much so that...'. In this text, it emphasizes how desperate the situation was by showing just how far people went (breaking statues).","jlpt":"N3"},{"example":"なぜかというと、この数年...からだ。","meaning":"A structure used to introduce a reason.'The reason why is because...'","pattern":"Clause + からだ","tip":"This is a formal and clear way to explain cause and effect. Always look for the からだ at the end of the sentence to complete the logic.","jlpt":"N3"},{"tip":"While this often means'is doing'(progressive), for change-of-state verbs like つく (to attach), it describes the current state (it is currently attached).","jlpt":"N4","meaning":"Describes a continuing state that resulted from a past action.","pattern":"Te-form + いる","example":"カラスのフンが白くついているのが見える。"},{"tip":"Since you cannot truly know another person's internal feelings, you use'garu'to describe the'appearing state'of their emotions.","jlpt":"N3","meaning":"Suffix added to an adjective to indicate that someone else is showing outward signs of feeling that emotion.","pattern":"I-adjective + がる","example":"夕方になると気味悪がって誰も近づかなくなった。"},{"jlpt":"N3","tip":"When you add か to the end of せい, it implies that you are not 100% sure if that is the reason, but you suspect it is.","pattern":"Noun + せいか","meaning":"Used to indicate a cause that leads to a negative or undesirable result.'Perhaps because of...'","example":"しかし今日は時間が遅いせいか、一羽も見えない。"}],[{"jlpt":"N4","tip":"Use this when you have a logical reason for your conclusion. It implies \"it ought to be.\"","example":"死体しかないはずだ。","pattern":"Dictionary form + はず","meaning":"An expectation or strong belief that something should be the case."},{"tip":"It emphasizes that whatever follows is the absolute only thing. Remember to always pair it with a negative verb form.","jlpt":"N5","meaning":"Nothing but; only (used with a negative verb).","example":"死体しかないはずだ。","pattern":"～しか～ない"},{"pattern":"Dictionary form + ことにする","example":"はしごを登ることにした。","meaning":"To decide on something; to make a choice.","tip":"Use this version when the decision is made by the person themselves, rather than an outside force.","jlpt":"N4"},{"pattern":"Volitional form + と思う","example":"夜を明かそうと思った。","meaning":"Thinking of doing or intending to do an action.","tip":"This uses the Volitional form form (e.g. 食べよう, 行こう) to express an internal plan or intention.","jlpt":"N4"},{"tip":"Pair this with \"how,\"\"what,\"or \"where\"to ask for instructions or a path forward.","jlpt":"N4","example":"どうやって生きていけばいいのか分からず","pattern":"Conditional form + ばいい","meaning":"Should; it would be good if... (standard way to ask for advice)."},{"example":"クビにされた。","pattern":"Passive form + れる / られる","meaning":"Passive voice; indicates an action done to the subject.","jlpt":"N4","tip":"In this text, it shows the man was the victim of being fired (クビ) by his master."},{"example":"分からず、途方に暮れていた。","pattern":"Plain negative + ずに","meaning":"Without doing; the literary equivalent of 「～ないで」.","tip":"This is common in written stories. Simply replace the 「ない」 of a negative verb with 「ず」. For 「する」, it becomes 「せず」.","jlpt":"N3"}],[{"tip":"Use these for things you can see/hear without trying, unlike 見る or 聞く which imply intention.","jlpt":"N4","example":"誰かが火をともしているのが見えた。","meaning":"Indicates that a sensory perception (seeing/hearing) is happening spontaneously or naturally.","pattern":"～が見える / ～が聞こえる"},{"meaning":"Doing an action without doing something else (similar to ～ないで).","example":"足音を立てずに一番上まで登り...","pattern":"Plain negative + ずに","jlpt":"N3","tip":"This is a formal way to say'without doing'. Remember that する becomes せずに."},{"jlpt":"N4","tip":"Use の instead of こと when the main verb involves direct perception like'see','hear', or'wait'.","pattern":"Dictionary form + の","example":"死体の中に、一人の人間がうずくまっているのを見たからだ。","meaning":"Turns a verb phrase into a Noun so it can be the object of a sentence."},{"pattern":"Clause + からだ","example":"一人の人間がうずくまっているのを見たからだ。","meaning":"Used at the end of a sentence to state a reason or explanation.","jlpt":"N4","tip":"This is a direct way to provide a reason for a previously mentioned situation. In casual speech, it often becomes ～から。"},{"tip":"Attach this to the ます-stem of a verb. It focuses on the start of a continuous process.","jlpt":"N4","meaning":"Indicates the beginning of an action.","example":"髪の毛を一本ずつ抜き始めたのだ。","pattern":"Masu-stem + 始める"},{"tip":"This gives the sentence an explanatory tone, often used when revealing the background or reason for something.","jlpt":"N3","meaning":"Used for emphasis or to provide an explanation/clarification of a situation.","example":"髪の毛を一本ずつ抜き始めたのだ。","pattern":"Dictionary form + のだ"},{"meaning":"Indicates performing an action deeply, thoroughly, or into something.","example":"若い女の死体の顔をのぞき込んでいた。","pattern":"Masu-stem + 込む","jlpt":"N3","tip":"Common with verbs of movement (like 飛び込む) or observation (like のぞき込む) to show depth or intensity."}],[{"example":"刀を突きつけた。","meaning":"Object marker particle indicating the target of a verb's action.","jlpt":"N5","pattern":"Noun + を","tip":"Always follows the Noun that is being acted upon. In this text, it connects the sword (刀) to the action of thrusting (突きつけた)."},{"meaning":"To attempt to do something or be about to do something.","example":"逃げようとしたが","pattern":"Volitional form + とする","jlpt":"N4","tip":"Uses the Volitional form form of the verb. It implies an attempt that might be interrupted or may not succeed."},{"example":"震えながら","meaning":"While doing something; indicates two actions happening simultaneously by the same person.","tip":"Attach this to the stem of the verb (the part before ます). The main action comes after the ながら Clause.","pattern":"Masu-stem + ながら","jlpt":"N4"},{"tip":"When modifying a Noun (like 憎しみ), use に対する. When modifying a verb, use に対し or に対して.","jlpt":"N3","pattern":"Noun + に対する","meaning":"Towards; regarding; in contrast to. Expresses an attitude or action directed at someone or something.","example":"老婆に対する激しい憎しみ"},{"example":"怒りだと言ってもいい。","meaning":"It is okay to say...; one might even say...","pattern":"Clause + と言ってもいい","jlpt":"N3","tip":"Used to provide a strong classification or to suggest that a certain description is acceptable or accurate."},{"tip":"もし reinforces the \"if\"condition, while だろう at the end shows that the result is an assumption or prediction.","jlpt":"N3","pattern":"Plain past + ら","meaning":"If (conditional) ... then probably (conjecture). Usually used for hypothetical or uncertain situations.","example":"もしこの時、誰かが「飢え死にするか、泥棒になるか」と聞いたら、男は迷わず飢え死にを選んだだろう。"},{"pattern":"Plain negative + ずに","jlpt":"N3","tip":"This is a formal/literary version of ～ないで. To form it, change the ～ない ending to ～ず. For する, use せず.","example":"迷わず飢え死にを選んだ","meaning":"Without doing; used to describe an action performed without a specific preceding action."}],[{"pattern":"Dictionary form + かもしれない","tip":"It is used for subjective guesses. In casual speech, the final だ or です is omitted, leaving just しれない.","jlpt":"N4","meaning":"Maybe; might; perhaps (expresses a possibility)","example":"悪いことかもしれない"},{"meaning":"Nothing but; only; just (indicates a large amount or frequency of something)","example":"悪いことをしてきた人間ばかりだ","tip":"When used after the て-form of a verb, it means someone is'doing nothing but'that specific action.","pattern":"Dictionary form + ばかり","jlpt":"N3"},{"tip":"When the verb before it is in the Dictionary form, it indicates a conscious purpose or goal.","pattern":"Dictionary form + ために","jlpt":"N4","meaning":"For the purpose of; in order to","example":"生きるために"},{"pattern":"Plain negative + ければ","tip":"This is the'if'condition for negative verbs. Replace the い in ない with ければ.","jlpt":"N4","meaning":"If not; unless (negative conditional)","example":"そうしなければ飢え死にしていたからだ"},{"example":"大目に見てくれるだろう","meaning":"Probably; I think (expresses a conjecture or polite push for agreement)","jlpt":"N4","tip":"This is the Dictionary form of でしょう. Use it when you are fairly sure about something but not 100% certain.","pattern":"Dictionary form + だろう"},{"meaning":"To do something completely away / finish doing (verb suffix)","example":"完全に消え去っていた","tip":"When 去る is attached to the stem of a verb, it emphasizes the action of moving away or something disappearing completely.","pattern":"Masu-stem + 去る","jlpt":"N3"}],[{"pattern":"～な / ～だな","meaning":"Confirmation or agreement particle used at the end of a sentence.","example":"本当にそうだな。","jlpt":"N5","tip":"It functions similarly to ね but is more casual and often sounds more masculine or assertive."},{"example":"恨むなよ。","pattern":"Dictionary form + な","meaning":"Negative imperative (prohibition) meaning \"don't do...\".","jlpt":"N4","tip":"Adding よ after な softens the command slightly, but it still sounds very strong and blunt."},{"meaning":"Expresses a conditional \"if... not\", used to show a necessary consequence.","pattern":"Plain negative + ければ","example":"そうしなければ飢え死にする体なのだ。","tip":"This is the Conditional form of the negative ない. In speech, this is often shortened to なきゃ.","jlpt":"N4"},{"tip":"When following a Noun or Na-adjective, you must add な before のだ. It adds a tone of conviction or explanation.","jlpt":"N4","meaning":"The explanatory particle used to provide a reason, explanation, or emphasize a fact.","pattern":"Dictionary form + のだ","example":"飢え死にする体なのだ。"},{"tip":"This often describes a scene where someone is just starting an action or a physical effort that might not succeed.","jlpt":"N3","example":"すがりつこうとする老婆","meaning":"Indicates an attempt or intention to perform an action. Expresses \"trying to...\"or \"about to...\".","pattern":"Volitional form + とする"},{"tip":"When a question word like どこ (where) or 何 (what) is used, the sentence ends in か even if it is in the middle of a larger sentence.","jlpt":"N4","meaning":"Turns a question into a Noun Clause so it can function as the subject or object of a sentence.","pattern":"Question word + ～か","example":"男がどこへ行ったのかは、誰も知らない。"}]],"original":[[{"tip":"Use this whenever you want to say things like'I like doing X'or'I saw X happening'.","pattern":"Dictionary form + の (nominalizer)","jlpt":"N5","meaning":"The'no'particle turns a verb/Clause into a Noun (nominalization) so it can be used with particles like'wo'.","example":"雨のふるのを眺めていた。"},{"example":"地震とか辻風とか火事とか・・・","meaning":"Used to list multiple examples non-exhaustively (like'A, B, and so on').","jlpt":"N4","pattern":"Noun + とか〜とか","tip":"Unlike'to'which is an exhaustive list,'toka'implies there are other things not mentioned."},{"meaning":"Expresses what should be natural, expected, or typical in a given situation.","example":"二三人はありそうなものである。","tip":"This adds a nuance of'it is only natural that'or'one would expect that'based on social norms or logic.","jlpt":"N3","pattern":"Dictionary form + そうなものだ"},{"example":"朱雀大路にある以上は","meaning":"Now that/Since; expresses a strong cause or condition where a certain result is natural or required.","jlpt":"N2","pattern":"Noun + 以上（は）","tip":"This pattern is often used when a decision has been made or a fact is established, leading to a natural consequence."},{"meaning":"Indicates that an action or state has started but is not yet finished (half-way through).","example":"崩れかかった、そうしてその崩れ目に・・・","jlpt":"N2","pattern":"Masu-stem + かかる","tip":"Use this for processes that take time to complete, like a building falling apart or a person starting to say something."},{"example":"誰でも気味を悪るがって","meaning":"Appearing to feel a certain emotion or sensation (used for third-person subjects).","pattern":"I-adjective + がる","jlpt":"N3","tip":"Japanese speakers rarely use direct feeling words (like'scared'or'cold') for others; they use'garu'to describe the outward appearance of that feeling."},{"example":"死人の肉を、啄みに来るのである。","meaning":"Indicates the purpose of going or coming to a place.","jlpt":"N5","pattern":"Masu-stem + に（行く・来る）","tip":"Drop the'masu'from a verb and add'ni'plus a movement verb to express'going to do'something."}],[{"pattern":"～ても / ～でも","jlpt":"N4","meaning":"Even if; even though (indicates a hypothetical or factual concession)","tip":"Observe how it attaches to the て-form of verbs or adjectives to show that the result is unaffected by the condition.","example":"雨がやんでも"},{"pattern":"Dictionary form + はず","example":"帰る可き筈である","jlpt":"N4","meaning":"Expected to; supposed to (expresses a strong expectation based on logic or common sense)","tip":"Use this when you have a logical reason to believe something is true. Note that the text uses the old-style べき (represented as 可き)."},{"pattern":"次第に","jlpt":"N4","tip":"This is a more formal version of だんだん and is common in literature and news.","meaning":"Gradually; little by little (indicates a progressive change)","example":"夕闇は次第に空を低くして"},{"example":"余波にほかならない","meaning":"Nothing but; none other than (used to identify something strongly)","tip":"This adds a strong emphatic tone to a statement, often used in written conclusions.","jlpt":"N2","pattern":"Noun + にほかならない"},{"pattern":"Noun + あげくに","example":"同じ道を低徊した揚句に","jlpt":"N2","tip":"Think of this as'after all that trouble, the result was...'– it often emphasizes the mental or physical struggle preceding the outcome.","meaning":"After; in the end (usually implies a long process with a negative or exhaustive result)"},{"pattern":"Noun + よりほかに（仕方がない）","jlpt":"N3","meaning":"Have no choice but to; no other way except for...","tip":"This expresses a situation where options have run out. Only the action before より remains possible.","example":"盗人になるよりほかに仕方がない"}],[{"pattern":"～てしまう / ～てしまった","jlpt":"N4","meaning":"Expresses completion of an action or a sense of regret/finality.","tip":"In this context, it emphasizes that the crickets are completely gone, leaving the scene lonely.","example":"どこかへ行ってしまった。"},{"pattern":"Masu-stem + ながら","example":"頸をちぢめながら","jlpt":"N4","meaning":"Indicates two actions happening simultaneously by the same person.","tip":"The Stem always precedes this. It focuses on the second action as the main one."},{"pattern":"Noun + ほど","example":"火桶が欲しいほどの寒さである。","jlpt":"N3","tip":"Use this when you want to say something is'to the extent that...'or'so much so that...'.","meaning":"Indicates the degree or extent of something by providing an example."},{"pattern":"Masu-stem + そう","jlpt":"N4","meaning":"Potential form (can sleep) combined with the appearance of possibility (seems like).","tip":"It combines the Potential form Potential form (られる) with the'looks like'guess (そう).","example":"一晩楽にねられそうな所"},{"example":"鞘走らないように気をつけながら","tip":"This is used when setting a goal for an action or maintaining a specific habit/caution.","meaning":"To take care to do (or not do) something, or to ensure a certain state.","jlpt":"N3","pattern":"Dictionary form + ように"},{"pattern":"Dictionary form + ばかり","meaning":"Indicates that there is nothing but a certain thing, or that something happens exclusively.","tip":"Here it shows the protagonist's assumption that the tower contained'only'or'nothing but'corpses.","jlpt":"N4","example":"死人ばかりだと高を括っていた。"},{"example":"火をそこここと動かしているらしい。","jlpt":"N4","tip":"It is often used when you see or hear something that leads you to a logical conclusion.","meaning":"Expresses a conjecture based on objective evidence or information gathered.","pattern":"Dictionary form + らしい"},{"pattern":"Masu-stem + つめる","example":"一番上の段まで這うようにして上りつめた。","jlpt":"N2","tip":"When attached to movement verbs, it implies a difficult or exhaustive effort to reach the final point.","meaning":"Indicates doing something to the very end or reaching a limit."}],[{"example":"死骸の中に蹲っている人間を見た。","tip":"When used with action verbs, it shows'is doing'. With change-of-state verbs like 蹲る, it shows a completed action whose result remains.","meaning":"Expresses an ongoing action or a current state.","jlpt":"N5","pattern":"Te-form + いる"},{"jlpt":"N4","pattern":"Masu-stem + 始める","meaning":"Added to the stem of a verb to indicate the start of an action.","example":"その長い髪の毛を一本ずつ抜きはじめた。","tip":"Attach this to the ます-stem of any verb to say you'started'doing that action."},{"meaning":"Used to describe something by comparing it to something else (metaphor or likeness).","tip":"Think of this as'like'or'as if'. It usually follows a Dictionary form verb or a Noun plus の.","example":"猿の子の虱をとるように","pattern":"Dictionary form + ように","jlpt":"N4"},{"pattern":"Noun + に従って","jlpt":"N2","example":"髪の毛が、一本ずつ抜けるのに従って","tip":"This indicates a simultaneous change. As one thing progresses, another thing changes along with it.","meaning":"As X happens, Y happens in accordance or proportion to it."},{"jlpt":"N2","pattern":"Clause + は言うまでもない","tip":"This is a formal way to state that something is so self-evident or certain that it doesn't need to be mentioned.","example":"老婆が驚いたのは云うまでもない。","meaning":"It goes without saying that... / It is obvious that..."},{"meaning":"Expression meaning'must not'or'should not'. A stiff, literary prohibition.","example":"それだけで既に許すべからざる悪であった。","tip":"This is the attributive form of ～べからず. It is very formal and usually found in literature or old legal texts to describe things that are'unforgivable'or'forbidden'.","jlpt":"N1","pattern":"Dictionary form + べからざる"},{"jlpt":"N1","pattern":"Plain negative + ぬ","example":"云わぬと、これだぞよ。","tip":"While common in certain dialects/proverbs, in literature it provides a classical or archaic tone. In this text, 云わぬ means 云わない.","meaning":"The classical negative form equivalent to ～ない."}],[{"jlpt":"N4","example":"死人の髪の毛を抜くと云う事は","tip":"Use this to turn a sentence or a verb phrase into a Noun Clause to discuss it as a topic.","meaning":"The thing called; the act of (used to define or emphasize a Noun or concept)","pattern":"Noun + という + Noun"},{"tip":"Attach さえ to the Noun or the stem of the verb, and put the following verb in its conditional (ば) form.","pattern":"～さえ～ばいい","meaning":"If only; as long as (indicates the minimum requirement for something to happen)","jlpt":"N3","example":"何をして居たのだか、それを己に話しさえすればいいのだ。"},{"meaning":"Like; similar to (describes something by comparing it to another Noun)","pattern":"Noun + のような","tip":"Use ような before nouns and ように before verbs or adjectives to create vivid metaphors.","example":"鴉の啼くような声","jlpt":"N3"},{"tip":"であろう is the formal, literary version of だろう, commonly seen in novels and historical texts.","meaning":"Probably; I wonder (expresses conjecture or a polite opinion)","pattern":"Dictionary form + であろう","jlpt":"N3","example":"その気色が、先方へも通じたのであろう。"},{"jlpt":"N2","example":"死骸の頭から奪った長い抜け毛を持ったなり","tip":"It indicates that a person does something and stays in that state, often implying unexpected continuity. It is similar to っぱなし but more formal.","pattern":"Plain past + なり","meaning":"Remaining in a certain state; just as it is (without changing)"},{"meaning":"If one does not; unless (classical/literary negative conditional)","pattern":"Plain negative + ねばならぬ","tip":"This is an old form of ～なければ. In modern Japanese, it survives mostly in the set phrase ～ねばならない (must).","example":"せねば、饑死をするのじゃて","jlpt":"N1"},{"meaning":"Would have been (counter-factual conditional or past conjecture)","pattern":"Plain past + ことであろう","tip":"This sophisticated ending describes a situation that did not happen but could have, or makes a strong guess about the past.","example":"今でも売りに往んでいた事であろ。","jlpt":"N1"}],[{"jlpt":"N4","tip":"The main action comes after the ～ながら Clause. The verb before it must be in the stem form (ます-form minus ます).","meaning":"While doing; simultaneous actions","example":"太刀の柄を左の手でおさえながら","pattern":"Masu-stem + ながら"},{"pattern":"Noun + ほど","example":"考える事さえ出来ないほど","tip":"Used to describe the degree of a state by providing a dramatic example. When used with a verb, it is directly attached to the Dictionary form.","meaning":"To the extent that; so much so that","jlpt":"N3"},{"example":"迷わなかったばかりではない。","pattern":"Dictionary form + ばかりか","jlpt":"N3","meaning":"Not only... but also...","tip":"It emphasizes that something is not limited to one thing but extends to others. In the text, it is used with the negative form to show how decisive the character became."},{"example":"己が引剥をしようと恨むまいな。","pattern":"Dictionary form + まい","jlpt":"N2","meaning":"Will probably not; intend not to (Negative Volitional form)","tip":"This is a literary or formal way to express a negative intention (I will not) or a negative guess (probably not). It is common in classic literature like this story."},{"meaning":"Only; nothing but; simply","tip":"When used at the end of a sentence after a Noun or verb, it emphasizes that a certain state is all that exists, often implying a sense of emptiness or limitation.","jlpt":"N2","pattern":"Dictionary form + ばかりである","example":"黒洞々たる夜があるばかりである。"},{"meaning":"To try to; to be about to do something","tip":"Uses the Volitional form form of the verb. It describes an attempt to do something or a state just before an action occurs.","jlpt":"N3","pattern":"～ようとする / ～おうとする","example":"反対な方向に動こうとする勇気である。"},{"jlpt":"N1","tip":"In this older literary context, 体 means \"appearance\"or \"situation.\"It functions like わけだ or のだ to explain a reason or state of being.","meaning":"The situation is...; the context is... (Noun usage)","example":"飢死をする体なのだ。","pattern":"Noun + 体 (てい) だ"}]]},"hashire-merosu":{"simplified":[[{"example":"奥さんもいません","tip":"When used with a negative verb, it emphasizes 'not even one' or 'not at all' depending on context. here it lists multiple absences.","jlpt":"N5","pattern":"Noun + も + Plain negative/Masu-form negative","meaning":"Expresses total negation when used with a negative verb, often replacing specific particles or listing absence"},{"meaning":"Indicates a purpose or goal (in order to do something) or a reason (because of)","pattern":"Dictionary form + ために","example":"買うために","tip":"When specifically following a Dictionary form verb, it almost always expresses purpose.","jlpt":"N4"},{"jlpt":"N4","example":"倒さなければならない","tip":"The final 'i' of the negative 'nai' is removed to create 'nakereba'. It is often used for duties and firm resolutions.","pattern":"Plain negative + なければならない","meaning":"Expresses a strong sense of obligation or necessity (must do)"},{"jlpt":"N4","example":"買った後","tip":"Make sure to use the Plain past (Plain past) to show the action is completed before the next one starts.","pattern":"Plain past + 後","meaning":"Indicates that one action takes place after another action has finished"},{"meaning":"Expresses an intention, plan, or expectation to do something","pattern":"Dictionary form + つもりだ","jlpt":"N4","example":"会いに行くつもりでした","tip":"This indicates a firm intention in the speaker's mind, regardless of whether the plan has been officially scheduled."},{"example":"歩いていると","tip":"When used as a conditional 'when/if' for discovery, the second Clause is usually something the subject noticed, not a command or request.","jlpt":"N4","pattern":"Dictionary form + と","meaning":"Indicates that one action or event occurs immediately after another, often resulting in a discovery or unexpected result"},{"jlpt":"N4","tip":"This is a very common way to introduce proper nouns or concepts that the listener might not know.","example":"セリヌンティウスという大切な友だち","meaning":"Used to define or identify something by its name (called... or named...)","pattern":"Noun + という + Noun"}],[{"pattern":"Masu-stem + てくる","meaning":"Indicates that an action or feeling comes forth or starts to appear from within","jlpt":"N4","example":"短い刀が出てきました","tip":"In this context, it describes the physical emergence of the dagger from the pocket towards the speaker's perspective."},{"example":"怒ったまま","jlpt":"N4","tip":"It often implies that the state is unusual or persists longer than expected.","meaning":"To do something while a certain state remains unchanged","pattern":"Plain past + まま"},{"meaning":"Indicates intention or plan","pattern":"Dictionary form + つもりだ","tip":"Use this to express what you intend to do. The past tense version implies a prior intention.","example":"何をするつもりだったか？","jlpt":"N4"},{"meaning":"Used to indicate a purpose or objective","pattern":"Dictionary form + ために","jlpt":"N4","example":"町を、あなたから助けるためだ","tip":"The particle に is often omitted when it ends a sentence or acts as a reason."},{"meaning":"Expresses inability or impossibility to do an action","pattern":"Dictionary form + ことができる","tip":"This is the standard way to form the potential (can/cannot) using a Noun-modifying Clause.","example":"人の心は信じることができない","jlpt":"N4"},{"example":"人を疑うのは","jlpt":"N4","tip":"This allows you to treat a whole phrase like a Noun so you can describe it as 'bad', 'difficult', etc.","meaning":"Nominalizes a verb to turn an action into a subject or object","pattern":"Dictionary form + のは"},{"pattern":"Te-form + ほしい","meaning":"Used to express a desire for someone else to do something","jlpt":"N4","example":"命を助けてほしいと言いません","tip":"The target of the request (the person you want to do the action) is usually marked with the particle に."},{"tip":"Think of this as 'the [Noun] called [Name]'. It is essential for introducing new terms.","jlpt":"N4","example":"セリヌンティウスという私の友だち","meaning":"Used to define or name something or someone","pattern":"Noun + という + Noun"},{"jlpt":"N4","example":"もし私が信じられないなら","tip":"なら focuses on the context provided by the other person or a specific situation. Pairs frequently with もし for emphasis.","pattern":"もし + Clause + なら","meaning":"Used to introduce a hypothetical condition or supposition"},{"example":"殺してやろう","jlpt":"N4","tip":"In modern Japanese, be careful using this with people as it can sound condescending or rude. Here, the King is being cruel.","pattern":"Te-form + やる","meaning":"To do something for someone (often used when the recipient is of lower status or an animal, or in a mocking/aggressive tone)"},{"meaning":"Indicates a deadline or a point in time by which an action must be completed","pattern":"Noun + までに","tip":"Don't confuse this with まで (until), which implies a continuous action. までに is for a one-time deadline.","example":"三日目の夕方までに","jlpt":"N4"}],[{"example":"顔を赤くしました","tip":"When using an I-adjective with a verb of change or action like する, the final い changes to く. For Na-adjectives, use に instead.","jlpt":"N5","meaning":"To make something into a certain state or change its appearance (to make red)","pattern":"I-adjective (remove ～い) + く + する"},{"tip":"While できる often means 'can do', in this context it refers to the completion or readiness of a task or object.","example":"準備ができていません","pattern":"Noun + が + できる","meaning":"To be completed or ready","jlpt":"N4"},{"pattern":"Masu-stem + たい","jlpt":"N4","meaning":"Expressing a personal desire to do an action (want to)","tip":"This form is only used for the speaker's own desires. To describe someone else's desire, different endings like ～たがっている are used.","example":"ずっとここにいたい"},{"pattern":"Plain negative (remove ～ない) + なければなりません","jlpt":"N4","meaning":"Must do; to have an obligation to do something","tip":"This is the formal way to express necessity. In casual speech, it is often shortened to ～なきゃ or ～なくちゃ.","example":"行かなければなりません"},{"tip":"When used with a Noun, it denotes the beneficiary of the action. When used with a Dictionary form verb, it indicates a purpose or goal.","example":"友だちのために","pattern":"Noun + のために","jlpt":"N4","meaning":"For the sake of; for the benefit of someone or something"}],[{"tip":"While it traditionally reflects a speaker doing something for a lower status being, in this context it shows Melos's strong determination versus the King.","example":"見せてやる","jlpt":"N4","pattern":"Te-form + やる","meaning":"To do something for someone (usually with a sense of strong intent or looking down on the receiver)"},{"meaning":"To start or burst into an action","jlpt":"N4","pattern":"Masu-stem + 出す","tip":"This is used for actions that begin suddenly or outwardly.","example":"走り出しました"},{"tip":"Always use this when the outcome is undesirable. If the outcome is good, use ～のおかげで instead.","example":"雨のせいで","pattern":"Noun + のせいで","jlpt":"N3","meaning":"Because of; due to (used for a negative result)"},{"example":"泣きながら","tip":"The primary action comes second in the sentence; the 'while' action is secondary.","jlpt":"N4","pattern":"Masu-stem + ながら","meaning":"While doing; performing two actions simultaneously"},{"meaning":"When/If; indicates that the following action or event happens almost immediately after the first","jlpt":"N4","pattern":"Dictionary form + と","tip":"This specific use of 'to' suggests a natural consequence or a discovery of what happened next.","example":"川を渡ると"},{"meaning":"Nothing but; only (used with a negative verb)","pattern":"Noun + しか + Negative verb","jlpt":"N5","tip":"Always pair this with a negative verb to emphasize that nothing else exists or is possible.","example":"命しかありません"},{"meaning":"To become (a certain state) / to reach the point where one can no longer do something","pattern":"Plain negative (ない -> くなる) + なる","jlpt":"N4","example":"足が動かなくなりました","tip":"Change the 'i' in 'nai' to 'ku' before adding the verb 'naru' to show a change in state."},{"meaning":"To one's surprise; strangely enough (emphasizing the speaker's feeling)","tip":"This structure is used at the beginning of a Clause to set the emotional tone for the fact that follows.","example":"不思議なことに","jlpt":"N3","pattern":"Na-adjective + なことに"},{"meaning":"Must; have to; it is necessary to do","pattern":"Plain negative (remove い) + ければならない core","jlpt":"N4","example":"助けなければならない","tip":"This is a formal and strong way to express obligation. In casual speech, it often shortens to ～なきゃ."}],[{"example":"風のように","jlpt":"N4","tip":"Use this for metaphors or and analogies. When modifying a verb, use に; when modifying a Noun, use な.","pattern":"Noun + のように","meaning":"To do something in a way that resembles or mimics a Noun; like..."},{"example":"沈むところでした","meaning":"About to do something; on the verge of occurring.","pattern":"Dictionary form + ところだ","jlpt":"N4","tip":"This expresses a point in time just before an action starts. It is often used with phrases like 'just now' or 'barely'."},{"pattern":"Dictionary form + ところだった/でした","meaning":"Was just about to happen (often implies a narrow escape or a critical moment).","jlpt":"N4","tip":"When used in the past tense, it often describes a situation that almost occurred but was prevented at the last second.","example":"殺されるところでした"}],[{"meaning":"Used to make a request, meaning 'won't you do [something] for me?'","example":"私をあなたたちの友だちにしてくれないか。","jlpt":"N4","pattern":"Te-form + くれないか","tip":"This is a casual but direct way to ask for a favor. Adding か at the end makes it a question."},{"example":"あきらめようとしました。","meaning":"To try to do something or to be about to do something.","tip":"This expresses an attempt or an intention that was about to take place.","pattern":"Volitional form form + とする","jlpt":"N4"},{"jlpt":"N4","pattern":"Dictionary form + ことができない","tip":"This is the formal way to express inability, as opposed to using the potential verb form.","meaning":"Indicates that one is unable to do a certain action.","example":"抱きしめることができません。"},{"example":"あなたにたたかれないと","meaning":"Expresses a conditional 'if' or 'unless'—if the first action doesn't happen, the second cannot either.","tip":"When used with a negative verb, it often implies an indispensable condition for the following result.","pattern":"Plain negative + と","jlpt":"N4"},{"tip":"Use this when you want to treat an action like a Noun, such as for the subject or object of a sentence.","jlpt":"N4","pattern":"Dictionary form + こと","example":"人を信じることは嘘ではない。","meaning":"Turns a verb or Clause into a Noun phrase to discuss it as a topic or concept."},{"example":"恥ずかしくなって","meaning":"Indicates a change in state, meaning 'to become' or 'to start being'.","tip":"For Na-adjectives and Nouns, use になる instead of くなる.","pattern":"I-adjective (remove い) + くなる","jlpt":"N4"}]],"intermediate":[[{"pattern":"Plain negative (without ～ない) + なければならない","meaning":"Must; have to; indicates an obligation or necessity","jlpt":"N4","example":"倒さなければならない","tip":"This is the standard formal way to express obligation. In casual speech, it often shortens to ～なきゃ."},{"tip":"When used with a verb, the verb must be in the Dictionary form and represent a Volitional form action.","example":"買うために","jlpt":"N4","meaning":"In order to; for the purpose of","pattern":"Dictionary form + ために"},{"tip":"Use this to describe rules, schedules, or social arrangements rather than a personal willpower decision.","example":"迎えることになっていた","jlpt":"N4","pattern":"Dictionary form + ことになっている","meaning":"It has been decided that; it is scheduled to; expresses a decision made by others or a natural course of events"},{"pattern":"Dictionary form + つもりだ","meaning":"Intend to; plan to","tip":"This expresses a person's current intention or plan for the future.","jlpt":"N4","example":"訪ねるつもりだ"},{"tip":"Use this when you have a logical reason to believe something is true, often expressing surprise when the reality differs.","example":"にぎやかだったはずだ","jlpt":"N4","meaning":"Should be; expected to be; expresses a strong conviction based on evidence or logic","pattern":"Na-adjective + だったはずだ"},{"meaning":"While; during; while a certain state or action is continuing, a change occurs","pattern":"Te-form + いるうちに","example":"歩いているうちに","jlpt":"N3","tip":"It implies that something happened naturally or unexpectedly before the initial state ended."},{"tip":"This points to a target of an action, attitude, or feeling. In this text, it shows Melos's reaction 'towards' evil.","example":"悪いことに対しては","jlpt":"N3","pattern":"Noun + に対して","meaning":"Towards; regarding; in contrast to"},{"pattern":"Dictionary form + ように + 注文/命令/頼む","meaning":"To command/request (someone) to do (something)","jlpt":"N3","example":"差し出すように命令しています","tip":"This is used for indirect quotes of commands or requests, acting as a softer way to report what someone was told to do."},{"jlpt":"N2","example":"生かしておくわけにはいかない","tip":"This is not about physical ability, but rather having a strong sense of duty or social pressure that prevents an action.","pattern":"Dictionary form + わけにはいかない","meaning":"Cannot (for social, moral, or psychological reasons); must not"}],[{"tip":"While it often describes future plans, in this context it is used to question the character's underlying intent.","example":"何をするつもりだったか","pattern":"Dictionary form + つもりだ","meaning":"Expresses an intention or plan to do something.","jlpt":"N4"},{"tip":"In narrative writing, this often adds an emotional weight to the event, suggesting the situation got out of hand.","example":"騒ぎになってしまった","pattern":"Te-form + しまう","jlpt":"N4","meaning":"Indicates that an action was completed, often with a sense of regret, accident, or unintended consequence."},{"tip":"This is more formal and authoritative than ～てはだめ.","example":"信じてはいけない","pattern":"Te-form + はいいけない","meaning":"Expresses a prohibition or a strong command not to do something.","jlpt":"N4"},{"pattern":"Dictionary form + ために","jlpt":"N4","meaning":"Indicates a purpose, objective, or the reason why something is done.","tip":"The particle に is often omitted when modifying a Noun or ending a sentence fragment.","example":"自分の地位を守るためか"},{"example":"死ぬ覚悟ができている","tip":"While ～ている is basic aspect, when combined with できた (to be ready/prepared), it functions as a functional phrase meaning \"to be prepared for.\"","jlpt":"N3","meaning":"Indicates a state that has been achieved and is currently persisting.","pattern":"Te-form + いる"},{"example":"荷物を背負ったまま","tip":"Use this when an action is performed without changing a previous condition that would normally be altered.","jlpt":"N3","meaning":"Indicates that a state continues unchanged while another action takes place.","pattern":"Plain past + まま"},{"pattern":"Question word + でも","jlpt":"N3","meaning":"Indicates \"no matter what/who/where,\" emphasizing that the condition applies to any case.","tip":"It is often used with potential verbs to show that anyone is capable of the action.","example":"どんなきれいなことでも言える"},{"meaning":"The Masu-stem of a verb is used to connect sentences, functioning like the Te-form but in a more formal or written style.","jlpt":"N3","pattern":"Masu-stem + (comma)","example":"結婚式を挙げさせ","tip":"This is called the Ren'youkei connection and is very common in literature to provide rhythm."},{"pattern":"Dictionary form + はずがない","meaning":"Expresses a strong conviction that something is impossible or definitely won't happen.","jlpt":"N3","tip":"This is much stronger than a simple negative and implies the speaker has logical reasons for their doubt.","example":"帰ってくるはずがない"},{"jlpt":"N3","meaning":"To act as if something is true when it is not; to pretend.","pattern":"Plain past + ふりをする","example":"騙されたふりをして","tip":"It is often used when the subject is consciously deceiving others or themselves."},{"jlpt":"N3","meaning":"Indicates doing something for someone else (or against them) from the speaker's perspective, often implying a lower status or a harsh intent in this context.","pattern":"Te-form + やる","example":"思い知らせてやりたい","tip":"While it can mean \"doing a favor\" for animals/plants, here it expresses the King's aggressive intent toward the \"honest people.\""},{"jlpt":"N3","meaning":"Indicates that a certain action or state is sufficient, often used to give permission or express indifference/sarcasm.","pattern":"Conditional ば + いい","example":"うぬぼれていればいい","tip":"When used by an antagonist, it often carries a tone of \"Fine, go ahead and do that (I don't care).\""}],[{"meaning":"Used to express that something must be done or is necessary.","jlpt":"N4","pattern":"Plain negative (drop ～ない) + なければならない","example":"町へ行かなければならない。","tip":"In speech, this is often shortened to なきゃ or なければ."},{"pattern":"Volitional form form + とする","jlpt":"N4","meaning":"To try to do something or to be about to attempt an action.","tip":"This pattern focuses on the attempt or the immediate start of the action.","example":"無理に笑おうとした。"},{"pattern":"Masu-stem + 出す (だす)","meaning":"To suddenly start an action. Often used for natural phenomena or activities.","jlpt":"N4","tip":"While ～始める refers to the general start of a process, ～出す emphasizes the suddenness or outward burst of an action.","example":"雨が降り出し"},{"example":"知らせてきなさい。","tip":"Avoid using this with superiors; it is strictly top-down.","jlpt":"N4","meaning":"A polite but firm command, often used by parents or teachers.","pattern":"Masu-stem + なさい"},{"meaning":"Expresses a guess, conjecture, or probability. It is the Dictionary form of ～でしょう.","jlpt":"N4","pattern":"Dictionary form + だろう","example":"雨も弱まっているだろう。","tip":"When used with a falling intonation, it is a statement of probability; with rising intonation, it asks for confirmation."},{"pattern":"Noun/Clause + かのように / かのような","jlpt":"N3","meaning":"To behave as if something were true, or to describe something that looks like something else.","tip":"Use かのように to modify verbs and かのような to modify nouns.","example":"息もしていないかのような深い眠りに落ちてしまった。"},{"pattern":"Masu-stem + 始める (はじめる)","meaning":"To start doing an action.","jlpt":"N5","tip":"Unlike ～出す, this is the standard way to express the beginning of a continuous action.","example":"仕事を始めていた。"},{"pattern":"Noun (Time) + ぶり","jlpt":"N3","meaning":"Indicates that something happens for the first time in a specific duration of time.","tip":"Commonly used for physical reunions or events that haven't occurred for a long time.","example":"２年ぶりに再会した。"},{"example":"なかなか承知してくれない。","tip":"In an affirmative sentence, it means 'quite' or 'very', but with a negative verb, it means 'not easily'.","meaning":"Used with a negative verb to indicate that something is difficult to achieve or doesn't happen as easily as expected.","jlpt":"N4","pattern":"なかなか + Plain negative"}],[{"example":"これからすぐに出発すれば、約束の時間には十分間に合う。","jlpt":"N4","tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It is often used for logical results or requirements.","meaning":"Used to express a condition or hypothetical situation (if/when).","pattern":"Dictionary form + ば"},{"tip":"When used with a Dictionary form verb, it indicates a goal or intent. With a Noun, add 'no' between the Noun and 'tame'.","example":"身代わりの友を救うために走るのだ。","jlpt":"N4","pattern":"Dictionary form + ために/ための","meaning":"Expresses purpose or reason (in order to / for the sake of)."},{"jlpt":"N4","example":"走らなければならない。","tip":"Often shortened to 'nakereba' or 'nakucha' in casual speech. It literally means 'if not done, it is not become / not okay'.","meaning":"Indicates obligation or a necessity (must / have to).","pattern":"Plain negative + なければならない/なければならない"},{"pattern":"Dictionary form + ようだ","meaning":"Indicates a subjective judgment or appearance based on information (appears / looks like).","tip":"It expresses how things seem to the speaker based on their senses or context. For Nouns, use 'Noun + no + youda'.","example":"雨も少し弱まっているようだ。","jlpt":"N4"},{"pattern":"Dictionary form + ばいい","meaning":"Suggests a solution or gives permission (all you have to do is / it is okay to).","tip":"Literally means 'it would be good if you...'. Use it to show that a certain action is sufficient.","jlpt":"N4","example":"まっすぐに王の城へ行けばいいのだ。"},{"jlpt":"N4","example":"そんなに急ぐ必要もない。","tip":"Use the particle 'mo' instead of 'ga' to emphasize that 'even' that need is absent.","pattern":"Dictionary form + 必要がある/ない","meaning":"Indicates that a certain action is not required (no need to)."},{"tip":"The primary action comes second in the sentence. The 'nagara' part is the background action.","example":"自分を励ましながら走った。","jlpt":"N4","pattern":"Masu-stem + ながら","meaning":"Expresses two actions happening simultaneously by the same person (while)."},{"jlpt":"N3","example":"山を登りきってほっとした時","tip":"It adds the nuance of 'doing something completely' or 'to the limit', often implying effort.","pattern":"Masu-stem + きる/きって","meaning":"Indicates completing an action thoroughly or to the end."},{"jlpt":"N3","example":"日が傾きかけている。","tip":"Often used for states that are gradually changing or actions that are interrupted.","meaning":"Indicates an action that has started but is not yet finished (in the middle of / about to).","pattern":"Masu-stem + かける/かけている"},{"example":"私は決して君をだましたわけではない。","jlpt":"N3","tip":"Often paired with 'kesshite' (never) or 'zenbu' (all) to create a partial or strong negation of a conclusion.","pattern":"Clause + わけではない","meaning":"Used to clarify a misunderstanding or deny a specific inference (it does not mean that / it is not the case that)."},{"example":"君と私は運命を共にするのだから。","jlpt":"N3","tip":"Adding 'noda' or 'ndesu' makes the statement feel like an explanation of circumstances.","pattern":"Dictionary form + のだ/んだから","meaning":"An emphatic way to state a reason or provide an explanation."}],[{"pattern":"Masu-stem + 出す","tip":"Use this when something starts abruptly or moves from the inside to the outside, like a sudden rain or starting to run.","jlpt":"N4","example":"走り出した","meaning":"Indicates the sudden or natural start of an action or phenomenon"},{"tip":"When used with a verb, it emphasizes that the subject is doing that one thing to the exclusion of all else.","pattern":"Dictionary form + だけ","meaning":"Indicates that there is nothing else besides the stated action; 'only' or 'just'","example":"走るだけだった","jlpt":"N4"},{"meaning":"To be about to do something, or to be on the verge of happening","jlpt":"N4","example":"沈もうとしていた","pattern":"Volitional form form + とする","tip":"The progressive form ～としている emphasizes that the moment of change is imminent. Often used for natural phenomena like the sun setting."},{"meaning":"To do something 'like' or 'in the manner of' something else; an adverbial simile","jlpt":"N3","example":"風のように","pattern":"Noun + のように","tip":"Unlike のような which modifies nouns, のように modifies verbs and adjectives to describe the manner of an action."},{"tip":"Often used when you cannot explain logically why you feel a certain way but have a strong mental impression.","pattern":"Dictionary form + ような気がする","example":"なったような気がした","jlpt":"N3","meaning":"To have a feeling or hunch that something is the case, often used for subjective impressions"},{"pattern":"Dictionary form + につれて","tip":"This pattern implies a gradual, proportional change. Usually, both the cause and the effect involve a change in scale or intensity.","meaning":"As one thing happens, another change occurs in proportion or simultaneously","jlpt":"N3","example":"走るにつれて"},{"tip":"Combining the 'about to' Volitional form + とする with the 'moment' marker ところ highlights the critical timing of the scene.","pattern":"Volitional form form + としている + ところだ","example":"いよいよ槍を突き刺そうとしているところだった","jlpt":"N3","meaning":"States that someone is exactly at the point of performing an action (often right before it starts)"}],[{"example":"身代わりの友を殺すな！","meaning":"Strong negative imperative (Don't do...)","tip":"This is a very strong and blunt command used by men or in emergencies; do not use it with social superiors.","pattern":"Dictionary form + な","jlpt":"N4"},{"tip":"The form んだ is more common in speech, while のだ is used for written emphasis or dramatic declarations.","pattern":"Dictionary form + のだ","jlpt":"N4","example":"私は戻ってきたのだ！","meaning":"Focuses on the reason or gives an explanation for a situation"},{"jlpt":"N4","pattern":"Masu-stem + ながら","tip":"The main action always comes after the ながら Clause.","meaning":"Indicates two actions happening simultaneously by the same person","example":"メロスは叫びながら"},{"jlpt":"N4","pattern":"Plain negative + ければ / なければ","tip":"Often used to express a requirement or a necessary condition for a result.","meaning":"Expresses a conditional 'if' for a negative state or action","example":"君が私を殴ってくれなければ"},{"meaning":"To do something as a favor (for the speaker)","example":"殴ってくれなければ","jlpt":"N4","pattern":"Te-form + くれる","tip":"When the speaker asks for a favor using this, it implies gratitude or a humble request."},{"meaning":"Indicates reciprocal action (doing something to each other)","example":"抱き合う資格がない","pattern":"Masu-stem + 合う","jlpt":"N4","tip":"Always implies a mutual relationship where both parties are performing the action together."},{"meaning":"Expresses inability to do an action","example":"抱き合うことができない","jlpt":"N4","pattern":"Dictionary form + ことができない","tip":"This is a formal way to express potential, often focusing on situational inability rather than physical skill."},{"example":"すべてを理解したように","meaning":"Expresses a resemblance, an appearance, or 'as if' something is the case","tip":"Use this when describing an action that matches or mimics a certain state.","jlpt":"N4","pattern":"Dictionary form + ように"},{"example":"響き渡るような音で","meaning":"Indicates a simile or provides an example for a Noun (like/as)","tip":"This describes a Noun by comparing it to the preceding verb or Clause.","pattern":"Dictionary form + ような + Noun","jlpt":"N4"},{"tip":"While grammatically casual, adding か makes it a request for the listener's cooperation.","jlpt":"N4","pattern":"Te-form + くれないか","example":"仲間に入れてくれないか","meaning":"A polite way to ask for a favor or request permission (Won't you...?)"},{"tip":"Keep in mind that this explicitly requests an action from another person, unlike したい which is for one's own actions.","jlpt":"N4","pattern":"Te-form + ほしい","example":"仲間の一人にしてほしい","meaning":"Expresses a desire for someone else to do something"},{"example":"親友が気を利かせて教えてくれた","meaning":"To do a favor or action for the speaker's benefit","tip":"Used when a third party performs a kind act for the person the speaker empathizes with (in this case, Melos).","jlpt":"N4","pattern":"Te-form + くれる"},{"pattern":"Te-form + たまらない","jlpt":"N3","tip":"This expresses subjective feelings that are so strong the person cannot control them. Often used with adjectives of emotion.","meaning":"Expresses an emotion or sensation that is unbearable or can't be helped (extremely)","example":"見られるのが恥ずかしくてたまらないのだ"}]],"original":[[{"example":"除かなければならぬ","tip":"This is a more formal or literary version of ～なければならない. In modern speech, ～ぬ is often replaced by ～ない.","jlpt":"N4","pattern":"Plain negative (short stem) + なければならぬ","meaning":"Must; have to (indicates obligation or necessity)"},{"meaning":"It has been decided that; it is arranged that (indicates a scheduled event or rule)","example":"迎える事になっていた","tip":"Use this when describing external decisions, rules, or schedules rather than personal willpower.","jlpt":"N4","pattern":"Dictionary form + ことになっている"},{"meaning":"Grammar pattern for expressing purpose of movement (going somewhere to do something)","jlpt":"N4","pattern":"Masu-stem + に (directional verb)","example":"買いに、はるばる市にやって来たのだ","tip":"Commonly used with verbs like 行く (go), 来る (come), and 帰る (return)."},{"meaning":"Things like... and... (giving examples in a non-exhaustive list)","tip":"Similar to ～や～など, but ～やら implies a sense of disarray, variety, or uncertainty.","example":"衣裳やら祝宴の御馳走やら","pattern":"Noun + やら + Noun + やら","jlpt":"N3"},{"meaning":"Intend to; plan to (expresses the speaker's intention)","jlpt":"N4","pattern":"Dictionary form + つもりだ","example":"訪ねてみるつもりなのだ","tip":"The sentence-ending ～なのだ adds an explanatory tone or emphasis to the intent."},{"meaning":"While; during (an action or state takes place while another is ongoing)","jlpt":"N3","pattern":"Dictionary form + うちに","example":"歩いているうちに","tip":"Indicates that a change or event occurs before a specific state changes. Often translated as \"while still...\"."},{"meaning":"Should be; expected to be (expresses strong expectation based on objective reasons)","example":"賑やかであった筈だが","tip":"Use 筈 (はず) when you have a logical reason to believe something is true. addition of が creates a 'but' contrast.","jlpt":"N4","pattern":"Noun + である + 筈だ"},{"example":"信ずる事が出来ぬ","tip":"Adding ～ぬ (negative) makes it \"cannot\". In modern Japanese, 信ずる is often 信じる.","jlpt":"N4","pattern":"Dictionary form + ことが出来る","meaning":"Cannot; to be unable to (potential ability)"},{"meaning":"To do something in advance, or to leave something in a certain state","example":"生かして置けぬ","tip":"In this context, it means \"leave him alive\". The negative Potential form 置けぬ means \"cannot leave/allow to remain\".","jlpt":"N4","pattern":"Te-form + おく"}],[{"tip":"When used with a Noun, the particle の is required. It can express either the beneficiary or the objective.","jlpt":"N4","pattern":"Noun + の + 為","example":"自分の地位を守る為か","meaning":"Indicates a purpose, goal, or reason (for the sake of / in order to)."},{"meaning":"Used to describe a state that continues unchanged while another action takes place.","example":"背負ったままで","pattern":"Plain past + まま","jlpt":"N4","tip":"It often implies that the current state is somewhat unusual or shouldn't naturally be left as it is."},{"jlpt":"N4","pattern":"Te-form + しまう","tip":"In casual speech, this often contracts to ～ちゃう or ～じゃう. In this text, its formal version expresses the finality of the situation.","meaning":"Expresses completion of an action, often with a nuance of regret, realization of a mistake, or an unintended outcome.","example":"短剣が出て来たので、騒ぎが大きくなってしまった。"},{"meaning":"Used for rhetorical questions that strongly imply a negation (What kind of... / How can you call this...).","example":"殺して、何が平和だ。","jlpt":"N3","pattern":"Interrogative + が + Noun + だ","tip":"This is a common way to express disbelief or criticism towards someone's claim."},{"pattern":"Dictionary form + つもり","jlpt":"N3","tip":"While usually used for future plans, here it is used in the past tense to question a motive or intent.","meaning":"Expresses an intention, plan, or expectation.","example":"何をするつもりであったか。"},{"tip":"ならぬ is the archaic/literary negative form of なる. In modern speech, ならない is more common.","pattern":"Te-form + は + ならぬ","jlpt":"N3","example":"信じては、ならぬ。","meaning":"A strong prohibition (must not / shall not)."},{"meaning":"Used to soften a statement, express hesitation, or imply a contrast (it is the case that... but...).","example":"平和を望んでいるのだが。","pattern":"Dictionary form + のだ","jlpt":"N3","tip":"Adding のだ (or んだ) provides an explanatory tone or emphasis to the statement."},{"example":"刻み込まれたように深かった。","meaning":"Indicates a resemblance or appearance (as if / like).","tip":"Used for similes. When it modifies a verb or adjective (like 深い), ように is used; when it modifies a Noun, ような is used.","pattern":"Plain past + ように","jlpt":"N3"},{"tip":"It is a stronger, more formal expression than ～たほうがいい. For the verb する, both するべき and すべき are acceptable.","pattern":"Dictionary form + べき","jlpt":"N2","example":"最も恥ずべき悪徳だ。","meaning":"Expresses an obligation, duty, or something that is natural/appropriate to do."},{"example":"見え透いてならぬ。","meaning":"Expresses that a feeling or condition is so strong that it cannot be helped or suppressed (cannot help but...).","tip":"In this literary text, ならない is written as ならぬ. It is used with verbs of emotion or spontaneous reaction.","pattern":"Te-form + ならない","jlpt":"N2"},{"example":"帰って来ないにきまっている。","meaning":"Expresses a strong conviction or certainty (surely / bound to / must be).","tip":"This is a subjective judgment used when the speaker is absolutely sure about something based on their own logic.","jlpt":"N2","pattern":"Dictionary form + にきまっている / にきまっている"}],[{"pattern":"Noun / Clause + だと","jlpt":"N4","tip":"In this context, it shows a firm declaration or a re-statement of a previous fact.","meaning":"A particle used at the end of a sentence to quote information or emphasize a statement, often implying an omitted final verb like 'I said' or 'it is'.","example":"結婚式は、あすだと。"},{"tip":"While ～ならない is standard, ～ならぬ is common in classic literature or for a very solemn tone.","pattern":"Plain negative (stem) + なければならぬ修","jlpt":"N4","example":"またすぐ市に行かなければならぬ。","meaning":"An archaic or literary version of ～なければならない, expressing obligation or necessity."},{"pattern":"I-adjective / Noun + だろう / かろう","jlpt":"N4","tip":"かろう is specifically the Volitional form form for I-adjectives, appearing mainly in formal or literary writing.","meaning":"The Volitional form form of the copula (だ/です), used to express a conjecture, suggestion, or a firm opinion about what is likely.","example":"早いほうがよかろう。"},{"jlpt":"N4","pattern":"Te-form + くれ","tip":"This is the Imperative form of くれる. It is direct and assertive, used between close friends or in urgent situations.","meaning":"A command or strong request for someone to do something for the speaker.","example":"結婚式を明日にしてくれ、と頼んだ。"},{"pattern":"Masu-stem + 給え","jlpt":"N3","tip":"In modern Japanese, you will mostly see this in fiction or historical dramas to indicate a commanding or masculine tone.","meaning":"A polite yet commanding suffix used to give instructions or requests, typically by a person of higher status or in formal/literary speech.","example":"待つことは出来ぬ、どうか明日にしてくれ給え"},{"example":"車軸を流すような大雨となった。","meaning":"Used to describe a Noun by comparing it to something else (simile). It means 'like' or 'similar to'.","tip":"ような modifies a Noun, while ように modifies a verb or adjective.","jlpt":"N3","pattern":"Noun + のような / のように"},{"tip":"Do not confuse with まで (until). までに means 'by' or 'no later than'.","pattern":"Noun / Dictionary form + までに","jlpt":"N3","example":"あすの日没までには、まだ十分の時が在る。","meaning":"Indicates a time limit or deadline by which an action must be completed."},{"meaning":"The Volitional form form used to express a conjecture or probability regarding a state or action. Equivalent to ～ているだろう.","example":"雨も小降りになっていよう。","pattern":"Te-form + いよう","jlpt":"N3","tip":"This is often found in internal monologues or literary descriptions of future states."},{"meaning":"A very formal or humble way to receive something (often an intangible thing like permission or a burden) from someone else.","example":"ちょっとご免こうむって眠りたい。","jlpt":"N2","pattern":"Noun + をこうむる","tip":"This is a formal verb used in set expressions like 恩恵をこうむる (to receive benefits) or the polite apology shown in the example."},{"example":"歓喜に酔っているらしい花嫁に近寄り","meaning":"Indicates a judgment based on objective evidence or the general appearance of a situation.","tip":"Unlike そうだ (visual impression), らしい suggests the speaker is making an inference based on information or behavior.","pattern":"Dictionary form / Noun + らしい","jlpt":"N4"}],[{"pattern":"Dictionary form + れば","meaning":"Expresses a condition that must be met for a certain result to occur.","example":"出発すれば、約束の刻限までには十分間に合う。","tip":"For verbs ending in 'u', change the final vowel to 'e' and add 'ba'. This is the standard Conditional form.","jlpt":"N4"},{"pattern":"Plain negative + なければならぬ/ならない","meaning":"Expresses obligation or necessity (must do). The ending 'nu' is a literary/classical version of 'nai'.","example":"走らなければならぬ。","tip":"In modern speech, 'naranai' is more common, but 'naranu' adds a heroic or formal tone in literature.","jlpt":"N4"},{"pattern":"Masu-stem + そうになる","meaning":"Used to express that something appears likely to happen or is about to happen.","example":"立ちどまりそうになった。","tip":"Use this when an event almost happened but was narrowly avoided.","jlpt":"N4"},{"meaning":"Used to describe two actions performed simultaneously by the same person.","pattern":"Masu-stem + ながら","tip":"The primary action comes after 'nagara', while the secondary action comes before it.","example":"自分を叱りながら走った。","jlpt":"N4"},{"jlpt":"N4","tip":"Often used with adverbs like 'kitto' (definitely) or 'tabun' (probably).","example":"妹たちは、きっと佳い夫婦になるだろう。","meaning":"Indicates conjecture, probability, or a polite way to state an opinion.","pattern":"Dictionary form + だろう/でしょう"},{"jlpt":"N4","tip":"Use this when you are confident in your conclusion based on logic or evidence.","example":"なんの気がかりも無い筈だ。","meaning":"Expresses a strong expectation or belief based on some reason; 'should be' or 'is supposed to be'.","pattern":"Dictionary form + 筈だ/はずだ"},{"tip":"A common way to give advice or state a lack of obligation.","example":"そんなに急ぐ必要も無い。","jlpt":"N4","meaning":"States that a specific action is not necessary.","pattern":"Dictionary form + 必要がある/ない"},{"tip":"Often emphasizes doing something while the current state lasts or before it's too late.","example":"太陽も既に真昼時です。あれが沈んでしまわぬうちに","jlpt":"N3","meaning":"Indicates that an action should be completed before a certain change or state occurs.","pattern":"Plain negative + うちに"},{"tip":"Usually emphasizes a sense of desperation or having reached a final decision.","example":"泳ぎ切るより他に無い。","jlpt":"N3","meaning":"Indicates that there is no other choice or alternative but to do something.","pattern":"Dictionary form + より他に（は）ない"},{"jlpt":"N3","example":"陽は既に西に傾きかけている。","tip":"Use this for gradual processes like the sun setting or someone starting to say something.","pattern":"Masu-stem + かける/かけている","meaning":"Indicates that an action has started but is not yet finished, or is in the process of happening."},{"tip":"A formal and literary expression often used in historical or dramatic contexts.","example":"一刻といえども、むだには出来ない。","jlpt":"N1","meaning":"Even (a small amount/a single thing); used to emphasize that even the smallest unit cannot be ignored.","pattern":"Noun + といえども"},{"meaning":"Stresses that a specific action led to a negative or regrettable result.","pattern":"Plain past + ばかりに","tip":"This reflects a strong feeling of regret or blame regarding the cause.","example":"おまえを信じたばかりに、やがて殺されなければならぬ。","jlpt":"N2"}],[{"tip":"In casual speech, this often contracts to ～ちゃう or ～ちゃう, but the literary ～てしまえ is very forceful.","pattern":"Te-form + しまう","jlpt":"N4","example":"忘れてしまえ。","meaning":"Indicates the completion of an action, often with a sense of regret or focus on the totality of the result. When used as an imperative (～てしまえ), it expresses a strong command to finish or get rid of something completely."},{"meaning":"Used to describe a general truth, common sense, or a natural tendency. It implies 'it is only natural that...' or 'it is the way things are.'","example":"五臓が疲れているときは、ふいとあんな悪い夢を見るものだ。","pattern":"Dictionary form + ものだ","jlpt":"N3","tip":"Do not confuse this with its use for nostalgia or expressing strong emotion; here it states a general rule of nature or human experience."},{"tip":"This is more formal and explicit than the potential conjugation (e.g., 死ねる).","pattern":"Dictionary form + 事が出来る","jlpt":"N5","example":"死ぬ事が出来るぞ。","meaning":"Expresses ability or possibility. Nominalizing the verb with 事 (thing/fact) allows it to be the object of 出来る (can do)."},{"meaning":"Indicates that a state or condition remains unchanged.","example":"正直な男のままにして死なせて下さい。","pattern":"Noun + のまま","jlpt":"N3","tip":"It describes doing something without changing a previous state, like 'leaving it as is.'"},{"tip":"In this text, the speaker uses the shortened negative form ～てはならぬ for a more classical or dramatic tone.","jlpt":"N4","pattern":"Te-form + はならない","example":"死なせてはならない。","meaning":"Expresses a strong prohibition or a sense of duty that something must not happen. It is more formal than ～てはいけない."},{"pattern":"Dictionary form + がよい","jlpt":"N3","tip":"This sounds archaic or grand, often used by superiors or in dramatic literature.","meaning":"A formal or slightly authoritative way to permit or suggest an action, meaning 'it is fine to...' or 'you may as well...'","example":"知らせてやるがよい。"},{"pattern":"Dictionary form + ような","jlpt":"N4","tip":"When modifying a Noun, use ような. When modifying a verb or adjective, change it to ように.","meaning":"Indicates a resemblance or an appearance. It translates to 'like' or 'as if.'","example":"うめくような声が、風と共に聞えた。"},{"tip":"The primary action comes at the end of the sentence; the action with ながら is the secondary/background action.","pattern":"Masu-stem + ながら","jlpt":"N4","example":"メロスは走りながら尋ねた。","meaning":"Indicates that two actions are being performed simultaneously by the same person."},{"meaning":"Expresses that there is no other choice or alternative but to do a certain action.","example":"走るより他は無い。","pattern":"Dictionary form + より他は無い","jlpt":"N3","tip":"This is a strong way to express necessity or being cornered into a single option."},{"pattern":"Dictionary form + ところだ","jlpt":"N4","tip":"Combine with the present progressive (～ているところ) to mean 'in the middle of' or Plain past (～たところ) to mean 'just finished.'","meaning":"Indicates the specific stage of an action. Dictionary form + ところ means 'just about to' or 'on the verge of.'","example":"あの方が死刑になるところです。"},{"jlpt":"N4","pattern":"Plain past + なら","tip":"Unlike ～たら, which focuses on the sequence of events, なら focuses on the context or the supposition.","meaning":"A conditional marker used to provide a hypothesis or if-then scenario. Often used when the speaker is giving advice or expressing a 'what if' regret.","example":"早かったなら！"},{"example":"信じて居りました。","meaning":"The humble version of the auxiliary verb ～ている. It expresses the state or ongoing action of someone related to the speaker when speaking to a superior.","tip":"While おる is humble in modern standard Japanese, in older literature it can occasionally act as a stiff/neutral version of いる. Here it is used politely (居りました).","pattern":"Te-form + おる","jlpt":"N4"},{"tip":"This softens a statement to sound more hopeful or less definitive than saying 'it is possible.'","jlpt":"N2","pattern":"Plain negative + ものでもない","example":"間に合わぬものでもない。","meaning":"A double negative used to suggest a possibility, meaning 'it's not impossible to...' or 'one cannot say that it won't...'"},{"meaning":"An idiomatic expression meaning 'it goes without saying' or 'it is needless to mention.' It is the literary/classical version of 言うまでもない.","example":"言うにや及ぶ。","jlpt":"N1","pattern":"Dictionary form + には及ばない (variant)","tip":"In this specific text, the particle や is used for emphasis, creating the classical flavor of 'Needless to say!'"},{"example":"消えようとした時","meaning":"Indicates that someone is about to do something or an event is on the verge of happening.","tip":"Often used for natural phenomena or actions that were interrupted just as they were starting.","pattern":"Volitional form form + とする","jlpt":"N3"},{"meaning":"A literary expression meaning 'like' or 'as' (similar to ように). It is common in formal writing and epic storytelling.","example":"疾風の如く刑場に突入した。","jlpt":"N1","pattern":"Noun + の如く","tip":"This is the archaic version of ように and makes the prose sound very dignified and classical."}],[{"pattern":"Te-form + はならぬ/はならない","tip":"ぬ is a classical/literary negative ending equivalent to ない. It is often used in speech from authority figures or in formal literature.","jlpt":"N3","meaning":"Must not; should not (strong prohibition)","example":"その人を殺してはならぬ"},{"tip":"While often used for future plans, when paired with the Plain past, it indicates the speaker's subjective belief or intent in that moment, even if the result was different.","jlpt":"N3","pattern":"Dictionary form / Plain past + つもり","meaning":"Intending to; believing one is doing something","example":"叫んだつもりであったが"},{"pattern":"Plain past + ばかり","tip":"Used here to indicate that the sound barely came out and nothing more occurred beyond that minimal action.","jlpt":"N3","meaning":"Just after; only just (resultative)","example":"出たばかり"},{"example":"濁流を泳いだように","meaning":"Just like; as if","pattern":"Dictionary form / Plain past / Noun + の + ように","jlpt":"N4","tip":"This use of ように creates a simile, comparing the current action to a previous or hypothetical state."},{"pattern":"Masu-stem + ながら","tip":"The primary action follows the ながら Clause. Both actions must be performed by the same subject.","jlpt":"N4","meaning":"While doing; simultaneously","example":"叫びながら"},{"meaning":"If (conditional)","pattern":"Plain past + ら","tip":"When used with もし (若し), it emphasizes the hypothetical nature of the condition.","jlpt":"N4","example":"若し私を殴ってくれなかったら"},{"example":"抱擁する資格さえ無い","meaning":"Even; so much as (emphasizing an extreme)","pattern":"Noun / Dictionary form + さえ","tip":"さえ replaces particles like は or が to emphasize that even the most basic or minimum requirement is not met.","jlpt":"N3"},{"meaning":"To the extent that; so much so that","tip":"This indicates the degree or level of an action by providing a vivid example of its effect.","jlpt":"N3","pattern":"Dictionary form / Noun + ほど","example":"鳴り響くほど"},{"pattern":"Te-form + から","jlpt":"N4","tip":"This explicitly marks a sequence of events, ensuring the first action is completed before the second begins.","meaning":"After doing...","example":"殴ってから"},{"example":"仲間に入れてくれまいか","pattern":"Dictionary form / Masu-stem + まいか","tip":"まい is a negative Volitional form/conjectural auxiliary. Combined with か, it forms a rhetorical or humble invitation.","jlpt":"N2","meaning":"Won't you? (polite request/invitation in a slightly formal or archaic tone)"},{"pattern":"Te-form + ほしい","jlpt":"N4","tip":"The target of the request is usually marked with the particle に. Don't confuse this with Dictionary form + ほしい (which is incorrect for verbs).","meaning":"Want someone else to do something","example":"一人にしてほしい"},{"example":"着るがいい","pattern":"Dictionary form + がいい","tip":"This indicates a command or strong suggestion, often carrying a nuance of 'this is the best course of action' or 'you might as well'.","jlpt":"N2","meaning":"May as well; it is fine to (giving permission or a suggestion)"}]]},"lemon":{"simplified":[[{"meaning":"The embedded question 'why' used within a larger sentence structure","jlpt":"N4","pattern":"Scenario/Clause + か","example":"なぜかわかりませんが","tip":"Use the Dictionary form of verbs or adjectives before the particle か to embed a question into a sentence."},{"tip":"For I-adjectives, change the final い to く before なる. This marks a change in state.","example":"帰りたくなります","pattern":"Adjective-stem/Noun + になる","jlpt":"N4","meaning":"To become a certain state or to start feeling a certain way"},{"pattern":"Noun + のせい","jlpt":"N4","meaning":"Indicates a reason or cause, often with a negative or undesired result","tip":"This is used primarily for assigning blame. To say 'thanks to' for a positive result, use おかげ instead.","example":"病気のせいだけではありません"},{"tip":"When used with a Stem, it indicates something is about to happen or looks likely to happen. When modifying a Noun, use そうな.","example":"壊れそうな町です","pattern":"Masu-stem + そうだ","jlpt":"N4","meaning":"Indicates that something looks like or appears to be in a certain state"},{"meaning":"Expresses inability to do an action; the nominalizer こと turns the verb into a Noun phrase","jlpt":"N4","pattern":"Dictionary form + ことができる","example":"歩いていることができないのです","tip":"This is a formal way to express potential. In the text, the negative form ことができない is used."},{"pattern":"Dictionary form + と","jlpt":"N4","meaning":"Expresses a natural consequence or a repetitive, habitual truth; 'whenever A happens, B follows'","tip":"This conditional indicates that the second action follows inevitably or automatically from the first.","example":"飲んでいると、体が重くてだるい時が来ます"},{"meaning":"Guessing or judging based on appearance or current situation; 'looks like' or 'seems like'","jlpt":"N4","pattern":"I-adjective (minus い) + そうだ/そうな","example":"泥棒がいそうな暗い道","tip":"For the adjective 良い (good), the form becomes 良さそう. For the negative ない, it becomes なさそう."},{"tip":"For Nouns and Na-adjectives, use でも. It shows that the result is contrary to what might be expected.","example":"見ても心が楽しくありません","pattern":"Te-form + も","meaning":"Even if, even though, or although; indicates a concession","jlpt":"N4"},{"pattern":"Noun + あちらこちら + Verb","meaning":"Here and there; back and forth; indicates movement in various directions or locations","jlpt":"N3","tip":"This is often used with verbs of movement like walking, looking, or searching to describe a wandering or scattered action.","example":"あちらこちら歩いていました"},{"example":"わからないくらい、たくさん歩きました","tip":"It describes the intensity of an action by providing a comparison or a specific example of the extent.","meaning":"To the extent that; so much so that; indicates the degree or level of something","jlpt":"N3","pattern":"Dictionary form/Plain negative + くらい/ぐらい"}],[{"jlpt":"N5","example":"買うことができませんでした","tip":"Always use the Dictionary form before this pattern to express potential.","meaning":"To be able to do something (ability or possibility)","pattern":"Dictionary form + ことができる"},{"jlpt":"N4","example":"夜になると","tip":"This 'to' conditional describes things that happen automatically or habitually.","meaning":"When/if; expresses a natural consequence or a predictable result","pattern":"Dictionary form + と"},{"jlpt":"N5","example":"果物を見るのが好きでした","tip":"The particle 'no' turns the preceding verb phrase into a Noun.","meaning":"Nominalizes a verb to express an activity that someone likes or dislikes","pattern":"Dictionary form + のが好きだ"},{"meaning":"Called; named; used to introduce a proper Noun or specific definition","pattern":"Noun + という + Noun","example":"八百卯」という果物の店","tip":"Use this pattern when introducing a name that the listener might not know yet.","jlpt":"N4"},{"example":"レモンを買ってから","tip":"Do not confuse this with the particle 'kara' used for 'because' or 'from'. Here it must follow the Te-form.","jlpt":"N4","meaning":"After doing; indicates an action that takes place after another action is completed","pattern":"Te-form + から"},{"meaning":"While; indicates two actions occurring simultaneously by the same person","pattern":"Masu-stem + ながら","example":"町を歩きながら","tip":"The main action comes after 'nagara', while the secondary action comes before it.","jlpt":"N4"},{"jlpt":"N4","tip":"In this context, it emphasizes the complete and somewhat unexpected disappearance of the bad feelings.","example":"消えてしまったのです","pattern":"Te-form + しまう","meaning":"Regrettably; completely; indicates the completion of an action or a sense of regret/surprise"},{"pattern":"I-adjective (remove い) + く + Verb","meaning":"Turns an I-adjective into an adverb to describe how an action is performed","tip":"Change 'ookii' to 'ookiku' to modify the verb 'suu' (breathe).","example":"大きく息を吸うと","jlpt":"N4"},{"jlpt":"N3","example":"レモンの冷たさ","tip":"Commonly used for physical properties like length (nagasa), weight (omosa), and coldness (tsumetasa).","meaning":"State or degree; turns an adjective into a Noun to indicate a measurable quality or feeling","pattern":"I-adjective (remove い) + さ"},{"meaning":"Too much; indicates an excessive degree or a state that is beyond a limit","pattern":"Masu-stem + すぎる","example":"重すぎず","tip":"In the text, 'sugizu' is the negative connective form meaning 'without being too...'.","jlpt":"N3"}],[{"pattern":"Te-form + みる","tip":"In this text, it is used in the Volitional form みよう to express the intent to try going in.","example":"入ってみよう","jlpt":"N4","meaning":"To try doing something to see what it's like"},{"meaning":"To look like or be similar to something","jlpt":"N4","tip":"Use this for metaphors or when something resembles something else in appearance or nature.","example":"お城のようでした","pattern":"Noun + のようだ/のように"},{"jlpt":"N4","meaning":"Nominalizes a verb to treat the action as a Noun/subject","pattern":"Dictionary form + の","tip":"Using の makes it possible to describe an action with an adjective like 面倒 (troublesome) or 楽しい (fun).","example":"開くのも面倒でした"},{"pattern":"Dictionary form + と","tip":"This specific usage indicates a natural consequence or a repeated habit of the speaker.","example":"丸善にいると","jlpt":"N4","meaning":"Whenever a certain action happens, a result naturally follows; if/when"},{"tip":"While often meaning 'after', when followed by expressions of curiosity or doubt, it sets up a hypothetical scenario.","example":"置いたら、どうなるだろう","pattern":"Plain past + ら","meaning":"Conditional 'if' or 'when'; used to imagine a hypothetical situation or result","jlpt":"N4"},{"meaning":"To pretend as if; to act as though something is true when it is not","jlpt":"N3","example":"知らないふりをして","tip":"The Noun before ふり describes the \"act\" or \"persona\" being put on.","pattern":"Dictionary form + ふりをする"},{"meaning":"Appears to be; seems like (based on the speaker's subjective impression)","jlpt":"N3","example":"レモンの周りだけに集まっているようでした","tip":"This is used to describe a scene or situation that looks a certain way to the observer, often figuratively.","pattern":"Dictionary form + ようだ"},{"example":"店を出てから数分後に","tip":"When used with time counters, it specifies exactly how much later something occurs.","pattern":"Noun + 後に","meaning":"After a certain amount of time has passed since an event","jlpt":"N3"}]],"intermediate":[[{"pattern":"Dictionary form + と","meaning":"Indicates a natural or inevitable consequence; whenever A happens, B follows.","jlpt":"N4","tip":"Focus on the 'natural result' aspect here, as it describes a recurring physiological state (hangover).","example":"お酒を毎日飲んでいるとやってくる"},{"tip":"Use this when you want to use a Noun to describe another Noun as a simile.","example":"二日酔いのようなだるい時期","pattern":"Noun + のような","jlpt":"N4","meaning":"Used to describe a Noun by comparing it to another Noun (similarity)."},{"pattern":"Te-form + しまう","meaning":"Indicates an action that happens unintentionally or a state that occurs despite one's plans, often with a nuance of regret.","jlpt":"N4","tip":"In this context, it emphasizes the uncontrollable nature of the protagonist's impulsive feelings.","example":"立ち上がって帰りたくなってしまう"},{"tip":"The negative form 'okanai' here suggests that the restless feeling prevents the state of being still from being maintained.","example":"そこにじっとさせておかないのだ","pattern":"Te-form + おく","jlpt":"N4","meaning":"Indicates performing an action in advance or leaving a state as it is for a future purpose or objective."},{"tip":"Commonly used with verbs of destruction or consumption (like eating or breaking) to show an incomplete state.","example":"家や土壁が崩れかけ","pattern":"Masu-stem + かける/かけの","meaning":"Indicates that an action or state has started but is not yet finished, or is in the middle of a process.","jlpt":"N3"},{"example":"壊れていくのかを考えるのが好きだった","tip":"Here it describes the temporal progression of the town's decay.","jlpt":"N3","meaning":"Indicates a change or action that starts from the present and continues into the future, or moves away from the speaker.","pattern":"Te-form + いく"},{"tip":"Use this to describe subjective feelings or gut instincts about a situation.","example":"馴染んでいるような気がした","pattern":"Clause + 気がする","jlpt":"N3","meaning":"Indicates that the speaker has a certain feeling or intuition, though they aren't 100% certain."},{"tip":"This is an idiomatic expression very common in literature to describe absolute helplessness.","example":"どうしようもない重い気持ち","pattern":"Clause + どうしようもない","meaning":"Used to express that there is no way to deal with a situation; it is hopeless or cannot be helped.","jlpt":"N3"},{"pattern":"Plain past + まま / Noun + のまま","meaning":"Indicates that a state continues unchanged while another action is performed.","jlpt":"N3","tip":"It emphasizes that the second action (walking) happens while holding onto the internal state (the feeling).","example":"重い気持ちを抱えたまま"}],[{"meaning":"Until a certain point or state is reached","tip":"When used with a verb, it indicates that an action continues until the change described by the verb occurs.","pattern":"Dictionary form + まで","jlpt":"N4","example":"分からなくなるまで"},{"example":"歩き続けた","pattern":"Masu-stem + 続ける","jlpt":"N4","tip":"This compound verb focalizes the continuous nature of the action over a period of time.","meaning":"To continue doing an action"},{"meaning":"Because; since (expresses a reason or cause)","tip":"This is more polite and sounds slightly more objective or natural in descriptive writing than から.","pattern":"Clause + ので","jlpt":"N4","example":"お金がないので"},{"example":"見るだけでも楽しかった","tip":"Adding も adds emphasis, often implying that even the simplest action is sufficient for the result.","jlpt":"N3","pattern":"Dictionary form + だけでも","meaning":"Just; only (emphasizing a minimum requirement or simple action)"},{"example":"並べることで有名だったのだ","meaning":"Explaining a reason or providing background information with emphasis","pattern":"Dictionary form + のだ","jlpt":"N3","tip":"In written text, this often appears as んだ in speech; it provides an explanatory tone to the sentence."},{"tip":"Use this when something spontaneously appears a certain way to the observer's eyes.","pattern":"Masu-stem + 見える","jlpt":"N4","meaning":"To look like; to appear to be","example":"果物がさらに美しく輝いて見える"},{"example":"ラグビーボールのような形","meaning":"Like; similar to (describing a Noun)","tip":"Used for metaphors or to compare something to a representative example.","jlpt":"N4","pattern":"Noun + のような"},{"example":"素晴らしいものに思えた","pattern":"Noun + に思える","jlpt":"N3","tip":"This express a spontaneous feeling or intuition rather than a logical conclusion.","meaning":"To seem like; to appear to be (subjective impression)"},{"tip":"Focuses on the exact point in time when an action occurs.","pattern":"Plain past + 瞬間","jlpt":"N3","meaning":"The moment that...; as soon as...","example":"レモンを握った瞬間から"},{"example":"軽くなったように感じた","pattern":"Dictionary form + ように感じる","jlpt":"N4","tip":"Describes a subjective sensation or a resemblance to a state.","meaning":"To feel as if; to feel like"},{"example":"街を歩きながら","meaning":"While doing (two actions at the same time)","tip":"The action following ながら is usually the main focus of the sentence.","jlpt":"N4","pattern":"Masu-stem + ながら"},{"pattern":"Dictionary form + なんて","jlpt":"N3","tip":"Often used at the end of a sentence to show the speaker's strong emotion or reaction to something unexpected.","meaning":"Expressing surprise, disbelief, or emotional emphasis regarding a fact","example":"消えてしまうなんて"},{"example":"幸せになれるなんて","meaning":"To become (indicating a change in state)","pattern":"Noun/Na-adjective + になる","jlpt":"N4","tip":"Combined here with the Potential form and なんて to express surprise at the change."},{"tip":"Used for vague intuitions or physical/mental sensations that aren't necessarily based on proof.","pattern":"Dictionary form + 気がする","jlpt":"N3","meaning":"To have a feeling that; to have a hunch that","example":"元気が出てくるような気がした"},{"meaning":"As if; like (modifying a Noun)","tip":"Creates a simile to describe the Noun that follows.","pattern":"Dictionary form + ような + Noun","jlpt":"N4","example":"健康になったような錯覚に陥った"},{"example":"重すぎず、軽すぎず","pattern":"Masu-stem + すぎる (as ～すぎず)","jlpt":"N4","tip":"The ず ending is a formal literary negative (similar to ないで) used to connect sentences.","meaning":"Too much; excessively (negated)"},{"meaning":"To try doing something (Volitional form)","jlpt":"N4","pattern":"Te-form + みる (as ～てみよう)","tip":"Combines the 'try and see' meaning with the Volitional form to express an internal suggestion.","example":"入ってみよう"},{"tip":"Indicates that a state was almost reached or looks like it is going to happen.","pattern":"Masu-stem + そうになる","jlpt":"N4","meaning":"Look like; feel like; about to (indicating appearance or likelihood)","example":"息が詰まりそうになる"},{"example":"レモンを持っていれば","meaning":"If; provided that (conditional)","jlpt":"N4","pattern":"Conditional form (Verb-ば)","tip":"Focuses on the condition required for the following result to occur."}],[{"example":"店に入った途端、私の心を満たしていた幸福な気持ちは、だんだんと逃げていった。","tip":"This pattern implies an element of surprise or an unexpected change immediately following the action.","pattern":"Dictionary form + 途端/Plain past + 途端","meaning":"Immediately after; as soon as. Indicates that a second action or event occurs almost simultaneously after the first.","jlpt":"N3"},{"jlpt":"N4","meaning":"To do something completely, or to do something accidentally/regretfully.","pattern":"Te-form + しまう","tip":"In speaking, this often contracts to ～ちゃう or ～じゃう, but in literature, it emphasizes completion or an uncontrollable result.","example":"歩き回って疲れてしまったのだろうか。"},{"jlpt":"N3","meaning":"Should be; expected to be. Expresses a strong expectation based on logic or past experience.","pattern":"Dictionary form + はず","tip":"For Nouns use + のはず and for Na-adjectives use + なはず. It indicates what the speaker believes to be a natural certainty.","example":"普段なら好きなはずの画集も、今日は開くのさえ面倒だった。"},{"jlpt":"N3","meaning":"Even; so much as. Used to emphasize an extreme example to show the extent of a situation.","pattern":"Noun + さえ/Dictionary form + のさえ","example":"今日は開くのさえ面倒だった。","tip":"It replaces the particles が and を, but attaches to other particles like に. It highlights a minimum requirement or a baseline emotion."},{"meaning":"Like; similar to. Used to make a comparison to something that illustrates a state or appearance.","jlpt":"N4","tip":"Use のような to modify a Noun and のように to modify a Verb or Adjective.","example":"それは、奇妙で幻想的なお城のようだった。","pattern":"Noun + のような/Noun + のように"},{"example":"軽くドキドキする心を抑えながら、その本の城の一番上に、持っていたレモンを静かに置いたのだ。","tip":"The primary action is usually the one described by the second verb in the sentence.","pattern":"Masu-stem + ながら","meaning":"While doing. Indicates two actions occurring simultaneously by the same person.","jlpt":"N4"},{"meaning":"Appears to be; looks like. Indicates an impression or a subjective appearance.","jlpt":"N4","tip":"This focuses on how something looks or the visual impression the observer receives.","example":"周りのごちゃごちゃした色が、すべてそのレモンの鮮やかな黄色に吸収されていくように見えた。","pattern":"Dictionary form + ように見える"},{"pattern":"Plain past + ら","example":"「このまま置いて、知らん顔をして外へ出たらどうなるだろう」","tip":"It is the most versatile conditional and is frequently used for \"what if\" scenarios.","jlpt":"N4","meaning":"If; when. A Conditional form used for hypothetical situations or consequences of an action."},{"jlpt":"N3","meaning":"As if; just like. Used with comparisons to emphasize that something feels or acts like something else.","pattern":"まるで + Noun + のように/まるで + Dictionary form + かのように","tip":"Using かのように makes the comparison more metaphorical or literary (as if it were the case).","example":"外へ出ると、私はまるで何か大きなことを成し遂げたかのように、京極の通りを愉快な気分で下っていった。"}]],"original":[[{"pattern":"Dictionary form + と言うか","meaning":"Used to list alternatives when the speaker is unsure of the exact description or is providing choices. Similar to \"whether one calls it A or B\".","jlpt":"N3","tip":"Often used with the Volitional form like 言おうか as seen in the text to express hesitation.","example":"言う（と言う）か、嫌悪と言う（と言おう）か"},{"example":"宿酔があるように","jlpt":"N3","tip":"When following a verb, it describes doing something in the same manner as that action.","meaning":"Used to indicate a resemblance, a metaphor, or to follow a certain state/manner. Meaning \"just like\" or \"in the way that\".","pattern":"Noun + のように / Dictionary form + ように"},{"meaning":"Used to provide a specific example or to explain the nature of something via metaphor. Meaning \"like\" or \"as if\".","pattern":"Noun + のような / Dictionary form + ような","example":"背を焼くような借金","jlpt":"N3","tip":"This attaches to nouns to modify subsequent nouns, whereas ように modifies verbs or adjectives."},{"jlpt":"N2","tip":"Usually used with words expressing emotion or physical sensation.","example":"辛抱がならなくなった","pattern":"Noun + がならない / Te-form + ならない","meaning":"Used to express an unbearable emotion or physical state that one cannot control. Meaning \"cannot help but\" or \"cannot endure\"."},{"meaning":"Indicates that an action or state continues without interruption. Meaning \"to keep on\" or \"to continue doing\".","pattern":"Masu-stem + 続ける","example":"浮浪し続けていた","jlpt":"N3","tip":"Focuses on the persistence or repeated nature of the action."},{"meaning":"Used to give an example while suggesting there are other possibilities. Meaning \"even in the case of\" or \"talking about\".","pattern":"Noun + にしても","jlpt":"N2","tip":"Similar to と言っても or にしても, it sets a theme or provide a specific example.","example":"風景にしても壊れかかった街だとか"},{"example":"壊れかかった街","jlpt":"N3","tip":"Often implies that something is moving toward a certain state but hasn't fully reached it.","pattern":"Masu-stem + かける / かかった","meaning":"Indicates that an action has started but is not yet finished, or someone is in the middle of a process. Meaning \"in the middle of\" or \"half-finished\"."},{"example":"土塀が崩れていたり家並が傾きかかっていたり","jlpt":"N4","tip":"Always remember to end the sequence with the verb する to make it a complete predicate.","meaning":"Used to list multiple actions or states in no particular order, implying there may be other examples as well.","pattern":"Plain past + り ... Plain past + り (する)"},{"meaning":"Indicates that something happens occasionally or under certain circumstances. Meaning \"sometimes\" or \"it happens that\".","pattern":"時とすると / 時とすれば","example":"時とするとびっくりさせるような","jlpt":"N2","tip":"A formal or literary way to say \"occasionally\" or \"it is possible that\"."},{"meaning":"Expresses a strong desire or regret about a completed or hypothetical action. Meaning \"wanted to (completely) do\".","pattern":"Te-form + しまいたい (しまいたかった)","jlpt":"N4","tip":"Combining the てしまう (completion/regret) with たい (desire). It emphasizes the finality of the wish.","example":"逃げ出して誰一人知らないような市へ行ってしまいたかった"},{"pattern":"Plain past + ら","meaning":"A Conditional form used to express a hypothetical situation, often showing a wish or a preference. Meaning \"if it were the case that\".","jlpt":"N3","tip":"In the text, the auxiliary verb だ is added before ったら to create a strong hypothetical nuance (のだったら).","example":"いつの間にかその市になって（い）るのだったら"},{"pattern":"Noun + とか","meaning":"Used to list items in an informal or casual way. Similar to や or など. Meaning \"A and B and so on\".","example":"京都から何百里も離れた仙台とか長崎とか","jlpt":"N4","tip":"Very common in spoken Japanese, but also used in prose to give approximate examples."},{"example":"私にとってなんともいえない享楽だったのだ","jlpt":"N3","tip":"Usually followed by an evaluation or judgment from that specific person's perspective.","pattern":"Noun + にとって","meaning":"Used to indicate a point of view or a perspective. Meaning \"for\" or \"from the standpoint of\"."},{"pattern":"Plain past + ものだ","meaning":"Used to express a nostalgic habit or a strong feeling about something in the past. Meaning \"used to do\".","jlpt":"N2","tip":"Typically used when reminiscing about past habits or stating common sense/social norms.","example":"叱られたものだが"},{"meaning":"Indicates an action or state that is moving towards the speaker or an action that has just begun/is appearing. Meaning \"to come to be\" or \"to start to\".","pattern":"Te-form + くる","jlpt":"N3","tip":"In this context, it describes a sensation starting to arise within the speaker's mind or senses.","example":"漂って来る"},{"pattern":"Phrase + とは言え","meaning":"Used to acknowledge a previous statement but introduce a contrasting or qualifying point. Meaning \"nonetheless\" or \"be that as it may\".","jlpt":"N2","tip":"More formal than と言っても and used to bridge a known fact with a surprising or specific situation.","example":"とは言えそんなものを見て"},{"jlpt":"N3","tip":"Often used to downplay the importance or scale of something.","example":"場所に過ぎなかった","meaning":"Used to emphasize that something is \"nothing more than\" or \"only\". Meaning \"just\" or \"merely\".","pattern":"Noun / Dictionary form + に過ぎない"}],[{"pattern":"Plain negative (minus い) + ければならない","jlpt":"N4","meaning":"Expresses obligation or necessity (must/have to).","tip":"In writing, ～なければならない is standard, while ～なければいけない often implies personal or social consequences.","example":"彷徨い出なければならなかった。"},{"pattern":"Plain past + り ... Plain past + りする","jlpt":"N4","meaning":"Used to list multiple actions or states in no particular order. Often implies there are other things not mentioned.","tip":"Don't forget the final する (or specific verb form like だった) to complete the sentence after the last point in the list.","example":"裏通りを歩いたり、...立ち留まったり、...眺めたり、"},{"jlpt":"N3","meaning":"The more something happens, the more something else happens.","pattern":"Conditional ば + Dictionary form + ほど","example":"奥へゆけばゆくほど堆高く積まれている。","tip":"Both verbs must be the same. For Na-adjectives, use なら(ば) + な + ほど."},{"example":"帽子を冠った帽子の廂のように","tip":"When modifying a Noun, use the pattern のような; when modifying a Verb or Adjective, use のように.","jlpt":"N3","meaning":"Used to describe something by comparing it to something similar (like/as if).","pattern":"Noun + のように / Dictionary form + ように"},{"tip":"It describes a state where the level of one thing reaches the level of another.","example":"あそこの店は帽子の廂をやけに下げているぞ」と思わせるほどなので、","pattern":"Dictionary form + ほど","meaning":"Indicates the degree or extent of something to the point of a specific condition.","jlpt":"N3"},{"meaning":"Indicates that something seems or appears to be a certain way, focusing on external appearance or subjective impression.","jlpt":"N3","pattern":"Dictionary form + ように思える / Plain past + ように思える","example":"丸善がその時の私にはやすやすと入れるように思えた。","tip":"Unlike 思われる which is spontaneous thought, ように思える highlights the appearance or impression."},{"example":"今日は一つ入ってみてやろう","tip":"In the example, it is combined with the Volitional form ～よう and the particle やろう which adds a tone of resolve or casual intent towards oneself.","jlpt":"N4","meaning":"Indicates trying to do something to see what the result is.","pattern":"Te-form + みる"},{"pattern":"Plain past + とみえて","jlpt":"N2","meaning":"Used when making an observation based on appearance or signs (it looks as if/it seems that).","tip":"This sounds more literary or formal than ように見える. It often follows historical or narrative contexts.","example":"不吉な塊がそれを握った瞬間からいくらか弛んで来たとみえて、"},{"meaning":"A formal suffix that indicates something happens naturally or spontaneously (spontaneous potential/passive).","jlpt":"N1","pattern":"Noun + ぜられる","example":"果物屋固有の美しさが最も露骨に感ぜられた。","tip":"This is the classical/formal version of される, commonly used with nouns like 案ずる, 感ずる, or 信ずる in older literature."}],[{"meaning":"Indicates wonder, doubt, or asking oneself a question","jlpt":"N4","tip":"Use this when you are talking to yourself or expressing a mild uncertainty to others.","example":"出て行こうかなあ","pattern":"Dictionary form + かなあ"},{"jlpt":"N4","meaning":"Expresses completion of an action, often with a nuance of regret or unintended consequences","pattern":"Te-form + しまう","example":"そこへ置いてしまう","tip":"In casual speech, this often contracts to ちゃう or じゃう. During narrative prose, it highlights the finality of the state."},{"meaning":"Will not feel satisfied or settled until a specific action is performed","jlpt":"N3","tip":"This is often used for obsessive behaviors or strong emotional requirements.","example":"やってみなくては気が済まないのだ","pattern":"Plain negative + とは気が済まない"},{"tip":"This is a formal/literary version of ものでした and emphasizes a recurring habit or strong feeling from the past.","example":"周囲を見廻すときのあの変にそぐわない気持を、私は以前には好んで味わっていたものであった。","pattern":"Plain past + ものであった","meaning":"Used to describe a common occurrence or state in the past; nostalgic recollection","jlpt":"N3"},{"meaning":"Lists actions or states occurring at intervals or in random order","jlpt":"N3","example":"赤くなったり青くなったりした","tip":"Remember that the final する (or its conjugation) determines the tense of the entire sentence.","pattern":"Plain past + り + Plain past + りする"},{"pattern":"Masu-stem + ながら","example":"制しながら","tip":"The primary action comes at the end of the sentence; the ながら action is subordinate.","jlpt":"N3","meaning":"While doing; indicates two actions occurring simultaneously by the same agent"},{"meaning":"To have a feeling that; to have a hunch that","jlpt":"N3","tip":"Use this for subjective feelings or intuitions that aren't necessarily based on hard evidence.","example":"緊張しているような気がした","pattern":"Dictionary form + ような気がする"},{"pattern":"どんなに + Dictionary form + だろう","example":"大爆発をするのだったらどんなにおもしろいだろう","tip":"Often paired with words like どんなに, どれほど, or なんと to express strong emotion or wonder.","jlpt":"N3","meaning":"How...! (Emphasizing an exclamation of degree or emotion)"},{"example":"克明にはぐってゆく気持はさらに湧いて来ない","tip":"In negative sentences, さらに functions like 全く or 決して to emphasize the lack of something.","pattern":"さらに + Plain negative","meaning":"Not at all; (not) anymore (used with a negative verb)","jlpt":"N2"},{"jlpt":"N2","meaning":"Giving a suggestion or wondering about a result (elliptical form of ...たらどうですか)","pattern":"Plain past + ら","example":"一度この檸檬で試してみたら。","tip":"When a sentence ends abruptly with the conditional ら, it often implies a suggestion or a hypothetical \"What if?\""},{"jlpt":"N2","meaning":"Hard to; difficult to (stative/psychological)","pattern":"Masu-stem + がたい","example":"堪えがたさのために置いてしまった","tip":"Used for things that are psychologically or emotionally difficult to do, rather than physically impossible. Not to be confused with にくい."}]]},"hana":{"simplified":[[{"meaning":"Double negative used to express that everyone or everything does something; 'there is no one who doesn't...'","tip":"This is a common way to emphasize that a statement applies to every single person in a group.","pattern":"Plain negative + 人はいない","jlpt":"N5","example":"知らない人はいません"},{"jlpt":"N4","pattern":"Noun + のようだ/のようです","tip":"Use this when making a figurative comparison or describing an appearance based on a metaphor.","meaning":"Used to describe something by comparing it to something else; 'like' or 'similar to'","example":"ソーセージのようです"},{"pattern":"Dictionary form / Plain past + からです","jlpt":"N4","tip":"This often answers a 'why' question or explains a previous statement in a narrative.","meaning":"Used at the end of a sentence to provide a reason or explanation; 'it is because...'","example":"気にするのは恥ずかしいと思ったからです"},{"meaning":"Indicates that an action happened completely, often with a sense of regret, mistake, or lack of control","jlpt":"N4","pattern":"Te-form + しまう/しまいます","tip":"In casual speech, this often contracts to ～ちゃう. In this text, it emphasizes the accidental nature of the nose falling into the food.","example":"入ってしまいます"},{"meaning":"To have someone do something for you; used when receiving a favor or service from someone","tip":"The person performing the action is marked with the particle に. It emphasizes the benefit received by the subject.","pattern":"Te-form + もらう/もらいます","jlpt":"N4","example":"鼻を持ってもらいます"},{"tip":"Use this version of 'if' when the result is a predictable or inevitable outcome of the first action.","jlpt":"N4","pattern":"Dictionary form + と","meaning":"Expresses a natural consequence, a habit, or a factual conditional relationship; 'when' or 'if'","example":"鼻が長いと、生活が大変です"}],[{"jlpt":"N4","tip":"This changes a verb into a Noun representing the method of the action. Notice that this example replaces the particle を with no if used as a standalone Noun phrase, but here it modifies another Noun.","example":"鼻を短く見せる方法","meaning":"Way of doing; how to do","pattern":"Masu-stem + 方 (かた)"},{"jlpt":"N4","tip":"Always end the sequence with a form of the verb する. It implies there are other actions the speaker could have mentioned but didn't.","pattern":"Plain past + り ... Plain past + りする","meaning":"Doing things like A and B (non-exhaustive list)","example":"顔の向きを変えたり、手で顔を触ったりしました"},{"example":"短く見えなくて","meaning":"Not doing X and...; because not X","pattern":"Plain negative (without い) + くて","tip":"This is the Te-form of negative verbs/adjectives used to connect sentences or show a reason/cause.","jlpt":"N4"},{"jlpt":"N4","meaning":"Showing a result or reaction to the previous state","example":"短く見えなくて、がっかりしました","pattern":"Te-form + Verb","tip":"When used with emotion verbs like がっかりする, the Te-form indicates the cause of that emotion."},{"jlpt":"N4","tip":"When you use the transitive version する instead of なる, it means to intentionally make something reach that state.","meaning":"To make something (adjective)","example":"鼻を短くする薬","pattern":"I-adjective (without い) + くなる / Na-adjective + になる"},{"example":"15センチのままでした","meaning":"To remain in a certain state; as it is","pattern":"Noun + のまま / Plain past + まま","tip":"This indicates that a condition remains unchanged, often contrary to expectations or efforts to change it.","jlpt":"N3"},{"example":"やってみることにしました","meaning":"To try doing something to see what happens","pattern":"Te-form + みる","tip":"This is often used when doing something for the first time or as an experiment.","jlpt":"N3"},{"meaning":"To decide to do something","example":"やってみることにしました","pattern":"Dictionary form + ことにする","tip":"Use this when the speaker has made a conscious decision or choice about their own future actions.","jlpt":"N3"}],[{"pattern":"Te-form + ください","jlpt":"N5","tip":"This is the standard polite way to ask someone to perform an action. For negative requests, use the Plain negative form + でください.","meaning":"Please do (polite request)","example":"踏んでください"},{"example":"鼻と同じくらい短くなっていた","meaning":"About the same (degree/extent) as...","tip":"This is used to compare two things that are roughly equal in degree. It can be followed by an adjective or a verb.","jlpt":"N4","pattern":"Noun + と同じくらい"},{"tip":"When ending a sentence with からです, you are providing the explanation for a previously mentioned situation. Use the Dictionary form or Plain past before it.","pattern":"Clause + からです","jlpt":"N4","example":"短くなっていたからです","meaning":"Because it is (stating a reason)"},{"example":"鼻を踏んでもらいます","meaning":"To have someone do something (for one's benefit)","tip":"This expresses that the speaker (or the subject) received a favor. Unlike ～てくれる, the subject of this sentence is the receiver of the action.","pattern":"Te-form + もらう","jlpt":"N4"}],[{"meaning":"To reach a point where something happens or starts to be the case; a change in habit or state","pattern":"Dictionary form + ようになる","jlpt":"N4","example":"笑うようになります","tip":"This indicates a gradual change or a new development compared to the past."},{"pattern":"Dictionary form + こと","meaning":"Nominalizes a Clause, turning a sentence into a Noun phrase to describe a fact or action","example":"鼻が短くなったこと","jlpt":"N4","tip":"Use this when you need to treat an entire action or occurrence as the object of a verb like 'to regret' or 'to know'."},{"pattern":"Potential form + ない/ませんでした","meaning":"The negative Potential form, indicating that someone is unable to do something","jlpt":"N4","example":"眠れませんでした","tip":"While simple potential is common, the negative potential in this context highlights an external or internal inability to perform the action."},{"tip":"This is used for comparing degrees of emotion, size, or quality between two things.","example":"鼻が短くなった時と同じくらい","jlpt":"N3","pattern":"Noun + と同じくらい","meaning":"To the same extent as; as much as; about the same level as"},{"meaning":"Probably; I think; expressing a conjecture or a high degree of probability","pattern":"Dictionary form + だろう/でしょう","jlpt":"N4","example":"笑う人はいないだろう","tip":"This is the plain version of 'deshou' and is used when the speaker is making a guess based on their own reasoning."}]],"intermediate":[[{"meaning":"Double negative meaning 'everyone knows' or 'there is no one who doesn't'","pattern":"Plain negative + 人はいない","jlpt":"N4","example":"知らない人はいない","tip":"This is a common way to emphasize that something is universally known or true within a certain group."},{"meaning":"Similar to; like (used for metaphors and comparisons)","pattern":"Noun + のような","jlpt":"N4","example":"ソーセージのようなものが","tip":"Use this pattern when you want to compare a Noun to something else using a simile. Remember it functions like a Na-adjective to modify the following Noun."},{"pattern":"Noun + くらい","meaning":"Approximately; about (referring to quantity or degree)","tip":"When used with counters or measurements, it indicates an approximate amount. It is interchangeable with ぐらい.","example":"十五センチくらいあって","jlpt":"N4"},{"meaning":"To look like; to act as if; to have the appearance of","pattern":"Dictionary form + ような顔をする","jlpt":"N4","tip":"This expresses an outward appearance or facial expression that suggests a certain state or feeling.","example":"それほど気にしていないような顔をしている"},{"example":"極楽浄土へ行くことを一番に考えるべきお坊さん","tip":"Note that for the verb する, both するべき and すべき are acceptable, though すべき is more formal.","jlpt":"N3","meaning":"Should; ought to; must (expresses moral obligation or a natural expectation)","pattern":"Dictionary form + べき"},{"example":"鼻がお茶碗の中に入ってしまう","tip":"In this context, it emphasizes the accidental and unfortunate nature of the nose falling into the bowl.","jlpt":"N4","pattern":"Te-form + しまう","meaning":"To do something completely, or to do something accidentally/regrettably"},{"jlpt":"N3","example":"ご飯を食べる間","tip":"Ensure the action in the main Clause lasts for the same entire duration as the action before 間.","meaning":"While; during the time that (expresses a continuous action or state)","pattern":"Dictionary form + 間"},{"pattern":"Noun + にとっても","meaning":"For; from the standpoint of; as far as ... is concerned","jlpt":"N3","tip":"This is used when giving an evaluation or opinion from a specific person's perspective. The も adds the nuance of 'also' or 'even'.","example":"弟子にとっても"},{"example":"鼻のせいで傷つく","tip":"Always use this when attributing a negative outcome to a specific cause. If the result is positive, use おかげで instead.","jlpt":"N3","pattern":"Noun + のせいで","meaning":"Because of; due to (used for negative results/reasons)"}],[{"example":"鼻が短く見えないか試した","tip":"This expresses a trial action; in the text, it is often combined with 'tamesu' (to try/test) for emphasis.","jlpt":"N4","pattern":"Te-form + みる","meaning":"To try doing something in order to see what the result will be"},{"example":"鼻なんか気にしていないという態度をとって","pattern":"Noun + なんか","meaning":"Emphasizes a feeling of dismissal, belittlement, or distain toward a topic","tip":"It is a more informal version of 'nado'. Here it shows the priest is pretending his nose is trivial.","jlpt":"N4"},{"example":"鼻を短くする方法もたくさん試した","pattern":"Masu-stem + 方 (かた)","meaning":"The way or method of doing something","tip":"When using this pattern, the particle 'o' usually changes to 'no' for the preceding Noun, but it can also follow a complex Clause.","jlpt":"N4"},{"jlpt":"N4","tip":"Use this when comparing two things that share very similar characteristics.","pattern":"Noun + と同じような","meaning":"Similar to; like something else","example":"自分と同じような鼻の人"},{"example":"顔の向きを変えたり、手で頬を押さえたりして","jlpt":"N4","tip":"It implies that the listed actions are just examples and other actions might have also taken place.","pattern":"Plain past + り ... Plain past + りする","meaning":"Listing actions or states among others (representative list)"},{"example":"その方法を試すことにした","meaning":"To decide on a course of action (subjective decision)","pattern":"Dictionary form + ことにする","tip":"Contrast this with 'koto ni naru', which signifies a decision made by an outside force or group.","jlpt":"N4"},{"tip":"In the text, 'to' is used to connect the intention to the following action. 'To suru' specifically means to try or struggle to perform the action.","jlpt":"N3","meaning":"Attempting to do something or showing an intention to do something","pattern":"Volitional form + と (する)","example":"鼻を短くしようと、色々な方法を試した"},{"example":"何をしても、鼻は十五センチの長さのまま","tip":"It expresses persistence. Here, the nose stays 15cm despite all the strange medical attempts.","jlpt":"N3","pattern":"Noun + のまま","meaning":"Indicates that a state remains unchanged, even when it might be expected to change"},{"tip":"When it modifies a Noun directly, use 'no you na'. When it modifies a verb or adjective, use 'no you ni'.","jlpt":"N3","pattern":"Noun + のように","meaning":"Used to introduce an example or to describe something by comparing it to something else","example":"内供のように長い鼻の人"},{"example":"ただ気休めを探すだけでなく","tip":"This is a common way to expand on information, showing that the first point is not the only factor.","jlpt":"N3","pattern":"Dictionary form + だけでなく","meaning":"Not only A, but also B"}],[{"tip":"While polite, this is still a direct request; use more indirect forms with superiors.","example":"踏んでください","jlpt":"N5","pattern":"Te-form + ください","meaning":"Used to make a polite request or give an instruction"},{"example":"踏んでもらう","tip":"This focuses on the speaker's gratitude or initiative in receiving the action.","jlpt":"N4","pattern":"Te-form + もらう","meaning":"To have someone do something for the benefit of the speaker; to get someone to do something"},{"pattern":"Dictionary form + だろう","jlpt":"N4","tip":"This is the plain version of でしょう and is often used in internal monologues or when speaking to oneself.","example":"笑わないだろう","meaning":"Expresses a conjecture, probability, or a guess about a future or current state"},{"meaning":"Indicates that when one action takes place, another action or state naturally follows or is discovered","example":"踏んでいると","tip":"In this context, it often describes a discovery after performing a continuous action.","jlpt":"N4","pattern":"Dictionary form + と"},{"meaning":"Indicates that something appears or looks to be a certain way based on visual evidence","pattern":"Na-adjective (no な) + そうだ","jlpt":"N4","example":"満足そうだった","tip":"When using this with Na-adjectives, simply drop the な and add そう."},{"meaning":"Expresses contrast, contradiction, or unexpectedness (despite/although)","pattern":"Dictionary form + のに","jlpt":"N3","tip":"The Clause following のに usually expresses a feeling of surprise, frustration, or unexpected results.","example":"踏まれているのに"},{"meaning":"Indicates that two actions are being performed simultaneously by the same person","example":"踏まれながら","tip":"The primary action (the one the speaker wants to emphasize) comes after ながら.","jlpt":"N3","pattern":"Masu-stem + ながら"},{"pattern":"Noun + のような","jlpt":"N3","example":"後のような","tip":"This acts like an adjective to modify the Noun that follows it.","meaning":"Used to describe something by comparing it to something else (resemblance)"},{"meaning":"Indicates the completion or finishing of an action, often implying it was done thoroughly","jlpt":"N3","pattern":"Masu-stem + 上がる","tip":"Commonly used with cooking or creative tasks to show the final result is ready.","example":"茹で上がっていた"}],[{"meaning":"Expresses regret or the wish that one had not done something in the past.","jlpt":"N4","pattern":"Plain negative past (conditional) + よかった","tip":"This literally means 'it would have been good if I hadn't...' and is the standard way to express regret for an action.","example":"あんな短い鼻にしなければよかった"},{"meaning":"Expresses a conjecture, guess, or a polite assertion about a situation.","jlpt":"N4","pattern":"Dictionary form + だろう","tip":"Use this when you are fairly sure but not 100% certain, or when pondering to yourself.","example":"もう誰も私を笑う人はいないだろう"},{"jlpt":"N4","pattern":"Masu-stem + に","tip":"In this context, it marks the reason for coming: 'came in order to read the sutras'.","meaning":"Indicates the purpose of a movement (going, coming, or returning).","example":"お経を読みに来たお侍さんが"},{"example":"周りの人が笑うたびに","meaning":"Expresses that every time a certain action happens, another action or state occurs.","tip":"This emphasizes a recurring pattern. For nouns, use 'Noun + の + たびに'.","jlpt":"N3","pattern":"Dictionary form + たびに"},{"meaning":"Used to provide an example or describe something that is similar to or like something else.","pattern":"Noun + というような","jlpt":"N3","tip":"This is a more specific and descriptive version of 'Noun + のような' used to characterize a speech, thought, or appearance.","example":"前よりもおかしいというような顔をして"},{"example":"不幸な状態に戻してみたいとすら思うのだ","tip":"It is often used in negative contexts or to highlight an extreme feeling or reaction.","jlpt":"N2","pattern":"Noun + すら","meaning":"Emphasizes an extreme or unexpected case, similar to 'even' or 'to the extent of'."}]],"original":[[{"meaning":"Speaking of; used to pick up a topic previously mentioned or known by both parties","pattern":"Noun + と云えば","tip":"This is often used to introduce more specific information or a personal reaction to a known subject.","example":"鼻と云えば","jlpt":"N3"},{"example":"腸詰めのような物","jlpt":"N3","meaning":"Like; similar to (used for metaphorical comparisons)","tip":"This acts like a Na-adjective and must be followed by a Noun. To describe a verb, use ように.","pattern":"Noun + のような"},{"meaning":"The fact that; used to nominalize a sentence to comment on its characteristics or feelings","tip":"The first の is a subject marker used in descriptive clauses; the second の turns the adjective phrase into a Noun.","pattern":"Noun + の + I-adjective + の","example":"鼻の長いのが不便だった","jlpt":"N3"},{"jlpt":"N4","example":"とどいてしまう","pattern":"Te-form + しまう","tip":"In this context, it emphasizes the unfortunate physical reach of the nose touching the food.","meaning":"To do something completely; often implies regret or an accidental/unfortunate outcome"},{"jlpt":"N4","example":"持上げていて貰う事にした","tip":"Contrast this with ことになっている which implies an external rule or existing arrangement.","pattern":"Dictionary form + 事にした","meaning":"To decide to; indicates a decision made by an individual or choice of action"},{"meaning":"For; from the standpoint of; used when giving an evaluation or opinion from a specific perspective","pattern":"Noun + にとっても","tip":"Adding も adds the nuance of 'also' or 'even' for that specific person.","example":"内供にとっても","jlpt":"N3"},{"example":"批判する者さえあった","jlpt":"N3","meaning":"Even; used to emphasize an extreme example to show the extent of a situation","tip":"It often replaces particles like が or を. It suggests that if this extreme is true, other things are naturally true as well.","pattern":"Noun + さえ"},{"example":"鼻を苦に病んだ重な理由ではない","jlpt":"N3","meaning":"It is not that; it is not the case that (used to clarify a reason or situation)","tip":"When used after a full explanatory Clause ending in a Noun, it refutes a specific logical conclusion.","pattern":"Noun + ではない"},{"jlpt":"N3","example":"自尊心のために苦しんだ","tip":"When following a Noun that is an emotion or abstract concept, it usually indicates the cause of a struggle.","pattern":"Noun + のために","meaning":"Because of; for the sake of; indicates a reason, cause, or purpose"},{"example":"余りにデリケイトに出来ていた","jlpt":"N3","meaning":"Too much; excessively; used to indicate that a state is beyond the appropriate limit","pattern":"余りに + Adjective/Verb","tip":"This is a more formal version of すぎる and often appears in literary texts."}],[{"tip":"The main action comes after the ながら Clause. Both actions must be performed by the same subject.","pattern":"Masu-stem + ながら","jlpt":"N4","example":"顔を映しながら","meaning":"While doing or at the same time as something else"},{"meaning":"To have an experience in the past (used with 'none' to mean 'never')","example":"鼻が短く見えた事は、これまでにただの一度もない。","pattern":"Dictionary form + 事がある/ない","jlpt":"N4","tip":"Focuses on the existence or absence of a specific experience or occurrence."},{"meaning":"Doing something in a manner like... or pretending to be...","example":"鼻などを気にかけないと云う風をして","pattern":"Noun + という風をする/ Dictionary form + という風をする","jlpt":"N3","tip":"Similar to ～振（ふ）りをする, it describes the outward appearance or manner someone adopts."},{"jlpt":"N3","pattern":"Conditional (ば) form + Dictionary form + ほど","tip":"Repeat the same verb in the conditional and then the Dictionary form for emphasis.","meaning":"The more something happens, the more another thing changes in proportion","example":"苦心すればするほど"},{"tip":"Often used to highlight a minimum requirement or an unexpected level of intensity.","jlpt":"N3","pattern":"Noun + さえ / Clause + さえ","example":"長く見えるような気さえした。","meaning":"Even, so much as (used to emphasize an extreme or surprising point)"},{"meaning":"Even though; despite; although","example":"積極的な苦心をしながらも","jlpt":"N3","pattern":"Masu-stem + ながら（も）","tip":"Usually indicates a contrast between two states or actions, similar to 'although' in English."},{"example":"ここに云うまでもない。","meaning":"Needless to say; it goes without saying that...","tip":"Used when something is so obvious or simple that performing the action is unnecessary.","pattern":"Dictionary form + までもない","jlpt":"N3"},{"pattern":"Noun + の / Dictionary form + が + 如く","jlpt":"N2","tip":"This is a classical/literary equivalent of ように. Frequently seen in literature or fixed idioms.","meaning":"Like; as if (archaic/literary style)","example":"有れども無きが如くである。"},{"tip":"Indicates that as one change occurs, another change happens simultaneously or as a result.","pattern":"Dictionary form + に従って","jlpt":"N2","example":"度重なるに従って","meaning":"As; in proportion to; along with (a change taking place)"},{"example":"この策略がわからない筈はない。","meaning":"It is impossible that... / There is no way that...","tip":"Expresses a strong objective denial based on logic or expectation.","jlpt":"N2","pattern":"Dictionary form + 筈はない"}],[{"example":"指も入れられないような熱い湯","meaning":"Used to provide an illustrative example or to describe something by way of comparison. Often translated as 'like' or 'such as'.","jlpt":"N4","tip":"Unlike '～そう', which describes appearances, '～よう' describes the nature or state of something by comparing it to something else.","pattern":"Dictionary form + ような"},{"pattern":"Dictionary form + からである","example":"誰も鼻の話とは気がつかないだろうと思ったからである。","tip":"This is the formal/written equivalent of using '～からだ' at the end of a sentence.","meaning":"Formal way to state a reason or logic, often used in writing to mean 'it is because'.","jlpt":"N4"},{"meaning":"To begin or start an action. Grammatically attaches to the stem of a verb.","jlpt":"N4","tip":"This focus is specifically on the initiation of an ongoing process, compared to '～だす' which implies a sudden start.","example":"両足に力を入れながら、踏みはじめた。","pattern":"Masu-stem + はじめる"},{"example":"両足に力を入れながら、踏みはじめた。","tip":"The main action is always the second verb (the one following 'nagara').","meaning":"Indicates that two actions are being performed simultaneously by the same person.","jlpt":"N4","pattern":"Masu-stem + ながら"},{"pattern":"Dictionary form + くらい/ぐらい","tip":"It can also be used for approximations, but here it emphasizes the intensity of the feeling.","meaning":"Used to describe the extent or degree of a state, often translated as 'to the extent that' or 'so much so that'.","jlpt":"N3","example":"痛いよりもかえって気もちのいいくらいだったのである。"},{"example":"これを茹でればようござる。","meaning":"The Conditional form indicating 'if'. In this context, '～ばよい' suggests 'it would be good if...' or 'you should...'.","jlpt":"N3","tip":"In the text, 'ようござる' is a polite/archaic variation of 'よい'. This pattern is frequently used for giving advice.","pattern":"Conditional form (ば-form) + よい/いい"},{"example":"弟子の僧のするなりに任せて置いた。","tip":"In many cases, the 'o' is dropped in casual speech (～とく), but the formal/written '～ておく' remains standard.","meaning":"Used to express completion of an action, or more commonly, doing something in advance for future convenience.","jlpt":"N3","pattern":"Te-form + おく"},{"example":"親切がわからない訳ではない。","tip":"Use this when you want to avoid a strong, absolute 'no' and instead clarify a nuance.","meaning":"A partial negation meaning 'it's not that...' or 'it doesn't mean that...'. It acknowledges one side while implying there is more to the story.","jlpt":"N3","pattern":"Dictionary form + 訳ではない"},{"example":"弟子の僧の云うなりになっていた。","tip":"It often carries a nuance of passivity, where the subject follows a course of action without resistance.","meaning":"To do as something or someone dictates; 'to be at the mercy of' or 'exactly as...'.","jlpt":"N2","pattern":"Noun + なり / Dictionary form + なり"},{"pattern":"Dictionary form + にちがいない","example":"もう誰も哂うものはないにちがいない。","meaning":"Used to express a strong conviction or certainty on the part of the speaker; 'without a doubt' or 'must be'.","jlpt":"N2","tip":"Based on objective evidence or strong intuition, this expresses 100% confidence."}],[{"meaning":"Expresses that as long as one condition is met, everything else is alright; 'if only' or 'as long as'.","jlpt":"N3","pattern":"Noun + さえ + Conditional form (ば) form","example":"暇さえあれば手を出して","tip":"When using a verb instead of a Noun, you use the Stem + さえすれば pattern."},{"example":"鼻ばかり眺めていた事である","tip":"While it can mean 'approximately' with numbers, here it emphasizes an exclusive or repetitive action.","jlpt":"N4","meaning":"Used to indicate that something is the only thing being done, or that someone is doing nothing but one specific thing.","pattern":"Noun + ばかり + Verb"},{"tip":"This is a more objective-sounding version of 'hazu da'. Use it when you are making a deduction based on evidence.","example":"そこにあるのにちがいない","pattern":"Dictionary form + にちがいない / Noun + にちがいない","jlpt":"N3","meaning":"Expresses a strong certainty or conviction on the part of the speaker; 'must be' or 'there is no doubt'."},{"jlpt":"N2","meaning":"Used to emphasize a reason, stating that there is no other possible cause; 'none other than' or 'precisely because'.","pattern":"Noun + にほかならない / Clause + からにほかならない","example":"何となく不快に思ったのは...感づいたからにほかならない","tip":"This is a very formal expression often used in writing to provide a definitive explanation."},{"jlpt":"N2","meaning":"A suffix added to a verb to indicate doing something with great force or doing something thoroughly/violently.","pattern":"Masu-stem + つける","example":"誰でも意地悪く叱りつける","tip":"Common examples include 叩きつける (to slam down) or 怒鳴りつける (to shout at). It adds an aggressive nuance."},{"meaning":"A sentence-ending particle used to emphasize a statement or give a warning, typically by male speakers.","jlpt":"N4","pattern":"Dictionary form + ぞ","example":"内供は法慳貪の罪を受けられるぞ","tip":"In modern Japanese, this is mostly used by men in casual speech or in fiction to show authority or assertiveness."},{"tip":"In this text, it is used as a cry in a game, but generally, it is a formal/literary way to say 'nai darou' or 'nai tsumori'.","example":"鼻を打たれまい","pattern":"Dictionary form + まい (for Group 2/3) / Masu-stem + まい (for Group 1)","jlpt":"N2","meaning":"Expresses a negative intention (will not) or a negative conjecture (probably not)."},{"jlpt":"N4","meaning":"Indicates that two actions are being performed simultaneously by the same person.","pattern":"Masu-stem + ながら","example":"鼻を打たれまい...と囃しながら","tip":"The primary action is the one following the ながら. It can also mean 'although' depending on the context."},{"tip":"This is less common in casual speech than 'hito'. It often defines a category of person based on their behavior.","example":"もう誰も哂うものはないにちがいない","pattern":"Dictionary form + もの","jlpt":"N3","meaning":"Refers to a person/people who do a certain action in a formal or literary context."}]]},"matsu":{"simplified":[[{"meaning":"To go somewhere for the purpose of doing something.","example":"人を迎えに行きます","tip":"The'ni'particle indicates the goal or purpose of the movement.","jlpt":"N4","pattern":"Masu-stem + に行く"},{"pattern":"Plain past + 後 (あと)","jlpt":"N4","meaning":"After doing something; indicates a sequential relationship.","tip":"Always use the past tense'ta'form before'ato', even if the overall sentence describes a future or habitual action.","example":"買い物をした後"},{"example":"電車が来るのをずっと待ちます","tip":"Use this when you want to treat an action as a thing, common with verbs like'see','hear', or'wait for'.","meaning":"Turning a verb/Clause into a Noun phrase to make it the object of a sentence.","jlpt":"N4","pattern":"Dictionary form + の"},{"pattern":"Dictionary form + と","jlpt":"N4","meaning":"A natural, inevitable, or habitual consequence. Whenever A happens, B follows.","example":"電車が来ると","tip":"This specific'to'implies that the second action happens almost automatically or predictably every time."},{"meaning":"Appearing to be; looking like. Used to describe the likeness or appearance of something.","tip":"This is used for metaphors or when providing examples based on visual assessment.","example":"怒っているような顔です","pattern":"Dictionary form + ような + Noun","jlpt":"N3"},{"tip":"Use this to emphasize that a condition or action persists while another action takes place.","example":"座ったまま","meaning":"State of remaining unchanged; doing something while keeping a previous state or condition.","pattern":"Plain past + まま","jlpt":"N3"},{"jlpt":"N3","pattern":"Dictionary form + のでしょうか","meaning":"An explanatory or polite way to ask a question or express a thought/wondering.","tip":"This is softer and more reflective than just asking'ka'. It adds a sense of'I wonder'or'is it that case?'.","example":"誰を待っているのでしょうか"}],[{"tip":"While basic, it highlights a continuous habit or routine when used with time markers like 毎日 (every day).","example":"家で手伝いをしています","meaning":"Indicates an ongoing action or a current state/habit.","pattern":"Te-form + いる","jlpt":"N5"},{"meaning":"Indicates that an action or state has continued since a specific event happened.","example":"戦争が始まってから","tip":"This emphasizes the starting point of a sequence. Don't confuse it with the Noun + から meaning'from'.","jlpt":"N4","pattern":"Te-form + から"},{"pattern":"Te-form + しまう","jlpt":"N4","tip":"In this context, it suggests a lack of control over the urge to wait or a sense of helplessness.","example":"待ってしまいます","meaning":"Expresses completing an action, or doing something unintentionally/regrettably."},{"meaning":"Expresses a possibility or a guess that something might happen (roughly 50% certainty).","tip":"This is often used for subjective guesses. In polite speech, use かもしれません.","example":"私と話すかもしれない","pattern":"Dictionary form + かもしれない","jlpt":"N4"},{"tip":"The の (or ん) adds an explanatory or inquisitive tone, making the question sound more reflective.","example":"待っているのでしょうか","meaning":"A polite way to ask a question with a nuance of curiosity or wondering.","pattern":"Dictionary form + のでしょうか","jlpt":"N3"},{"pattern":"Clause + Noun","jlpt":"N4","meaning":"The entire Clause before the Noun acts as an adjective to describe that Noun.","tip":"In Japanese, there are no relative pronouns like'who'or'which'; simply put the verb phrase directly before the Noun.","example":"苦しい毎日を変える、何か"},{"jlpt":"N3","pattern":"Dictionary form + ことしかできない","meaning":"Indicates that there is no other option or possibility but the one mentioned.","example":"待つことしかできません","tip":"しか must be followed by a negative verb. It emphasizes that the action is the only choice available."},{"pattern":"Te-form + も","jlpt":"N4","meaning":"Expresses'no matter what'or'even if'. Highlighting a condition that doesn't change the outcome.","tip":"When paired with question words like 何 (what) or どこ (where), it translates to'no matter what/where'.","example":"他の人が何と言っても"}]],"intermediate":[[{"example":"人を迎えに行きます","meaning":"Going to a place with the purpose of doing something.","tip":"The に particle marks the purpose of movement, and the verb before it must be in its stem form.","jlpt":"N4","pattern":"Masu-stem + に行く"},{"example":"買い物を済ませた後","meaning":"After doing something or after a specific event.","tip":"Note that when using a verb, it must always be in the past tense even if the overall sentence refers to the future.","pattern":"Plain past + 後 (あと) / Noun + の後 (あと)","jlpt":"N4"},{"meaning":"Without doing something; a more formal/literary version of ～ないで.","example":"家には帰らず","pattern":"Masu-stem (negative) + ず","jlpt":"N3","tip":"This is often used to connect clauses. Remember that the irregular verb する becomes せず."},{"tip":"Unlike こと, の is often used for actions happening right before your eyes, like seeing, hearing, or waiting for something.","jlpt":"N4","pattern":"Dictionary form + の","example":"電車が着くのを待ちます","meaning":"Turning a verb or Clause into a Noun to make it the object of a sentence."},{"jlpt":"N3","pattern":"Dictionary form + たびに / Noun + のたびに","tip":"This emphasizes that every single instance of the action is followed by the same result. It cannot be used for everyday routine occurrences like'every morning'.","meaning":"Every time something happens; whenever a certain action occurs.","example":"電車が着くたびに"},{"example":"怒っているような顔をして","meaning":"To look like or appear as if; used for comparisons or descriptions based on appearance.","tip":"Use this when something resembles something else or is an example of a certain state.","pattern":"Dictionary form + ような / Noun + のような","jlpt":"N4"},{"meaning":"Leaving something in a certain state; doing something while a previous state remains unchanged.","example":"ぼんやり座ったまま","jlpt":"N3","pattern":"Plain past + まま / Noun + のまま","tip":"It often implies that a state is continuing longer than expected or is being left as is."},{"meaning":"An embedded question within a sentence.","example":"誰を待っているのか","pattern":"Dictionary form + か (どうか)","jlpt":"N4","tip":"If an interrogative word (like who, what, or where) is used, simply use か. Without an interrogative, use かどうか (whether or not)."}],[{"jlpt":"N4","pattern":"Noun + ほど","tip":"Unlike くらい, ほど is often used to emphasize the extent or degree of something.","meaning":"Approximately/about a certain amount or degree","example":"十五分ほどのとろこにあります"},{"meaning":"Ever since a certain action or event took place","example":"戦争が始まってから","pattern":"Te-form + から","jlpt":"N4","tip":"This indicates that a state has continued uninterrupted since the starting point."},{"tip":"In this context, it suggests an habitual action the speaker cannot help but perform.","pattern":"Te-form + しまう","jlpt":"N4","example":"待ってしまいます","meaning":"To do something unintentionally or to end up in a certain state (often with regret)"},{"jlpt":"N4","pattern":"Dictionary form + かもしれない","tip":"It expresses a subjective guess with low certainty (around 50% or less).","meaning":"Perhaps; might; it is possible that...","example":"期待しているのかもしれません"},{"tip":"This focuses on a single action or state, excluding all other possibilities.","pattern":"Dictionary form + だけ","jlpt":"N4","example":"急いで帰っていくだけです","meaning":"Only; just; nothing but"},{"jlpt":"N3","pattern":"Dictionary form + わけではない","tip":"Used to partially deny a logical assumption or provide a nuanced clarification.","meaning":"It doesn't mean that; it's not the case that...","example":"待っているわけではありません"},{"meaning":"To look forward to something","example":"春が来るのを楽しみにしている","pattern":"Noun + を楽しみにする","jlpt":"N3","tip":"Use the particle を when you are the one looking forward to it as an active state."},{"jlpt":"N3","pattern":"Dictionary form + ような+ Noun","tip":"This is used for metaphors or to describe a Noun by giving an example of its qualities.","meaning":"Like; similar to; of the kind that...","example":"変えてくれるような何か"},{"example":"入ってくるたびに","meaning":"Every time; whenever something happens","tip":"Focuses on the repetition: whenever \"A\"happens, \"B\"always follows. Often used for highlight-worthy events.","jlpt":"N3","pattern":"Dictionary form + たびに"},{"meaning":"Can do nothing but; have no choice but to...","example":"待つことしかできないのです","pattern":"Dictionary form + ことしかできない","jlpt":"N3","tip":"The negative ending is required with しか to emphasize the limitation to a single option."},{"example":"待っていることほど、馬鹿げたことはない","meaning":"Nothing is more... than [A] (expressing [A] is the most...)","tip":"This is a superlative structure used to express that nothing reaches the level of the subject.","jlpt":"N3","pattern":"Noun + ほど + (negative adjective/verb) + ことはない"},{"jlpt":"N3","pattern":"Masu-stem + 続ける","tip":"This indicates a continuous or repeated action over a period of time.","meaning":"To continue doing something without stopping","example":"待ち続けています"},{"jlpt":"N2","pattern":"Volitional form form + と (particle)","tip":"Often used with question words to mean \"no matter who/what/how.\"It expresses a strong determination.","meaning":"No matter what/who... (regardless of...)","example":"誰が何と言おうと"}]],"original":[[{"meaning":"Expresses that something happens every time another thing occurs or repeats","tip":"Similar to'tabi ni', but'goto ni'is often used for regular intervals or occurrences.","jlpt":"N3","pattern":"Dictionary form + ごとに","example":"電車がホームに到着するごとに"},{"jlpt":"N4","tip":"Use this when making a subjective comparison based on visual appearance.","meaning":"Indicates a resemblance or appearance; to look like or act as if","example":"怒っているような顔をして","pattern":"Dictionary form + ような / Noun + のような"},{"jlpt":"N3","meaning":"Emphasizes that just one small action or thought is enough to trigger a strong reaction","tip":"Often used with verbs of feeling, thinking, or seeing to show intensity.","example":"考えただけでも","pattern":"Dictionary form + だけ（で）"},{"jlpt":"N4","meaning":"Functions as an adverb to describe the manner of an action by comparison","tip":"When used mid-sentence to describe a verb or adjective, it functions like the English word'like'.","example":"冷水をかけられたように","pattern":"Dictionary form + ように / Noun + のように"},{"example":"人間でないかも知れない","pattern":"Dictionary form + かもしれない","jlpt":"N4","tip":"It suggests a 50/50 chance and is less certain than'deshou'.","meaning":"Expresses a possibility or a guess that something might be true"},{"pattern":"Masu-stem + たくも＋ない/ない形 negative form","example":"言いたくもない挨拶","meaning":"Emphasizes a negative feeling or lack of desire toward an action","tip":"The'mo'adds emphasis, suggesting'not even'wanting to do it.","jlpt":"N3"},{"jlpt":"N3","tip":"Usually used with emotive verbs or adjectives to express extreme uncontrollable feelings.","meaning":"Cannot help but feel a certain way; an emotion or physical sensation is unbearable","example":"いやでいやでたまらなくなります","pattern":"Te-form + たまらない"},{"pattern":"Dictionary form + ものだ / もの（なの）だ","example":"一生を送るものなのでしょうか","tip":"It often carries a nuance of social norms, common sense, or a deep realization.","meaning":"Indicates a general truth, an essence of something, or how something should be","jlpt":"N3"},{"tip":"In negative contexts like'nai kagiri', it translates closely to'unless'.","meaning":"As long as; unless (sets a condition for the rest of the sentence to be true)","jlpt":"N2","pattern":"Dictionary form + 限り / Noun + である＋限り","example":"よほどの事でもない限り"}],[{"tip":"Often used with negative or pessimistic conclusions, emphasizing a sense of futility.","jlpt":"N1","meaning":"Even if / even though; used to express that even if an action is taken, the result will be useless or unchanged.","example":"外に出てみたところで","pattern":"Te-form + ところで"},{"jlpt":"N4","tip":"When a sentence ends with this, it often implies a hidden wish like'I wish...'or'What if...?'","meaning":"Expressing a wish, hope, or hypothetical situation ending abruptly.","example":"ひょいと現われたら！","pattern":"Plain past + ら"},{"meaning":"Something like; used to give an example or describe something in an indirect, illustrative way.","example":"きまってしまうのだというような","pattern":"Dictionary form + というような","jlpt":"N3","tip":"Use this to provide a representative example of a feeling, statement, or category."},{"jlpt":"N3","tip":"It describes a degree so extreme that it reaches the level of the action mentioned.","pattern":"Dictionary form + ほど","meaning":"To the extent that; used to indicate the degree or scale of a state.","example":"窒息するほどくるしくなります"},{"jlpt":"N4","tip":"In casual speech or literature, it functions similarly to'youni'but feels slightly more colloquial or visual.","pattern":"Plain past + みたいに","meaning":"Like; similar to; used to describe something by comparing it to something else (metaphor).","example":"覗いたみたいに"},{"meaning":"Might; perhaps; used to express a possibility or the speaker's conjecture.","example":"女なのかも知れない","pattern":"Dictionary form + かも知れない","jlpt":"N4","tip":"The'da'from'na-adjectives'and nouns is dropped before this pattern."},{"meaning":"The thing called; as for the matter of; used to define or emphasize the topic.","example":"お役に立ちたいというのは嘘で","pattern":"Dictionary form + というのは","tip":"It is often used to define a term or provide an explanation for a specific statement.","jlpt":"N3"},{"jlpt":"N3","tip":"This is a shortened form of'Volitional form + to omou'or'Volitional form + to suru', focusing on the intent behind an action.","meaning":"Attempting to; in an effort to; expressing an intention to perform an action.","example":"空想を実現しようと","pattern":"Volitional form + と"},{"example":"駅へお迎えに行っては","meaning":"Repeatedly doing an action; whenever one does... they always...","pattern":"Te-form + は","tip":"This highlights a repetitive or habitual action that occurs under certain conditions.","jlpt":"N3"},{"tip":"In this context, it implies keeping a memory or state of mind for the future.","jlpt":"N4","example":"覚えて置いて下さいませ","meaning":"Do something in advance or leave something in a certain state (applied here with polite'mase').","pattern":"Te-form + おく"},{"tip":"This is a very formal humble form, common in refined speech or classical-leaning modern literature.","jlpt":"N3","meaning":"Humble expression (Kenjougo) used to refer to the speaker's own actions toward someone respected.","example":"お教え申しません","pattern":"O + Masu-stem + 申す"}]]},"gyofukuki":{"simplified":[[{"pattern":"Dictionary form + と","meaning":"Indicates a natural consequence or an inevitable result (whenever A happens, B follows)","tip":"Commonly used for natural phenomena, directions, or mechanical operations.","example":"秋になると","jlpt":"N4"},{"example":"夏から秋にかけて","tip":"Unlike ～から～まで, this pattern implies a fuzzy or continuous boundary.","jlpt":"N3","meaning":"From... through... (indicates a general range of time or space)","pattern":"Noun + から + Noun + にかけて"},{"jlpt":"N4","tip":"Often used to correct a misconception or provide a specific clarification.","example":"自分で死んだのではありません","meaning":"It is not the case that... (polite negation of an explanation)","pattern":"Dictionary form + のではありません"},{"jlpt":"N4","example":"落ちて死んだのです","tip":"In speech, this often becomes ～んです. It connects the statement to the context.","pattern":"Dictionary form + のです","meaning":"Used to provide an explanation, emphasize a fact, or give a reason for a situation"},{"pattern":"Masu-stem + やすい","meaning":"Easy to do (indicates a tendency or physical ease of action)","jlpt":"N4","example":"滑りやすかったです","tip":"The resulting word functions as an I-adjective. Its opposite is ～にくい."},{"meaning":"To try to do or attempt to do something","pattern":"Volitional form form + とるす","jlpt":"N4","example":"草を取ろうとしました","tip":"This expresses an immediate attempt or an intention that is about to be put into action."}],[{"jlpt":"N4","meaning":"To do two actions simultaneously; while doing...","pattern":"Masu-stem + ながら","tip":"The action following ながら is usually the main or primary action.","example":"お酒を飲みながら言いました。"},{"example":"スワに小さい財布などを買ってくれました。","tip":"This expresses gratitude or indicates that the action benefited the recipient.","pattern":"Te-form + くれる","jlpt":"N4","meaning":"Someone does something as a favor for the speaker or someone close to them."},{"meaning":"Because; since. Indicates a reason or cause.","jlpt":"N4","pattern":"Clause + から","tip":"When following a verb or I-adjective, it can be attached to the Dictionary form or the polite Masu-form.","example":"キノコは町で高く売れますから、スワはたくさん取りました。"},{"tip":"This cannot be used for everyday routine events that are considered natural to happen (like 'every morning').","example":"滝を見るたびに、その蛇を考えました。","jlpt":"N3","meaning":"Each time; every time (a certain action happens).","pattern":"Dictionary form + たびに"}],[{"pattern":"Dictionary form + と","meaning":"Expresses an inevitable natural consequence or a repeatable cause-and-effect relationship (if/when)","jlpt":"N4","example":"風が吹くと、家は大きく揺れました。","tip":"The result following this particle is often something that happens automatically or naturally."},{"tip":"This pattern compares two things by highlighting a shared characteristic. Use のような to modify a Noun directly.","example":"動物のように恐ろしい顔でした。","meaning":"To be like something; used for similes and metaphors","jlpt":"N4","pattern":"Noun + のように"},{"pattern":"Plain negative + で","meaning":"Doing something without doing another action first","jlpt":"N4","example":"何も言わないで、スワの近くに来ました。","tip":"Used when an expected action is not performed while doing the main verb. For verbs, it is the negative Te-form (ない → ないで)."},{"jlpt":"N4","meaning":"To try to do something or to be about to do something","pattern":"Volitional form form + とした/とする","tip":"This shows the subject's attempt or immediate intention to perform an action. For Group 2 verbs, replace る with よう.","example":"スワを捕まえようとしました。"},{"pattern":"Volitional form form + としました","jlpt":"N4","meaning":"To try to do something or to be about to do something","example":"逃げようとしました。","tip":"Use this to describe an attempt that might not have been successful."},{"jlpt":"N4","meaning":"Embedded question within a sentence (whether/where/who/etc.)","pattern":"Dictionary form + か","tip":"When using a question word like どこ or なに, the particle か marks the end of the sub-Clause before the main verb.","example":"どこへ行くか分かりませんでした。"},{"pattern":"Clause + と思う/と思いました","jlpt":"N4","meaning":"To express a personal thought or opinion","example":"恐ろしいお父さんが来ると思いました。","tip":"Before と, you must use the Dictionary form (Dictionary form, Plain past, etc.) of the verb or adjective."},{"pattern":"Noun + という","meaning":"Called; named; that says...","jlpt":"N4","example":"「ばか！」という大きい声が聞こえました。","tip":"Use this to define or give the specific content of a sound, name, or statement."},{"pattern":"Noun + か + Noun + か","meaning":"Whether A or B; or","jlpt":"N4","example":"お父さんの声か、風の音か、分かりませんでした。","tip":"This is used to list alternatives when the speaker is unsure which one is correct."},{"pattern":"I-adjective stem + そうだ/そうです","jlpt":"N4","meaning":"Looking like; appearing to be (based on visual impression)","example":"冬の滝はとても寒そうでしたが","tip":"Remove the final い from I-adjectives. For the adjective いい (good), it becomes よさそう."},{"example":"もう逃げることができません。","tip":"This is the formal way to express potential or ability using the nominalizer こと.","pattern":"Dictionary form + ことができる/ことができません","jlpt":"N4","meaning":"To be unable to do something (potential)"}],[{"meaning":"Indicates an embedded question within a sentence.","example":"どのくらい時間が過ぎたか分かりません。","tip":"When the main Clause involves knowing or deciding, use this particle to mark the information being questioned.","jlpt":"N4","pattern":"Dictionary form + か (分かりません)"},{"jlpt":"N4","tip":"Use this to mean 'just as' or 'along the lines of' what was said or done.","pattern":"Plain past + ように","example":"お父さんが言ったように","meaning":"Indicates doing something in the same manner as someone else or as previously mentioned."},{"pattern":"Plain past + り ... Plain past + りする","jlpt":"N4","tip":"Always end the sentence with a form of する (to do) to set the tense for the whole sequence.","meaning":"Lists multiple actions or states in no particular order, implying there may be other similar activities.","example":"エビを追いかけたり、石のそばで遊んだりしました。"},{"meaning":"Indicates the time or occasion when a specific state or action occurred.","example":"人間だった時の悲しい記憶","pattern":"Plain past + 時 (とき)","tip":"Treat the word 'time' like a Noun that is being modified by the preceding Clause.","jlpt":"N3"}]],"intermediate":[[{"example":"秋になると","meaning":"Used to describe a natural consequence or a repetitive action that happens whenever a certain condition is met.","tip":"This is often used for giving directions or describing nature/automatic actions. Avoid using it for personal will or requests.","pattern":"Dictionary form + と","jlpt":"N4"},{"tip":"Unlike ～から～まで, which marks a clear start and end point, this pattern is used when the exact boundaries are vague.","pattern":"Noun + から + Noun + にかけて","jlpt":"N3","meaning":"Expresses a period of time or space with fuzzy boundaries (\"from... through...\").","example":"夏の終わりから秋にかけて"},{"example":"見るために","tip":"Ensure the verb before it is a non-Volitional form state or an intentional action. It expresses a clear purpose.","pattern":"Dictionary form + ために","jlpt":"N4","meaning":"In order to / For the purpose of."},{"meaning":"To do something completely, often with a sense of regret, mistake, or unfortunate outcome.","tip":"In casual speech, this often contract into っちゃう or ちゃう, but the written form for regret remains ～てしまう.","pattern":"Te-form + しまう","jlpt":"N4","example":"落ちてしまった"},{"meaning":"Used when someone does something as a favor for the speaker or someone close to the speaker.","jlpt":"N5","pattern":"Te-form + くれる","tip":"This emphasizes the sender's kindness and the receiver's gratitude. For superior people, use ～てくださる.","example":"茶屋を建ててくれました"},{"example":"塩せんべいなどの駄菓子","jlpt":"N4","pattern":"Noun + など","tip":"It is frequently paired with the particle や to list several items and imply others exist as well.","meaning":"Meaning 'such as' or 'and so on'; used to give examples."},{"example":"売るように言いました","meaning":"Used to report an instruction, command, or advice (\"told someone to...\").","jlpt":"N3","pattern":"Dictionary form + ように + 言う/伝える","tip":"This is an indirect way of quoting an order or request. For a negative command, use Plain negative + ように."},{"jlpt":"N3","pattern":"Noun + の + 通りに / Dictionary form + 通りに","tip":"When following a Noun, it needs the particle の. If following a verb directly, don't use the particle.","meaning":"To do something just as instructed or just like something else.","example":"その通りにしました"},{"meaning":"Indicates that something is easy to do or has a tendency to happen easily.","pattern":"Masu-stem + やすい","jlpt":"N4","tip":"This functions as an I-adjective. Its opposite is ～にくい (difficult to do).","example":"滑りやすくなっていました"}],[{"meaning":"Whenever one thing happens, another thing happens as a natural consequence or habit","jlpt":"N4","pattern":"Dictionary form + と","example":"夜になると","tip":"This specific 'Natural Conditional' is often used to describe natural phenomena or recurring routines."},{"meaning":"To do something completely, often with a sense of regret or unintentionality","jlpt":"N4","pattern":"Te-form + しまう","example":"落ちてしまい","tip":"In this narrative context, it emphasizes the tragic and irreversible nature of falling into the pool."},{"meaning":"Explaining a reason, focus, or providing background information to the listener","tip":"It adds an explanatory tone to the story, making the myth sound like a known fact or deep explanation.","example":"蛇に姿を変えてしまったのだと","pattern":"Dictionary form + のだ/んだ","jlpt":"N4"},{"meaning":"Doing two actions simultaneously (one person performing both)","example":"お酒を飲みながら","tip":"The main action comes after 'nagara', so the focus is on the speaking, not the drinking.","jlpt":"N4","pattern":"Masu-stem + ながら"},{"meaning":"Reporting information heard from another source (hearsay)","jlpt":"N4","pattern":"Dictionary form + そうだ","example":"人間だったそうです","tip":"Since this is a legend passed down by the father, this pattern indicates he is relaying information he didn't witness personally."},{"jlpt":"N3","pattern":"Dictionary form + という + Noun","example":"住んでいたという話です","tip":"This is very common for summarizing the contents of stories, rumors, or names.","meaning":"Called; named; that says that... (used to define or explain the content of a Noun)"},{"meaning":"According to (someone or a source)","tip":"This is a more narrative or formal way to cite a source compared to using 'ni yoru to'.","example":"父親が言うには","pattern":"Noun + が言うには","jlpt":"N3"},{"meaning":"Every time; whenever (something happens)","example":"見るたびに","tip":"Unlike 'to' or 'toki', this emphasizes that the following action or feeling happens 100% of the time.","jlpt":"N3","pattern":"Dictionary form + たびに"},{"example":"籠がいっぱいになるまで","tip":"When used with a verb, it describes a continuous action (picking mushrooms) up until the point the state (basket being full) is reached.","jlpt":"N3","pattern":"Dictionary form + まで","meaning":"Until; to the point that (indicates a limit or continuation up to a certain time/state)"}],[{"meaning":"Nominalizes a verb phrase or Clause to treat it as a Noun object","example":"春が来るのをじっと待っていました","jlpt":"N4","pattern":"Dictionary form + の","tip":"Use this when the following verb is a verb of perception or waiting, like 待つ (to wait) or 聞こえる (to be heard)"},{"jlpt":"N3","pattern":"Dictionary form + たびに","tip":"This emphasizes that every single instance of the first action triggers the second result","example":"風が吹くたびに","meaning":"Each time; every time something happens"},{"jlpt":"N4","pattern":"Noun + のような","tip":"This particle combination creates an adjective-like phrase to describe the appearance or nature of a Noun","meaning":"Like; similar to (describing a Noun)","example":"獣のような顔をしていました"},{"example":"スワを捕まえようと太い腕を伸ばしました","meaning":"Attempting to; trying to; with the intention of doing something","pattern":"Volitional form form + と","jlpt":"N3","tip":"It describes a character's internal intention or an immediate attempt to perform an action"},{"example":"叫びながら必死に抵抗しました","meaning":"While; doing two actions simultaneously","tip":"The primary focus is usually on the second verb in the sentence","pattern":"Masu-stem + ながら","jlpt":"N4"},{"jlpt":"N4","pattern":"Plain past + ら/Conditional + ば + いい","tip":"Often used with question words like どこ (where) or どう (how) to express 'what should I do'","example":"どこへ逃げればいいのか分かりませんでした","meaning":"Should; it would be good if... (seeking advice or expressing uncertainty)"},{"meaning":"Nominalizes a Clause to describe an emotion or feeling about it","example":"父親が追いかけてくるのが恐ろしくて","tip":"Commonly used with adjectives of feeling like 恐ろしい (scary), 好き (like), or 上手 (skillful)","jlpt":"N4","pattern":"Dictionary form + のが + I-adjective"},{"meaning":"To have a feeling that; to have a hunch that; it feels as if","example":"叫ぶ声が聞こえたような気がしました","pattern":"Dictionary form + ような気がする","jlpt":"N3","tip":"Used when the speaker is not 100% sure but has a subjective sensation or intuition"},{"example":"走り続けているうちに","meaning":"While; during; before a change occurs (while an ongoing action is in progress)","tip":"Focuses on a change that happens naturally or unexpectedly during the duration of an action","jlpt":"N3","pattern":"Dictionary form/Te-form + いる + うちに"},{"jlpt":"N3","pattern":"Dictionary form + ように","tip":"When followed by a verb, ように acts as an adverb to describe the manner in which the action is performed","example":"何かに吸い込まれるように","meaning":"As if; in a way that resembles something else (adverbial)"}],[{"meaning":"Expresses completion, regret, or a state of being unintentional or irreversible.","jlpt":"N4","pattern":"Te-form + しまう","example":"どうなってしまったのだろう？","tip":"In this context, it emphasizes the sudden and irreversible nature of the transformation."},{"tip":"Combining this with the past tense often indicates a previous assumption that has been corrected.","example":"大きな蛇になってしまったのかと思いました。","pattern":"Dictionary form + と思う","meaning":"Used to express a thought, belief, or initial impression that usually turns out to be incorrect or different from the current reality.","jlpt":"N4"},{"jlpt":"N4","meaning":"Indicates ability or possibility to perform an action.","pattern":"Dictionary form + ことができる","example":"進むことができます。","tip":"This is the standard way to express potential for Dictionary form verbs without using the potential conjugation."},{"pattern":"Te-form + いく","meaning":"Indicates that an action or state is moving away from the speaker or continuing into the future from the present moment.","jlpt":"N4","tip":"When used with psychological or sensory verbs, it often marks a gradual change over time.","example":"薄れていくようでした。"},{"tip":"It combines the 'try and see' meaning of ～てみる with the conditional ～と which triggers a realization.","example":"足を伸ばしてみると","pattern":"Te-form + みると","meaning":"Expresses that when someone did something, they discovered or realized something new as a result.","jlpt":"N4"},{"jlpt":"N3","meaning":"Used to indicate that something is done in the same manner as something else, or to provide an example.","pattern":"Dictionary form + ように or Noun + のように","example":"父親が話していたように","tip":"It creates a comparison or states that the following action follows the pattern set by the previous Clause."},{"pattern":"Plain past + たり ～ Plain past + たりする","meaning":"Used to list multiple actions or states as examples among others, implying that these are not the only things happening.","jlpt":"N3","tip":"The final verb -する determines the tense of the entire list.","example":"エビを追いかけたり、体をこすりつけたりして"},{"pattern":"Dictionary form + ことはない","meaning":"A formal way to say something is not done or there is no need/experience of doing it. Often used for emphasis.","jlpt":"N3","tip":"In this context, it emphasizes the complete lack of human sensation after the transformation.","example":"寒さも恐怖も感じることはありませんでした。"}]],"original":[[{"meaning":"Explanatory particle used to provide an explanation, emphasize a reason, or state a fact with conviction.","example":"ぼんじゅ山脈というのである","tip":"In writing, ～のである is used for a more formal or literary tone compared to ～のだ.","jlpt":"N4","pattern":"Dictionary form + のだ/のである"},{"meaning":"Indicates that the information was heard from another source (hearsay).","example":"海であったそうで","jlpt":"N4","pattern":"Plain past + そうだ/そうで","tip":"Be careful not to confuse this with the \"looks like\" ～そうだ, which attaches to the Stem of verbs."},{"tip":"When followed by a verb of motion or action, it shows the mental state or purpose behind that action.","jlpt":"N4","pattern":"Volitional form form + と (する)","meaning":"Indicates an intention or an attempt to perform an action.","example":"蝦夷の土地へ渡ろうとここを船でとおった"},{"pattern":"Clause + が","jlpt":"N4","tip":"In this context, it softens the contradiction between common belief and the author's observation.","meaning":"Used to connect two contrasting ideas, similar to \"but\" or \"however.\"","example":"似ているからと言うのであるが"},{"tip":"When used with numbers/quantities, it emphasizes a rough estimate.","pattern":"Noun + ばかり","jlpt":"N4","meaning":"A particle indicating an approximate amount or degree, similar to ～くらい.","example":"二里ばかりさかのぼると"},{"pattern":"Noun + から + Noun + にかけて alcohol","jlpt":"N3","tip":"Unlike ～まで, this pattern implies a continuous or fuzzy boundary across the period or area.","meaning":"Indicates a range of time or space, meaning \"from... through to...\" or \"extending over...\"","example":"夏の末から秋にかけて"},{"meaning":"Indicates that two actions are occurring simultaneously.","example":"岩を噛みつつ流れ出ていた","tip":"This is a more formal and literary version of ～ながら.","jlpt":"N2","pattern":"Masu-stem + つつ"}],[{"meaning":"Throughout a certain period or over a certain span/area.","tip":"Unlike ～まで, this indicates a continuous or fuzzy range in time or space.","example":"春の土用から秋の土用にかけて","jlpt":"N3","pattern":"Noun + から + Noun + にかけて"},{"example":"炭をこさえるのに適しているから","tip":"Often used with adjectives like 便利 (convenient) or 役に立つ (useful). Not to be confused with the 'although' usage.","pattern":"Dictionary form + のに","jlpt":"N4","meaning":"In order to (purpose), or 'for' a certain use."},{"example":"見え初めるじぶんになると","tip":"Focuses on the beginning of an action or process. Often written in kanji as 始める.","pattern":"Masu-stem + 初める","jlpt":"N4","meaning":"To start doing something."},{"meaning":"Even (emphasizing an extreme or unexpected degree).","example":"客を振りかえさすことさえ出来なかった。","tip":"In negative sentences, it emphasizes that even the most basic thing could not be done.","pattern":"Noun + さえ","jlpt":"N3"},{"tip":"Refers to the total absence of an experience or recurring event.","example":"五十銭と売りあげることがなかったのである。","jlpt":"N3","pattern":"Dictionary form + ことがない","meaning":"Never; not once (used for stating a fact or characteristic rather than a choice)."},{"meaning":"Explaining a situation or emphasizing a reason (extended predicate).","tip":"Gives the sentence an explanatory or assertive tone. More formal than ～のだ.","example":"霜のおりるころまでつづくのである。","jlpt":"N3","pattern":"Dictionary form + のである"},{"pattern":"Dictionary form + 気づかいがない","jlpt":"N2","example":"滝壺へ吸いこまれたりする気づかいがないのであった。","tip":"Used to express that there is no risk or worry of a specific negative outcome.","meaning":"To have no concern / fear that something bad might happen."},{"meaning":"Without a doubt; must be.","tip":"Used when the speaker is strongly convinced of something based on evidence or intuition.","example":"なくなって了うにちがいない","jlpt":"N3","pattern":"Dictionary form + にちがいない luxury"},{"example":"知っていたものであった。","tip":"In this context, it reflects on a continuous state or habit that existed in the past.","pattern":"Plain past + ものである","jlpt":"N3","meaning":"Used to express a past habit, a nostalgic memory, or a general tendency."},{"pattern":"Noun + そのほか","jlpt":"N4","example":"そのほか二三種の駄菓子をそこへ並べた。","tip":"Used to list additional items of a similar category.","meaning":"And others; besides that."},{"meaning":"While doing something (a change occurs during the process).","example":"のんでるうちに、体中へぶつぶつと鱗が吹き出た。","tip":"Implies that a change happened before the initial action or state ended.","pattern":"Te-form + いる + うちに","jlpt":"N3"},{"tip":"Expresses a certain feeling or physical sensation that is so strong it is unbearable.","example":"乾いて乾いてたまらなくなった。","jlpt":"N3","pattern":"Te-form + たまらない luxury","meaning":"Can't stand it; irresistibly."},{"pattern":"Volitional form form + と思う luxury","jlpt":"N4","example":"ぶちのめそうと思ったのである。","tip":"Used to express the speaker's (or subject's) intention or will.","meaning":"Thinking of doing / intending to do something."}],[{"pattern":"Te-form + から","tip":"Unlike just the Te-form, this emphasizes that event B starts strictly after event A is completed.","example":"茶店をたたんでから","jlpt":"N4","meaning":"After doing A, B happens; indicates a chronological sequence."},{"tip":"When followed by のだけど, it often implies a contrast between the ideal situation and reality.","pattern":"Conditional form + いい","meaning":"Used to express a suggestion, a wish, or a condition that would be sufficient.","jlpt":"N4","example":"人をたのめばいいのだけれど"},{"tip":"Adding のこと after a person or object makes the target of the verb more abstract or encompassing of their whole being/nature.","pattern":"Noun + のこと","jlpt":"N3","example":"一人のともだちのことを追想した","meaning":"Regarding; about (a certain topic)."},{"tip":"Use this to describe a personal routine or a conscious decision that has become a regular practice.","pattern":"Dictionary form + ことにしている","meaning":"To make it a rule to; to be in the habit of doing.","jlpt":"N3","example":"村へ持って行くことにしていた"},{"tip":"In this context, it highlights a repetitive, almost certain reaction to a specific trigger.","pattern":"Dictionary form + と","meaning":"Whenever A happens, B always follows (natural consequence or habit).","jlpt":"N3","example":"売れると、きまって酒くさいいきをしてかえった"},{"meaning":"Nominalizes a Clause, often used with verbs of waiting, seeing, or hearing.","jlpt":"N3","example":"父親の帰るのを待った","tip":"In literary texts, check if a Noun + が has been replaced by の within this nominalized Clause (Subject marker inversion).","pattern":"Dictionary form + の"},{"meaning":"Mixed with; among (sounds, smells, or abstract things).","jlpt":"N3","example":"木々のさわぐ音にまじって","tip":"Usually used when one thing is indistinguishable from or integrated into a larger surrounding atmosphere.","pattern":"Noun + にまじって"},{"jlpt":"N2","example":"父親を待ちわびたスワは","meaning":"To do something to excess or to feel a strong sense of weariness/distress while doing it.","tip":"Commonly used with verbs like 待ち (wait) or 住み (live) to express a painful or lonely state.","pattern":"Masu-stem + わびる"},{"pattern":"Plain past + ふりをする","tip":"The status can be a state (Noun + の) or an action (Verb). It implies the reality is actually different.","example":"じっと眠ったふりをしていた","jlpt":"N3","meaning":"To pretend to; to act as if."},{"meaning":"While; although; despite being in a certain state.","example":"夢心地ながらうきうきした","jlpt":"N2","pattern":"Noun + ながら","tip":"This is the adversative usage (though), not the simultaneous action usage. It is often used with fixed expressions like 残念ながら."},{"meaning":"To do something completely or to do something regrettable/unintended.","jlpt":"N4","example":"坐って了った","tip":"In older literature, the kanji 了った or 終わった are sometimes used instead of the hiragana しまった.","pattern":"Te-form + しまう"},{"jlpt":"N3","example":"みるみる髪も着物もまっしろになった","meaning":"Very fast; in a flash; right before one's eyes.","tip":"This adverb is usually followed by a change-of-state verb like なる (become) to emphasize the speed of transformation.","pattern":"みるみる+ Clause"}],[{"meaning":"Try doing something to see what it is like or what happens","pattern":"Te-form + みる","jlpt":"N4","tip":"Use this when you are doing an action experimentally or to check the outcome. It is often written in kana when used as an auxiliary verb.","example":"隠れて見たり"},{"jlpt":"N4","pattern":"Plain past + り (+ する)","example":"隠れて見たり、岩角の苔をすすったりして","tip":"Always pair this with the verb する (to do) at the end of the list. It suggests the listed items are just a few examples.","meaning":"Listing actions or states in no particular order, implying there are others as well"},{"meaning":"Used for explanation, emphasis, or providing background information to the listener","jlpt":"N4","pattern":"Dictionary form + のだ/んだ","tip":"In writing, のだ is more common, while んだ is used in spoken Japanese. It connects the statement to the current context or situation.","example":"帰れないのだ"},{"meaning":"To do something completely, often indicating regret, surprise, or an irreversible change","tip":"While often used for mistakes, in this context it emphasizes the completion of a transformation.","example":"大蛇になってしまったのだ","pattern":"Te-form + しまう","jlpt":"N4"},{"jlpt":"N4","pattern":"Volitional form form + とする/としている","tip":"This refers to a moment just before an action starts or a physical effort to perform an action.","example":"ぶっつかろうとした","meaning":"To be about to do something, or to attempt to do something"},{"meaning":"Indicates a judgment based on objective evidence or appearance; it seems that...","tip":"Use this when you have specific reasons or observations that lead you to a certain conclusion.","example":"考えているらしかった","jlpt":"N3","pattern":"Dictionary form + らしい"},{"example":"そよがせるだけである","tip":"When following a verb, it limits the scope of activity to just that specific action.","jlpt":"N3","pattern":"Dictionary form + だけ（だ/である）","meaning":"Nothing but; only; indicating that no other action is taken or exists"},{"example":"くねらせながら","tip":"The action following ながら is usually the primary focus or main action.","jlpt":"N3","pattern":"Masu-stem + ながら","meaning":"While doing; two actions occurring simultaneously by the same subject"},{"meaning":"As soon as; just when; used when one action happens immediately after another unexpectedly","pattern":"Plain past + かと思うと/^かと思えば","jlpt":"N2","tip":"This pattern is often used for sudden changes or surprising successions of events. It cannot be used for the speaker's own intentional future actions.","example":"水面へ浮んで来たかと思うと"}]]},"sakura":{"simplified":[[{"pattern":"Masu-stem / I-adjective - い / Na-adjective + すぎる","meaning":"Indicates that something is excessive or beyond a limit","jlpt":"N4","tip":"For I-adjectives, remove the final い before adding this pattern. For Na-adjectives, use the base form. It often implies a negative result.","example":"桜がきれいすぎますから"},{"example":"ナイフのような物","tip":"Use this when the similarity is based on appearance or characteristics. It functions like an adjective to modify the following Noun.","meaning":"Used to describe something by comparing it to a Noun (like/similar to)","jlpt":"N4","pattern":"Noun + のような"},{"example":"心が空になったような悲しい気持ち","tip":"When modifying a Noun like in the example, use ような. When modifying a verb or adjective, change it to ように.","meaning":"Directly follows a verb or adjective to express a similarity or metaphor (like/as if)","jlpt":"N4","pattern":"Dictionary form + ような / ように"},{"pattern":"Te-form + みてください","meaning":"A polite request to try doing something to see what it is like or what the result will be","jlpt":"N4","tip":"This combines the 'try and see' ～てみる pattern with the polite request ～てください.","example":"考えてみてください。"},{"tip":"While the Potential form of a verb exists, this pattern is often used for more formal or emphatic expressions of (in)ability.","example":"信じることができません。","pattern":"Dictionary form + ことができない","jlpt":"N4","meaning":"Expresses inability to perform an action"},{"jlpt":"N4","meaning":"Embeds a question within a larger sentence (indirect question)","pattern":"Dictionary form + か","example":"どうして不安だったか","tip":"Use this to turn a 'who/what/where/why' question into a Noun Clause. For Na-adjectives and Nouns in the present tense, do not use だ before か."},{"pattern":"Noun + のおかげで / Dictionary form + おけげで","jlpt":"N3","meaning":"Expresses thanks or gratitude for a cause that led to a positive result (thanks to...)","tip":"Unlike ～のせいで (which is for bad results), this is almost always used for positive outcomes or sarcasm.","example":"この考えのおかげで"},{"pattern":"Dictionary form + ことができる","meaning":"Indicates that an action is possible or allowed","jlpt":"N4","tip":"This is a very common way to express potentiality without changing the verb's conjugation into the Potential form.","example":"見ることができます。"},{"meaning":"Indicates that something appears or looks like a certain state based on visual evidence","jlpt":"N4","pattern":"Masu-stem / I-adjective - い / Na-adjective + そうな / そうに","example":"苦しそうな顔","tip":"When modifying a Noun, use そうな. When using it as an adverb, use そうに. For the negative of I-adjectives, change ない to なさそう."}],[{"example":"「かげろう」という虫","jlpt":"N4","meaning":"Called...; named...","tip":"Used when introducing a specific name or title that the listener might not know.","pattern":"Noun + という + Noun"},{"tip":"Used when referencing shared knowledge or following a certain manner/example.","pattern":"Dictionary form + ように","jlpt":"N3","example":"あなたも知っているように","meaning":"As; in the same way as"},{"tip":"Often used for things that happen automatically or to describe finding something after an action.","pattern":"Dictionary form + と","jlpt":"N4","example":"少し歩くと","meaning":"When; if (natural consequence or discovery)"},{"tip":"Used for similes and metaphors to describe the characteristics of a Noun.","pattern":"Noun + のような + Noun","example":"油のような光","jlpt":"N4","meaning":"Like; similar to"},{"meaning":"Embedded question (what do you think...?)","example":"何だと思いますか","jlpt":"N4","pattern":"Interrogative + だ (optional) + と思う","tip":"Used to express an opinion or ask for one regarding a question word like who, what, or where."},{"tip":"Expresses the degree or level of an action or state by giving an example of its intensity.","pattern":"Dictionary form + くらい","jlpt":"N3","example":"数えることができないくらい","meaning":"To the extent that; so much that..."},{"pattern":"Plain past + 後で/後","tip":"Focuses on the chronological order of events; the particle で is optional when modifying a Noun.","meaning":"After doing something","example":"卵を産んだ後のかげろう","jlpt":"N4"},{"example":"光っていたのです","jlpt":"N4","meaning":"The fact is; it is that... (explanatory emphasis)","tip":"Provides an explanation, reason, or adds emotional emphasis to the statement.","pattern":"Dictionary form + のです/んです"},{"example":"死体を見るのが好きな人","jlpt":"N4","meaning":"The act of (nominalizer)","tip":"Turns a verb into a Noun so it can be used with particles like が or を, often with verbs of feeling like 'to like'.","pattern":"Dictionary form + の (nominalizer)"},{"example":"きれいなだけのものは","jlpt":"N3","meaning":"Only; just; nothing but","tip":"Limits the scope to just that one quality or thing, excluding others.","pattern":"Na-adjective + な + だけ"},{"meaning":"Finally; at last (after effort or waiting)やっと","jlpt":"N4","example":"私たちの悲しい気持ちは終わるのです","pattern":"やっと + Clause","tip":"Usually implies a positive or long-awaited result reached after some difficulty or time."},{"example":"死体が埋まっています","jlpt":"N4","meaning":"State resulting from a completed action (intransitive)","tip":"When used with intransitive change-of-state verbs like 'to be buried', it describes a current state.","pattern":"Te-form + いる"},{"meaning":"Embedded question (whether/where...)","example":"どこから来たのか","jlpt":"N3","pattern":"Interrogative + Dictionary form + か","tip":"Allows a question to function as a Noun Clause within a larger sentence."},{"meaning":"Not at all; completely not (with negative)","example":"全く分かりません","jlpt":"N4","pattern":"全く + Plain negative","tip":"Used to strongly emphasize a negative state or inability."},{"meaning":"Seems/looks like it is possible to...","jlpt":"N3","example":"飲むことができそうです","pattern":"Stem + そうだ","tip":"Attached to the stem of the Potential form here to indicate an observation or feeling about a future possibility."}]],"intermediate":[[{"meaning":"Permission or expressing that something is acceptable/okay to do","jlpt":"N4","pattern":"Te-form + もいい","example":"信じてもいいことなんだよ","tip":"In this context, it is used to emphasize that the wild theory is actually acceptable to believe."},{"tip":"Used here to challenge the listener's logic and emphasize the speaker's perspective.","pattern":"Noun / Clause + じゃないか","example":"信じられないことじゃないか","jlpt":"N4","meaning":"Isn't it the case that...? (Seeking confirmation or emphasizing a point)"},{"meaning":"Used to express surprise, contempt, or emphasis toward a certain action or state","jlpt":"N3","example":"見事に咲くなんて","pattern":"Dictionary form + なんて","tip":"This pattern often carries a nuance of 'the very fact that...' and is frequently used when the speaker is emotionally moved."},{"tip":"Unlike ために or から, せいで is specifically used when blaming something for a bad outcome.","example":"綺麗すぎるせいで","pattern":"I-adjective (no い) + すぎる + せいで","jlpt":"N3","meaning":"Because of...; due to... (Used for negative causes and results)"},{"example":"空っぽになったような気持ちになった","pattern":"Plain past + ような + 気持ち","tip":"This connects a figurative description to an internal emotional state.","meaning":"Feeling like...; to have a feeling as if...","jlpt":"N3"},{"pattern":"Te-form + みてくれ","example":"想像してみてくれ","tip":"This is a slightly rough or masculine version of ～てみてください. It combines the 'try to' (～てみる) and 'please' (～てください) meanings.","meaning":"Please do (something) for me (Casual request)","jlpt":"N4"},{"meaning":"Probably; I think... (Expressing conjecture)","jlpt":"N4","pattern":"Dictionary form + だろう","example":"納得できるだろう","tip":"In this text, the speaker is using it to lead the listener toward his own conclusion."},{"jlpt":"N3","meaning":"Even so; despite that; nevertheless","tip":"It is used to highlight a stark contrast between the rotting corpses and the beautiful liquid they produce.","example":"嫌な臭いを出している。それなのに、","pattern":"Clause + それなのに"},{"example":"上っていくのが見えるようだ","pattern":"Dictionary form + ようだ","tip":"The speaker uses this to describe their vivid hallucination or visualization as if it were a physical reality.","meaning":"It seems like; to look like... (Based on appearances or feelings)","jlpt":"N3"},{"meaning":"To reach the point where one can do something; a change in ability or habit","jlpt":"N4","example":"見ることができるようになったのだ","pattern":"Dictionary form + ことができる + ようになる","tip":"This structure highlights the transition from being unable to look at the flowers calmly to finally being able to do so."}],[{"meaning":"When (someone) does something, they notice or discover something else; or a natural consequence.","jlpt":"N4","pattern":"Dictionary form + と","example":"歩いていると","tip":"This conditional 'to' focuses on an objective discovery or a natural progression of events."},{"pattern":"Masu-stem + きれる/きれない","example":"数えきれない","tip":"Used to express finishing a task thoroughly or reaching the limits of a capacity.","meaning":"To do something completely to the end, or to be unable to do so (in negative form).","jlpt":"N3"},{"meaning":"Nothing more than; merely; just.","jlpt":"N3","example":"風景に過ぎない","pattern":"Noun + に過ぎない","tip":"Commonly used to downplay the importance or scale of something."},{"meaning":"Not until; only after something happens does something else become possible.","jlpt":"N2","example":"あってはじめて","pattern":"Te-form + はじめて","tip":"Emphasizes that the first action is an indispensable requirement for the second state."},{"tip":"It is a softer, slightly authoritative way to say 'try to do' (temiru).","pattern":"Te-form + ごらん","example":"想像してごらん","jlpt":"N2","meaning":"Try doing (used when addressing someone of lower status or in a gentle imperative way)."},{"pattern":"Volitional form + とはしない","example":"離れていこうとはしない","tip":"This expresses that the subject (often an object or third person) appears to refuse to perform an action.","meaning":"To show no intention of doing; to not try to do at all.","jlpt":"N2"},{"example":"飲めそうな気がする","pattern":"Clause + 気がする","tip":"Used to express a subjective feeling or intuition without solid evidence.","meaning":"To have a feeling that; to have a hunch that.","jlpt":"N3"}]],"original":[[{"meaning":"Expresses surprise, disbelief, or emotional emphasis toward a fact or statement","pattern":"Dictionary form + なんて","jlpt":"N3","example":"あんなにも見事に咲くなんて信じられない","tip":"Think of this as a more casual or emotional version of など or というのは; it often follows a feeling of shock or contempt."},{"meaning":"Expresses a strong certainty or conviction that something is true","pattern":"Noun + にちがいない","jlpt":"N3","tip":"Use this when you have a logical reason to be sure of something, though it is based on your own judgment.","example":"同じようなことにちがいない"},{"pattern":"Dictionary form + 気がする","jlpt":"N3","tip":"This is used for vague feelings or premonitions where you don't have definitive proof.","example":"何か信じられないもののような気がした","meaning":"Indicates an intuitive feeling or subjective impression that something is the case"},{"meaning":"Expresses a similarity, appearance, or a goal/manner of action","tip":"When used for comparison, it functions like 'as if' or 'just like'. Don't confuse it with the 'in order to' usage.","example":"完全な静止に澄むように","jlpt":"N3","pattern":"Dictionary form + ように"},{"meaning":"Expresses that something will inevitably or naturally happen, or must be done (cannot help but...)","example":"人の心を撲たずにはおかない","tip":"This is a literary expression often used for strong natural tendencies or powerful emotions that cannot be suppressed.","pattern":"Plain negative (minus ない) + ずにはおかない","jlpt":"N2"},{"meaning":"Used to give permission or, more often, a slightly condescending or haughty suggestion/instruction","example":"想像してみるがいい","tip":"This sounds quite authoritative or dramatic; you might hear it used by villains or teachers in fiction.","pattern":"Te-form + みるがいい","jlpt":"N2"},{"meaning":"Describes something that appears to be the case, often used for analogies or metaphors; 'stating as if'","pattern":"Dictionary form + ようだ","jlpt":"N2","tip":"While this looks like N4 grammar, in this literary context it creates an imaginative comparison ('it is as if...').","example":"あがってゆくのが見えるようだ"},{"tip":"This is the causative version of ～がる (to show outward signs of an emotion). It means 'to make someone exhibit a certain feeling'.","example":"俺を不安がらせた神秘","pattern":"Stem of I-adjective + がらせる","jlpt":"N2","meaning":"The Causative form of an 'I-adjective' emotion or feeling, meaning 'to make someone feel' or 'to cause a state'"}],[{"example":"しばらく歩いていると","tip":"In this context, it indicates that the speaker unexpectedly discovered something after walking for a while.","pattern":"Dictionary form + と","meaning":"When or if; used to express a natural consequence or a discovery after an action.","jlpt":"N4"},{"example":"死体だったのだ","tip":"The 'no' (often contracted to 'n') adds an explanatory tone, as if revealing a hidden truth.","pattern":"Noun + なのだ / だったのだ","meaning":"Used to provide an explanation, emphasize a fact, or give focus to the sentence.","jlpt":"N4"},{"meaning":"Just as... or in the same way as...","jlpt":"N3","pattern":"Dictionary form + とおり","tip":"Use this pattern when you want to show that an action or state matches a previous statement or established fact.","example":"おまえも知っているとおり"},{"tip":"Use ような to modify nouns and ように to modify verbs or adjectives. It describes a figurative resemblance.","example":"石油を流したような光彩","meaning":"Looking like; appearing to be (simile).","jlpt":"N3","pattern":"Plain past + ような / ように"},{"example":"胸が衝かれるような気がした","tip":"This expression is used for subjective feelings or premonitions that aren't based on physical sensation.","pattern":"Dictionary form + 気がする","meaning":"To have a certain feeling or intuition; it feels as if...","jlpt":"N3"},{"tip":"This is used to downplay the importance or scale of something, emphasizing that it is 'only' what is mentioned.","example":"心象に過ぎない","meaning":"Nothing more than; merely; just.","jlpt":"N3","pattern":"Noun + に過ぎない"},{"pattern":"Dictionary form + ばかり","meaning":"Only; nothing but (often with an emphasizing nuance).","jlpt":"N3","example":"完成するときにばかり","tip":"When used with certain particles, it emphasizes that a specific condition is the only one that applies."},{"tip":"This implies the subject is 'refusing' to act or that the action simply refuses to occur despite expectations.","example":"離れてゆこうとはしない","jlpt":"N3","meaning":"To show no intention of doing; to not try to do (often of inanimate objects or stubborn people).","pattern":"Volitional form + とはしない / としない"},{"tip":"When attached to the Potential form of a verb, it expresses a feeling that something has become possible.","example":"酒が呑めそうな気がする","meaning":"To look like; to seem likely to.","jlpt":"N3","pattern":"Masu-stem + そうだ / そうな"}]]},"urashima":{"simplified":[[{"jlpt":"N4","pattern":"Te-form + はいけません","example":"いじめてはいけません","tip":"This is the polite form of ～ではいけない and is often used by adults to scold children or state a rule.","meaning":"Must not; used to forbid an action or indicate it is not allowed."},{"jlpt":"N4","pattern":"Masu-stem + なさい","example":"帰りなさい","tip":"While it sounds firm, it is less aggressive than the Imperative form and is common in parental or educational contexts.","meaning":"Order or strong command; used by people in authority to give directions."},{"example":"帰してやりました","tip":"Be careful not to use this for people of equal or higher status, as it can sound patronizing. Use ～てあげる instead.","jlpt":"N4","pattern":"Te-form + やる","meaning":"To do something for someone of lower status, an animal, or a plant."},{"pattern":"I-adjective (remove い) + そうだ","jlpt":"N4","tip":"When describing feelings of others, this form is necessary because you cannot directly state another person's emotions.","example":"苦しそうでした","meaning":"Looks like; seems; used to describe an impression based on visual appearance."},{"meaning":"When/if; indicates that one action or event is followed by an unexpected discovery or result.","example":"歩いていると","tip":"In a narrative context, this pattern often introduces a new scene or a surprising event that happened immediately after the action.","jlpt":"N4","pattern":"Dictionary form + と"},{"jlpt":"N4","pattern":"Noun + という + Noun","example":"浦島太郎という若い漁師","tip":"This is extremely common when introducing specific names of things that the listener might not be familiar with.","meaning":"Called; named; used to define or identify a person, place, or thing."}],[{"jlpt":"N5","example":"ゆっくり休んでください","tip":"Use this when you are asking someone to do something for you or giving kind advice.","pattern":"Te-form + ください","meaning":"A polite way to request or give an instruction to someone"},{"tip":"This shows the favor was done for the benefit of the speaker or someone they care about. In this text, it is used in the past tense to say thank you.","example":"亀を助けてくれて","jlpt":"N4","meaning":"Expressing gratitude for an action someone performed for the speaker or a third party","pattern":"Te-form + くれる"},{"jlpt":"N4","example":"心配しないで","tip":"This is often used for instructions to 'not do' something while doing something else, or simply 'please don't'.","meaning":"Doing an action (or requesting one) without performing another specific action; 'without doing'","pattern":"Plain negative + で"},{"meaning":"To be just like; used to describe a Noun by comparing it to another Noun","pattern":"Noun + のように","tip":"This is used for metaphors or comparisons. Use 'Noun + のような' if it is directly modifying a Noun.","example":"夢のように素晴らしい所でした","jlpt":"N4"},{"tip":"In narratives, this often marks the moment a character sees or realizes something after moving to a new location.","example":"中へ入ると","jlpt":"N4","pattern":"Dictionary form + と","meaning":"Indicates a natural consequence or that the speaker discovered something upon doing an action; 'when/if'"}],[{"tip":"This is used primarily for the speaker's own desires in the first person.","example":"帰りたいです","pattern":"Masu-stem + たい","jlpt":"N5","meaning":"To express desire or wanting to do an action"},{"tip":"Often shortened to ～なきゃ (informal) or ～なければならない (plain) in daily speech.","example":"帰らなければなりません","pattern":"Plain negative (minus い) + ければなりません","jlpt":"N4","meaning":"To have to do something; must; obligation"},{"meaning":"To look like; to appear a certain way based on visual impression","jlpt":"N4","pattern":"I-adjective (minus い) + そうだ","example":"悲しそうでした","tip":"For I-adjectives, remove the final い before adding そう. If using the adjective いい, it becomes よさそう."},{"tip":"This conditional structure is often used for giving directions or describing natural laws.","example":"帰ると","pattern":"Dictionary form + と","jlpt":"N4","meaning":"Natural consequence; when/if one thing happens, another follows inevitably"},{"meaning":"Called; named; used to identify or define something","tip":"Use this when introducing a name or a concept that the listener might not know.","example":"玉手箱という宝物","pattern":"Noun + という + Noun","jlpt":"N4"},{"tip":"This is the standard way to express a strong prohibition or rule.","example":"開けてはいけません","pattern":"Te-form + はいいけません","jlpt":"N4","meaning":"Must not; prohibition; not allowed to do something"},{"meaning":"Can do; to be able to; expresses potential or possibility","jlpt":"N4","pattern":"Dictionary form + ことができます","example":"会うことができます","tip":"This is a more formal alternative to the potential verb conjugation."},{"tip":"The ば conditional focuses more on the condition required to reach a specific result.","example":"開けなければ","pattern":"Plain negative (minus い) + ければ surface form","jlpt":"N3","meaning":"If; conditional \"if\" (often focusing on the prerequisite condition)"}],[{"meaning":"Must not; should not (prohibition)","jlpt":"N4","example":"開けてはいけない","pattern":"Te-form + はいけない","tip":"This is a formal and strong prohibition, often used for rules or warnings."},{"pattern":"Plain past + ことがある","tip":"Use the Plain past form of the verb to talk about things you have done at some point in your life.","jlpt":"N4","example":"聞いたことがあります","meaning":"To have the experience of (doing something)"},{"pattern":"Dictionary form + ことができる","tip":"This is the standard way to express potential using the Noun こと and the verb できる.","meaning":"Can; to be able to do something","jlpt":"N4","example":"戻ることができる"},{"tip":"In this context, it suggests an impulsive or irreversible action.","pattern":"Te-form + しまう","meaning":"To do something completely or to do something accidentally/regrettably","example":"開けてしまいました","jlpt":"N4"},{"example":"開けたら","jlpt":"N4","meaning":"If; when (conditional)","tip":"This conditional is very common in spoken Japanese and focuses on what happens after the condition is met.","pattern":"Plain past + ら"},{"tip":"This pattern expresses a possibility that something might be true, usually around a 50% chance.","pattern":"Dictionary form + かもしれない","example":"戻ることができるかもしれない","jlpt":"N4","meaning":"Might; perhaps; maybe"},{"jlpt":"N4","example":"おじいさんになってしまったのです","meaning":"It is the case that (explanatory emphasis)","pattern":"Dictionary form + のだ / のです","tip":"Use this when providing an explanation, clarification, or emphasizing a reason for a situation."},{"meaning":"While doing (simultaneous actions)","example":"泣きながら","jlpt":"N4","tip":"The main action comes after ながら. In this case, 'looking' is the main action while 'crying' is occurring.","pattern":"Masu-stem + ながら"},{"pattern":"Noun + だらけ","tip":"Use this for things that are messy or unwanted, like mud, dust, mistakes, or wrinkles.","jlpt":"N3","example":"しわだらけになりました","meaning":"Covered with; full of (usually something negative)"}]],"intermediate":[[{"example":"そんなひどいことをしてはいけないよ","jlpt":"N4","meaning":"Must not / prohibited to do something","tip":"This is a stronger prohibition than ～てはいけません and is often used by adults when scolding or instructing subordinates.","pattern":"Te-form + はいけない"},{"tip":"When used after a verb, it describes a situation where one action or state dominates the scene to the exclusion of others.","pattern":"Dictionary form + ばかりで","meaning":"Nothing but / only (emphasizing a single state or repetitive action)","example":"海が広がるばかりで他の舟は一艘もありません","jlpt":"N3"},{"jlpt":"N3","example":"お礼を言っているかのように太郎を見つめた後","meaning":"As if / just like","pattern":"Noun + の/Dictionary form + かのように","tip":"Used for similes that describe a state that is not actually true but appears to be so."},{"tip":"This is the standard Humble Form (Kenjougo) to show respect to the person receiving the action.","pattern":"お + Masu-stem + する/したい","meaning":"Humble expression used when doing something for the benefit of someone else","example":"素晴らしい世界、竜宮城へご案内したいと思います","jlpt":"N3"},{"example":"海の底の世界を見てみたいという強い好奇心に駆られました。","jlpt":"N3","tip":"Use this to provide the specific details of a vague Noun like 好奇心 (curiosity), 夢 (dream), or 噂 (rumor).","pattern":"Clause + という + Noun","meaning":"The thing called... / defining the content of a thought or feeling"},{"meaning":"Like / similar to (used for appearance and metaphors)","pattern":"Noun + のような / Dictionary form + ような","tip":"Unlike ～かのように, this is often used for direct comparisons or exemplifying something with a specific Noun.","example":"見たこともないような色鮮やかな魚たちが","jlpt":"N3"},{"example":"太郎を歓迎するように彼の周りをぐるぐると泳ぎ回っていました。","jlpt":"N3","meaning":"In such a way that / so that / as if","pattern":"Dictionary form + ように","tip":"When following a verb, it often indicates an objective, a request, or the manner in which an action is performed."}],[{"example":"窓を開ければ桜が満開に咲き乱れる春の景色","tip":"In this narrative context, it indicates that whenever the window is opened, a specific scenery inevitably appears.","jlpt":"N4","meaning":"Conditional \"if/when\" used to describe a natural consequence or a general truth.","pattern":"Conditional form (Verb)"},{"meaning":"Used to describe a sequence of events where one action leads to an immediate or unexpected discovery.","pattern":"Dictionary form + と","example":"太郎が門をくぐると","tip":"Often used in storytelling to set the scene or introduce a new character when the protagonist moves to a new location.","jlpt":"N4"},{"example":"地上の苦労や心配事はすべて忘れて、どうぞゆっくりと楽しんでいってください","tip":"Here it means to proceed with the action of \"enjoying oneself\" from this point forward.","jlpt":"N4","meaning":"To go and do something, or to do something and then leave. Also used for continuous actions moving away from the speaker.","pattern":"Te-form + いく"},{"jlpt":"N4","tip":"This is the humble version of ～てもらう. Oto-hime uses it to show respect to Taro for saving the turtle.","example":"亀の命を救っていただき","pattern":"Te-form + いただく","meaning":"A humble expression used when the speaker receives a favor or an action from someone of higher status."},{"meaning":"While the plain Te-form is usually for sequences, it also connects clauses to show manner or cause.","pattern":"Te-form (Sequential/Manner)","tip":"In \"wasurete sughoshita,\" it describes the state or manner in which he spent his days (forgetting time).","example":"時間を忘れて楽しい毎日を過ごしました","jlpt":"N4"},{"jlpt":"N4","example":"楽しむことができたのです","tip":"The \"no\" nominalizes the preceding Clause, and \"desu\" provides an assertive explanation. In speech, it often turns into \"n desu.\"","meaning":"Explains a situation, adds emphasis, or provides a reason for what was just mentioned.","pattern":"Dictionary form + のです"},{"example":"真珠のように白く輝く顔","tip":"When modifying an adjective or verb, use \"ni.\" When modifying a Noun, use \"Noun + no you na.\"","jlpt":"N4","pattern":"Noun + のように","meaning":"Used to create a simile, meaning \"like\" or \"resembling.\""},{"pattern":"Dictionary form + ほど","meaning":"Indicates the extent or degree of something, often to an extreme point.","example":"この世の者とは思えないほど美しい","tip":"It translates to \"to the extent that...\" or \"so much that...\" to emphasize the intensity of the beauty.","jlpt":"N3"},{"pattern":"Dictionary form + べき","meaning":"Expresses that someone should do something, or that a certain state is expected/natural. Often used in fixed phrases.","example":"さらに驚くべきことに","tip":"Odoroku-beki is a set phrase meaning \"surprising\" or \"astonishing.\" Always use the Dictionary form before beki (except for suru, which can be subeki).","jlpt":"N2"},{"pattern":"Stem + きれる/きれない","meaning":"To do something completely to the end. When used in the negative, it means the action is impossible to finish.","jlpt":"N2","example":"表現しきれないほど素晴らしい","tip":"\"Hyougen-shikirenai\" means something is so vast or intense that it is impossible to express it entirely with words."}],[{"example":"経ってしまった","tip":"In this context, it emphasizes the irreversible passing of time and the character's sense of regret.","pattern":"Te-form + しまう","jlpt":"N4","meaning":"To do something completely; often implies regret or an accidental occurrence"},{"tip":"It expresses the speaker's internal doubt or a question to oneself about a state.","example":"元気でいるだろうか","jlpt":"N4","meaning":"Wondering about something; the polite/casual conjecture form of 'desu' or 'masu' combined with a question particle","pattern":"Dictionary form + だろうか"},{"meaning":"To be certain that; without a doubt; used when there is strong conviction or evidence","jlpt":"N3","pattern":"Dictionary form + に違いない","tip":"Use this when you are making a strong logical deduction about a situation.","example":"泣いているに違いない"},{"example":"思い始めると","tip":"In this story, it indicates that the moment he started thinking about his parents, the feelings naturally overflowed.","pattern":"Dictionary form + と","jlpt":"N4","meaning":"Whenever X happens, Y always happens; used for natural consequences or habitual actions; or 'when/once' for specific discoveries"},{"meaning":"To start doing something; indicates the beginning of an action/state","jlpt":"N4","pattern":"Masu-stem + 始める","tip":"Similar to 'dasu', but 'hajimeru' is used for more intentional or logical start points.","example":"思い始めると"},{"pattern":"Plain negative (stem) + なければならない","jlpt":"N4","meaning":"Must; have to; indicates a necessity or obligation","example":"帰らなければならない","tip":"Though this looks long, it literally means 'it won't do if you don't (do the action)'."},{"jlpt":"N4","meaning":"Thinking of doing; expressing a desire or intention somewhat politely/indirectly","pattern":"V-tai form + と思う","tip":"Using 'to omou' after a desire makes the statement sound less direct and more like a shared feeling.","example":"帰りたいと思います"},{"example":"悲しそうな顔","tip":"Since it modifies the Noun 'kao' (face) here, it takes the 'na' attributive ending.","pattern":"I-adjective (drop い) + そうな","meaning":"Looking like; appearing as if; describes an external appearance or atmosphere","jlpt":"N4"},{"example":"お帰りになる","tip":"This is a standard Sonkeigo (respectful) pattern for elevated figures like the Dragon Princess.","pattern":"お + Masu-stem + になる","meaning":"Honorific expression used to show respect to the subject's actions","jlpt":"N4"},{"pattern":"お + Masu-stem + いたす","meaning":"Humble expression used to lower oneself/one's actions to show respect; 'itashimasu' is the humble version of 'shimasu'","jlpt":"N4","example":"お引き止めはいたしません","tip":"Known as Kenjougo (humble Japanese), this is used for the speaker's own actions toward a superior."},{"example":"開けてはいけません","tip":"This is the standard way to express a prohibition. In casual speech, it often becomes 'cha dame'.","pattern":"Te-form + はいいけない","jlpt":"N5","meaning":"Must not; forbidden; strongly prohibited"}],[{"meaning":"The interrogative plus is used with a negative verb to express a total absence (nobody, nothing, nowhere).","jlpt":"N5","pattern":"Interrogative + も + Plain negative verb","example":"誰もいない","tip":"In this context, 誰 (who) combines with も and the negative to mean 'no one at all'."},{"jlpt":"N4","meaning":"Indicates that someone does nothing else but a specific action, or that a situation remains constant in one direction.","tip":"When used with the Dictionary form, it often implies the repetition or continuation of a single action.","pattern":"Dictionary form + ばかり","example":"首をかしげるばかりです"},{"jlpt":"N4","meaning":"Expresses a strong confidence or expectation based on reason or memory.","tip":"Use this when you are logically certain something should be the case, even if the reality turns out differently.","example":"住んでいたはずの場所","pattern":"Dictionary form + はず"},{"pattern":"Dictionary form + かもしれない","example":"会えるかもしれない","tip":"This indicates a roughly fifty-fifty chance or a lingering doubt/hope.","meaning":"Expresses a possibility or a guess that something might happen.","jlpt":"N4"},{"example":"見つめ続けることしかできませんでした","pattern":"Noun + しか + Plain negative verb","tip":"It often carries a nuance of resignation or limitation. Note that it is always used with a negative verb.","meaning":"Indicates that there is no other option or possibility except the one mentioned.","jlpt":"N4"},{"pattern":"Dictionary form + と (conditional)","example":"到着すると","tip":"When used for discovery, the following Clause usually describes a situation the speaker noticed after the action. house.","meaning":"Expressed a natural consequence, a discovery, or a trigger for the following action.","jlpt":"N4"},{"jlpt":"N4","meaning":"Used to ask for advice or wonder about the best course of action.","tip":"Adding のか turns the expression into an indirect question or an expression of internal doubt.","pattern":"Dictionary form + ばいい","example":"どうやって生きていけばいいのか"},{"pattern":"Plain past + ように","example":"驚いたように言いました","tip":"When modifying a verb, ように functions like an adverb to describe the manner of the action.","meaning":"Indicates that something appears to be a certain way, or an action is done in a certain manner.","jlpt":"N3"},{"example":"海へ行ったきり","pattern":"Plain past + きり","tip":"In this text, it means he went and 'never came back'—the state of having gone remained permanent.","meaning":"Indicates that an action happened and then the state remained unchanged, with the expected follow-up action never occurring.","jlpt":"N3"},{"pattern":"Plain past + ようだ/ように/ような","example":"驚いたように言いました","tip":"Unlike そうだ, this is used for conclusions based on more comprehensive observations or similarities.","meaning":"Indicates a subjective feeling or state that seems to be true based on appearance or behavior.","jlpt":"N3"},{"pattern":"Stem + ぬ","example":"見知らぬ大きな家","tip":"This is an old or formal way to say ～ない. 知らぬ (not knowing) is common in fixed expressions or stories.","meaning":"A literary negative form used to modify nouns or to mean 'without doing'.","jlpt":"N3"},{"jlpt":"N3","meaning":"Indicates that something is on the verge of happening or appears likely to happen.","tip":"This is specifically used for events that almost happened but didn't quite occur.","pattern":"Masu-stem + そうになる","example":"膝から崩れ落ちそうになりました"},{"meaning":"Meaning 'let alone' or 'to say nothing of', used to emphasize that if a simpler thing is not present, a more significant thing certainly isn't either.","jlpt":"N1","pattern":"Noun + はおろか","example":"両親の姿はおろか","tip":"It is almost always followed by a negative statement or a situation that is even worse than the first mentioned item."}]],"original":[[{"meaning":"Called; named (used to introduce a person or thing by name)","jlpt":"N5","example":"浦島太郎というりょうし","pattern":"Noun + という + Noun","tip":"Use this when the listener might not know the specific entity you are naming."},{"meaning":"Expresses a repeated or habitual action occurring whenever a condition is met","jlpt":"N3","pattern":"Dictionary form + は + Dictionary form / Te-form + は + Dictionary form","example":"かついでは海へ出かけて","tip":"In this context, it emphasizes the repetitive routine of the fisherman's life."},{"meaning":"In the same way as; just as; following (a pattern or habit)","jlpt":"N3","pattern":"Noun + の + とおり / Dictionary form + とおり","example":"いつものとおり海へ出て","tip":"When attached directly to a Noun without の, it often becomes どおり."},{"meaning":"When (I) did... (used when the result of an action was discovered or unexpected)","jlpt":"N4","example":"のぞいてみると","pattern":"Te-form + みると","tip":"It combines the 'try to' meaning of ～てみる with the 'when' conditional と."},{"jlpt":"N5","meaning":"Doing things like... (listing multiple actions among others)","tip":"The final する can be conjugated into any form (here it is している for ongoing action).","pattern":"Plain past + り + Plain past + り + する","example":"つついたり、たたいたり"},{"meaning":"One should not; it is not the case that one should (expressing a moral or social imperative)","jlpt":"N3","pattern":"Dictionary form + ものではない","example":"するものではない","tip":"This sounds like a lecture or a general rule of thumb. Often shortened to もんじゃない in speech."},{"jlpt":"N2","meaning":"Without even trying to; showing no intention of doing something","tip":"This expresses that the subject shows absolutely no sign or effort toward the action.","pattern":"Volitional form + とも + しない","example":"きき入れようともしないで"},{"pattern":"Dictionary form + もんか / ものか","example":"かまうもんかい","tip":"The prefix かい adds a masculine or rough colloquial tone to the question.","meaning":"Used to express a strong negative feeling or \"as if I would...\" (rhetorical question)","jlpt":"N2"},{"jlpt":"N4","meaning":"While doing; simultaneously performing two actions","tip":"The main action always comes after ながら.","example":"わいわいいいながら","pattern":"Masu-stem + ながら"},{"example":"あぶないところだった","pattern":"Dictionary form + ところだった","tip":"Usually accompanied by words like 危うく(narrowly) or もう少しで (almost).","meaning":"Was just about to; was on the verge of (usually an undesirable outcome)","jlpt":"N3"},{"meaning":"Humble form of 'to come' or 'to go' (Kenjougo)","jlpt":"N4","pattern":"まいりました (Humble verb)","example":"お礼にまいりました","tip":"Use this when speaking to a social superior or a benefactor about your own movement."},{"jlpt":"N1","meaning":"There is no need to; it is unnecessary to (formal)","tip":"It can also be used to mean 'cannot reach his level' (～に及ばない), but here it means 'not necessary'.","pattern":"Dictionary form + には及ばない","example":"礼なんぞいいにくるにはおよばない"},{"meaning":"Intending to; planning to","jlpt":"N4","example":"どうして行くつもりだね","pattern":"Dictionary form + つもりだ","tip":"Use this to express your own intentions or ask about someone else's definite plan."},{"meaning":"Just as (someone says); following (one's lead) without resistance","jlpt":"N3","example":"いわれるままに","pattern":"Dictionary form / Plain past + ままに","tip":"Commonly used as 言われるまま (as I was told) or なすがまま (as it happens)."},{"tip":"Use ような to modify a Noun and ように to modify an Adjective or Verb.","pattern":"Noun + の + ような / ように","example":"夢のようにはこばれて行きます","jlpt":"N4","meaning":"Like; similar to (metaphor or comparison)"},{"tip":"Here it describes a state so intense (blinding/dizzying) that it serves as a metaphor for the appearance.","example":"目のくらむような金銀のいらか","pattern":"Dictionary form + ような + Noun","jlpt":"N3","meaning":"So much that; to the extent that (describing the degree of something)"}],[{"pattern":"Dictionary form + ようだ","tip":"Use this when making a comparison or describing something that appears to be a certain way based on your own feeling.","meaning":"To be like; to look like; to resemble (used for similes and subjective impressions).","example":"浦島はただもう夢のなかで夢を見ているようでした。","jlpt":"N4"},{"pattern":"Plain past + り + Plain past + りする","tip":"The final verb determines the tense and politeness of the entire sentence.","meaning":"Doing things like A and B (listing multiple actions or states among others).","jlpt":"N4","example":"歌をうたったり踊りをおどったりしました。"},{"pattern":"Interrogative + からともなく","tip":"Commonly used with verbs of sensing like smelling, hearing, or appearing.","meaning":"Expresses that the source, time, or person is unknown or unclear (from nowhere, from someone unknown).","jlpt":"N3","example":"どこからともなくいいにおいがして"},{"jlpt":"N3","example":"ひととおり見てしまうと","meaning":"Used to indicate that an action is completed or finished.","tip":"In this context, it emphasizes the completeness of the tour rather than the regretful meaning often found in N4.","pattern":"Te-form + しまう"},{"tip":"This is a set honorific phrase used when showing something to a person of higher status.","pattern":"お目にかける","jlpt":"N3","example":"四季のけしきをお目にかけましょう","meaning":"Humble way to say 'to show' (the humble form of 見せる)."},{"pattern":"Masu-stem + くださいまして","tip":"This is more formal and polite than simply saying ～てください。","meaning":"A very polite way to say 'thank you for doing...' something for me.","jlpt":"N3","example":"お助けくださいまして"},{"tip":"Unlike や or と, this implies there are many items and focuses on listing them one after another.","pattern":"Noun + だの + Noun + だの","jlpt":"N2","example":"かつおだの、ふぐだの、えびだの","meaning":"Listing examples in a repetitive, sometimes disparaging or overwhelmed manner (things like..., and the like...)."},{"example":"とても口やことばではいえないくらいでした。","jlpt":"N2","meaning":"To the extent that...; so much so that... (describing the degree of a state).","tip":"Use this to emphasize the intensity of an emotion or condition by providing a hypothetical comparison.","pattern":"Dictionary form + くらい"}],[{"jlpt":"N4","meaning":"A nominalizer indicating the specific moment, scene, or physical location where an action occurs.","pattern":"Dictionary form + ところ","example":"舟をこいだりしているところを","tip":"Unlike standard nominalizers like 'koto' or 'no', 'tokoro' emphasizes the scene or the timing of the action."},{"jlpt":"N4","meaning":"Indicates that two actions are performed simultaneously by the same person.","pattern":"Masu-stem + ながら","tip":"The main action always comes second in the sentence.","example":"舟うたをうたいながら"},{"pattern":"Plain past + り + Plain past + りする","tip":"It implies that other actions might also be happening, not just the ones mentioned.","example":"網をひいたり舟をこいだりしている","jlpt":"N4","meaning":"Lists examples of actions among others in a non-exhaustive list."},{"jlpt":"N4","meaning":"Indicates a gradual change in state or the start of a new habit/tendency.","pattern":"Dictionary form + ようになる","example":"夢を見るようになりました","tip":"Use this to describe a shift from 'not doing' to 'doing' something naturally over time."},{"pattern":"Te-form + いらっしゃる/なさい","example":"行っていらっしゃいまし","tip":"In this text, 'mashi' is an archaic polite suffix added to the imperative or soft command.","jlpt":"N4","meaning":"A polite command or invitation using the Te-form, often seen in older or very polite speech."},{"jlpt":"N4","meaning":"Strong prohibition stating that one must not do something.","pattern":"Te-form + はいいけない/はいけません","example":"あけてごらんになってはいけません","tip":"This is a common way to forbid someone from doing an action, especially to subordinates or children."},{"jlpt":"N3","meaning":"While a certain state or action is continuing, a change or event occurs.","pattern":"Dictionary form + うちに/うち","example":"あそんでくらすうち","tip":"It implies that if the time passes or the state changes, the opportunity might be lost."},{"meaning":"Indicates that someone is doing nothing but a specific action, often with a negative or critical nuance.","jlpt":"N3","tip":"This expresses that the frequency of the action is so high it seems like they are doing nothing else.","example":"ふさぎこんでばかりいました","pattern":"Te-form + ばかりいる"},{"meaning":"The honorific version of 'te iru', used to describe the state or ongoing action of a superior.","jlpt":"N3","tip":"This is a highly respectful (sonkeigo) substitute for 'iru' or 'iku/kuru'.","example":"どうしておいでになるだろう","pattern":"Te-form + おいでになる"},{"meaning":"An idiomatic expression meaning to be so anxious or excited that one cannot sit still.","jlpt":"N2","tip":"This specific phrase is a set idiom for extreme restlessness or impatience.","example":"いても立ってもいられなくなる","pattern":"Te-form + も + Masu-stem + 振る舞い + も + Potential negative"},{"meaning":"The humble (kenjougo) form used when the speaker is doing something for or to a superior.","jlpt":"N2","example":"おひきとめ申しても","tip":"Use this pattern to lower yourself and show respect to the person receiving the action.","pattern":"お + Masu-stem + 申し上げる/申す"}],[{"tip":"In speech, this is often contracted to んだ. It makes the statement feel like an explanation rather than just a dry fact.","example":"住んでいたのです","pattern":"Dictionary form + のだ/です","jlpt":"N4","meaning":"Used to provide an explanation, emphasize a fact, or provide background information for what was said."},{"jlpt":"N3","meaning":"Indicates that the source or location of something is unknown or unclear (from nowhere; from some unknown place).","pattern":"Noun + からともなく","example":"どこからともなく","tip":"This is often used with sensory verbs like hearing a sound or smelling a scent without knowing the origin."},{"tip":"The main action comes after ながら. The first action is the background or secondary activity.","example":"見ながら","pattern":"Masu-stem + ながら","meaning":"Indicates that two actions are being performed simultaneously by the same person.","jlpt":"N4"},{"pattern":"Plain past + まま","meaning":"Indicates that a state or condition remains unchanged while another action occurs; \"left as it is.\"","jlpt":"N3","tip":"Often used when something is done in a way that is contrary to common practice or expectation (e.g., wearing shoes inside).","example":"立ったまま"},{"meaning":"Indicates a change in state or the result of a process (to become/to reach a state).","jlpt":"N4","pattern":"I-adjective (remove い) + くなる","example":"帰ってこなくなりました","tip":"For nouns and Na-adjectives, use になる instead of くなる."},{"meaning":"Used to report information heard from another source (I heard that...; it is said that...).","jlpt":"N3","pattern":"Clause + ということです","example":"行ったのだろうということです","tip":"This is more formal than uses of らしい or だそうだ and is common in news or recounting legends."},{"example":"どこかへ行ってしまうはずはない","tip":"This is the negative version of はずだ. It implies a logical deduction that something is highly unlikely.","meaning":"Expresses a strong confidence or expectation that something is impossible or should not be the case.","jlpt":"N4","pattern":"Dictionary form + はずはない"},{"pattern":"Plain past + たらば","meaning":"A classic or literary Conditional form meaning \"if\" or \"when.\"","jlpt":"N3","tip":"Modern Japanese usually just uses たら. The ば suffix adds a slightly more formal or emphatic conditional tone found in older stories.","example":"あけてみたらば"},{"example":"こいしくてたまらなくなりました","tip":"Usually used with subjective feelings like emotions or physical sensations (hungry, lonely, itchy).","jlpt":"N3","meaning":"Used to express that a physical or mental feeling is so strong that it is unbearable.","pattern":"I-adjective (remove い) + くてたまらない"},{"tip":"Often pairs with a negative verb to emphasize the extremity of a situation.","example":"立っていたらしいあとさえ","pattern":"Noun + さえ","meaning":"Used to emphasize that even a basic or expected thing does not exist or occur; \"even.\"","jlpt":"N3"},{"tip":"This is a more literary or formal way of saying 方法がない (no way/method).","example":"わたろう手だてもありませんでした","pattern":"Dictionary form + 手だてがない","jlpt":"N2","meaning":"Indicates that there is no way or means to achieve a certain goal."},{"tip":"This is a variation of かしら, primarily used in literature or by older speakers to express internal doubt or curiosity.","example":"あたるのかしらん","pattern":"Dictionary form + かしらん","jlpt":"N3","meaning":"A casual or slightly old-fashioned way of wondering to oneself (I wonder if...)."}]]},"asa":{"simplified":[[{"meaning":"To be able to do something; to have the ability to do something.","jlpt":"N5","tip":"This pattern allows a verb to be treated as a Noun, enabling it to be the subject or object of a sentence. It's similar to the English '-ing' form of a verb.","pattern":"Dictionary form + ことができる","example":"私は遊ぶことが一番好きです。"},{"tip":"This pattern expresses a concession or a condition that holds true regardless of the preceding Clause.","jlpt":"N4","meaning":"Even if; even though.","pattern":"Te-form + も","example":"家で仕事をしていても、友達が来るのをいつも待っています。"},{"jlpt":"N4","meaning":"To wait for someone/something to do something.","tip":"The のnominalizes the preceding Clause, making it the object of 待つ (to wait).","pattern":"Dictionary form + のを待つ","example":"友達が来るのをいつも待っています。"},{"meaning":"When; if (a natural consequence or habitual action).","jlpt":"N4","tip":"This conditional indicates that the second Clause naturally follows from the first, often describing either a general truth or a habitual action.","example":"玄関のドアが開くと、少し嫌な顔をします。","pattern":"Dictionary form + と"},{"meaning":"In order to; so that; like.","jlpt":"N4","tip":"This pattern can indicate purpose (in order to) or similarity (like/as if). In this context, it implies a purpose.","pattern":"Dictionary form + ように","example":"家族にお弁当を作ってもらって、その部屋に行きます。"},{"example":"女の人が銀行から帰る前に、私は自分の家に帰ります。","pattern":"Dictionary form + 前に","jlpt":"N4","meaning":"Before (doing something).","tip":"Always pair with the Dictionary form of the verb to indicate an action that takes place prior to the main Clause."},{"example":"彼女は、もうすぐその男の人と結婚する予定です。","pattern":"Dictionary form + そうだ","jlpt":"N4","meaning":"It looks like; it seems that (based on appearance).","tip":"This pattern expresses an immediate impression or appearance. For verbs, drop ～ます and add そうだ."},{"pattern":"Te-form + くれる/もらう","example":"家族にお弁当を作ってもらって、その部屋に行きます。","tip":"～てくれる indicates someone does something for you, while ～てもらう indicates you receive a favor from someone doing something for you.","jlpt":"N4","meaning":"To receive the favor of someone doing something."},{"pattern":"Stem + に行く","example":"遊びに行きます。","meaning":"To go in order to do something.","jlpt":"N5","tip":"This pattern expresses the purpose of going somewhere. Use the Masu-stem of the verb followed by に行く."},{"pattern":"Noun + と言う","example":"名前はキクちゃんと言います。","tip":"Used to introduce a name or nickname, usually in the pattern 〇〇という名前 or 〇〇と言います.","meaning":"Named; called.","jlpt":"N5"},{"example":"だから、私はある場所に秘密の仕事部屋を作りました。","pattern":"Dictionary form + だから","tip":"This connects two clauses, indicating a cause-and-effect relationship. It is more casual than ですから.","jlpt":"N4","meaning":"Therefore; that is why."},{"jlpt":"N4","meaning":"Plan to; scheduled to.","tip":"This Noun indicates a plan or fixed schedule. It can be used with Dictionary form verbs or Nouns.","example":"彼女は、もうすぐその男の人と結婚する予定です。","pattern":"Dictionary form + 予定"},{"pattern":"Dictionary form + まで","example":"午後3時ごろになると、疲れます。","jlpt":"N5","meaning":"Until.","tip":"Indicates a continuing action or state up to a certain point in time or space."},{"example":"家族にお弁当を作ってもらって、その部屋に行きます。","pattern":"Dictionary form + ように","tip":"Indicates a purpose or goal. Often used when the subject of the main Clause and the subordinate Clause are different, or when the purpose is not directly controlled by the subject.","meaning":"So that; in order to.","jlpt":"N4"},{"meaning":"Even if one doesn't; even without.","jlpt":"N3","tip":"This indicates that something occurs regardless of whether a certain action is performed or not.","pattern":"Plain negative + なくても","example":"秘密の部屋には誰も来ないから、仕事は予定の通りに進みます。"}],[{"meaning":"Expresses ability or possibility to do something.","jlpt":"N5","pattern":"Dictionary form + ことができます","example":"歩くことができなくなりました。","tip":"This pattern combines a verb in its Dictionary form with こと (nominalizer) and ができます (can do). The negative form is ことができません."},{"jlpt":"N5","meaning":"Asks for permission to do something.","tip":"This polite request asks if it is 'okay to do X'. Replacing いい with だめ or いけません makes it 'is it not okay to do X?'.","example":"窓からおしっこをしてもいいですか","pattern":"Te-form + もいいですか"},{"jlpt":"N4","meaning":"Expresses a conditional 'if' or 'when'. The consequence happens after the condition is met.","tip":"This Conditional form implies the action will definitely or usually occur if the condition is met. It can be used with all word types.","pattern":"Plain past + ら","example":"明るかったら、今夜は何も悪いことをしないと思いました。"},{"tip":"Use this pattern when the result is a natural outcome, a habitual action, or an unexpected discovery. It emphasizes the direct and automatic consequence.","pattern":"Dictionary form + と","example":"少し足を動かすと、靴下を履いたままでした。","jlpt":"N4","meaning":"Expresses a natural or inevitable consequence when a certain condition is met; 'when/if X, then Y naturally happens.'"},{"pattern":"Te-form + しまう","example":"私は「しまった！」と思いました。","tip":"When a mistake or accident happens, しまう adds a sense of regret or completion that cannot be undone. In casual speech, it often contracts to ちゃう or じゃう.","meaning":"Expresses either completion of an action, or that something undesirable/regrettable has happened.","jlpt":"N4"},{"tip":"This pattern specifically implies that the action of the main Clause will occur if the preceding Clause's action is done 'for the speaker's benefit' or 'for us'.","pattern":"Te-form + くれたら","example":"ろうそくをつけてくれたら、お酒を飲みます","jlpt":"N4","meaning":"Expresses a conditional 'if someone does X for me'."},{"pattern":"Dictionary form + ために","example":"家に帰ることができません。","tip":"Used with verbs in Dictionary form, it means 'in order to'. With nouns, use Noun + のために. For reasons or causes, the preceding Clause is often descriptive.","meaning":"Expresses purpose or reason: 'in order to' for actions, or 'because of' for situations/causes.","jlpt":"N3"},{"example":"電気をつけようとしました。","pattern":"Dictionary form + としました","tip":"Adding としました after the Volitional form of a verb shows an attempt was made. This example uses つけよう (Volitional form of つける).","meaning":"Expresses attempting or trying to do something, often with the implication of failure or difficulty.","jlpt":"N3"},{"meaning":"Expresses leaving a situation or state as it is, or remaining in a certain condition.","jlpt":"N3","example":"コートを着たまま寝ました。","pattern":"Te-form + まま","tip":"This pattern indicates that an action or state continues without change. It can be preceded by a verb in Te-form, a Noun + の, or an I-adjective / Na-adjective."},{"jlpt":"N3","meaning":"Means 'must do,' 'have to do,' or 'should not do' (if negative), implying undesirable consequences if not done.","tip":"The negative conditional Verb + ないと (short for ないといけない) often implies 'if I don't do X, then something bad will happen'. This sentence features another grammatical structure between ない and と.","pattern":"Plain negative + といけない","example":"私が寝るか、お酒の酔いがなくなるかしないと、私はキクちゃんに悪いことをしてしまうかもしれません。"},{"tip":"The pattern is Verb Plain past + ほうがいい to suggest doing something, and Verb Plain negative + ほうがいい for suggesting not doing something. Note this example uses 'たらどうですか' which is a softer suggestion than 'ほうがいい'.","example":"靴下を脱いだらどうですか？","pattern":"Plain past + ほうがいい","jlpt":"N4","meaning":"Suggests that doing something is better or advisable."},{"jlpt":"N3","meaning":"Expresses possibility or conjecture, meaning 'maybe', 'perhaps', or 'it might be that'.","tip":"This pattern can follow a wide range of word types including verbs (Dictionary form), adjectives, and nouns by adding the Dictionary form of だ before かもしれません.","example":"私はキクちゃんに悪いことをしてしまうかもしれません。","pattern":"Dictionary form + かもしれません"}]],"intermediate":[[{"jlpt":"N5","meaning":"To be able to do something; it is possible to do something.","tip":"Combines a verb's Dictionary form with こと (a nominalizer) and ができる (can do). It converts a verb into a Noun phrase, allowing it to act as the subject of the Clause.","example":"私は遊ぶことが何よりも好きです。","pattern":"Dictionary form + ことができる"},{"pattern":"Te-form + もらう","example":"家族にお弁当を作ってもらい","jlpt":"N4","meaning":"To have someone do something for you, often implying a favor or benefit received.","tip":"Used to express that the speaker receives a favor from someone. The giver is marked by に."},{"tip":"Indicates a personal decision or resolution. The speaker is the one making the decision.","jlpt":"N4","meaning":"To decide to do something.","pattern":"Dictionary form + ことにする","example":"仕事部屋を作ることにしました。"},{"example":"玄関の戸が開くと、嫌な顔をして文句を言うふりをしますが","pattern":"Plain past + ら","tip":"Similar to ～と but can express a wider range of conditions and subsequent actions. Often implies an unexpected or surprising outcome.","meaning":"When/if (a condition is met). Used for sequential or conditional actions/events.","jlpt":"N4"},{"example":"文句を言うふりをしますが","pattern":"Dictionary form + ふりをする","meaning":"To pretend to do something, or to act as if something is true.","jlpt":"N3","tip":"Can be used with Dictionary form for verbs and Plain past for adjectives/nouns to indicate pretense."},{"tip":"Expresses the speaker's intention or plan. It can also signify a belief or expectation about something.","jlpt":"N3","meaning":"To intend to do something; to plan to do something.","example":"あっさりと結婚するつもりのようでした。","pattern":"Dictionary form + つもりだ"},{"jlpt":"N3","meaning":"Like; similar to; typical of.","tip":"Used to make comparisons or give examples, functioning as a Na-adjective to modify a Noun.","pattern":"Noun + のような","example":"人生経験が豊かな大人が言いそうなことを書いて送ったこともありました。"},{"pattern":"Clause + ようだ","example":"お母さんよりも娘さんのほうが、私をよく信頼しているように思えます。","tip":"Expresses conjecture or appearance based on observation, but with less certainty than ～そうだ. The preceding Clause can be in Dictionary form.","jlpt":"N3","meaning":"It seems that; it looks like; appears to be."},{"jlpt":"N3","meaning":"To do something completely/accidentally/regrettably. Implies completion, regret, or unintended action.","tip":"Adds a sense of completion, often with a nuance of regret, something being finished entirely, or an action happening inadvertently.","example":"遊びに出かけてしまいます。","pattern":"Te-form + しまう"},{"tip":"Used to express that something happens occasionally. The verb before こと is in Dictionary form.","jlpt":"N3","meaning":"There are times when; sometimes.","example":"深夜に帰宅することもあります。","pattern":"Dictionary form + ことがある"},{"tip":"Indicates that an action has just been completed, or that something is exclusively in a certain state. Can also mean 'only' or 'nothing but'.","meaning":"Just finished doing something; only (just).","jlpt":"N3","pattern":"Plain past + ばかり","example":"青年に会ってみて、「あの人ならいいお婿さんになるでしょう。賛成です」などと、人生経験が豊かな大人が言いそうなことを書いて送ったこともありました。"},{"tip":"Used to deny a common assumption or direct statement, clarifying misunderstanding.","jlpt":"N2","meaning":"It does not mean that; it is not that.","pattern":"Dictionary form + わけではない","example":"彼女は私の恋人などではありません。"},{"example":"疲れてくるし、人が恋しくなって遊びたくなります。","pattern":"I-adjective stem + し","tip":"Used to list reasons or additional characteristics, often implying there are other unstated reasons. It can connect various types of clauses.","meaning":"And; moreover; as well as (listing reasons or additional information).","jlpt":"N4"},{"tip":"Expresses a strong recommendation or obligation. Nouns are followed by であるべき.","jlpt":"N2","meaning":"Should; ought to.","example":"お婿さんになるでしょう。賛成です」などと、人生経験が豊かな大人が言いそうなことを書いて送ったこともありました。","pattern":"Dictionary form + べきだ"},{"example":"お母さんよりも娘さんのほうが、私をよく信頼しているように思えます。","pattern":"Dictionary form + ばかりでなく","tip":"Connects two elements to show that both are true, with the second often being more significant or surprising. Often paired with も.","jlpt":"N2","meaning":"Not only... but also..."}],[{"meaning":"Expresses that something is a regular occurrence or a habit.","jlpt":"N4","pattern":"Dictionary form + こと","example":"たくさん飲むのは毎晩のことで","tip":"This pattern emphasizes the habitual nature of an action or state."},{"jlpt":"N4","meaning":"Indicates that something is not the case, or there is no need to do something.","tip":"Similar to ～必要はない (there is no need to), but can also express that something is not a particular occurrence.","pattern":"Dictionary form + ことはありません","example":"珍しいことではありません。"},{"meaning":"To go somewhere to do something.","jlpt":"N5","example":"飲みに出かける","pattern":"Stem + に行く","tip":"Used to express the purpose of going somewhere. The verb before に is always in the Stem form."},{"meaning":"An action done for a specific purpose.","jlpt":"N4","example":"おしっこをしてもいいかな","pattern":"Dictionary form + に + Noun","tip":"This pattern expresses the purpose of an action using a Noun. The verb before に is in the Dictionary form."},{"tip":"Conveys a sense of completion, often with regret or an unintended outcome. Can also imply doing something quickly or thoroughly.","pattern":"Te-form + しまう","example":"寝てしまいました","jlpt":"N4","meaning":"To do something completely or by accident, often with a sense of regret or completion."},{"pattern":"Dictionary form + そうにない","example":"帰れそうにない","tip":"Expresses a prediction of unlikelihood or impossibility based on the speaker's assessment of the situation.","meaning":"It doesn't seem like something will happen; unlikely to happen.","jlpt":"N3"},{"jlpt":"N3","meaning":"To leave something as it is; to remain in a certain state.","tip":"Indicates that an action or state is maintained without change.","pattern":"Plain past + まま","example":"コートを着たまま"},{"jlpt":"N4","meaning":"Used to explain a reason, provide background information, or seek confirmation.","tip":"Adds an explanatory or emphatic nuance to a sentence. Often used in casual conversation as ～んだ.","example":"泊めてくれ。家まで歩いて帰れそうにない。このまま寝てしまうから。","pattern":"Dictionary form + のです / んだ"},{"tip":"Can indicate something was just completed, or only that action/state. Here it emphasizes 'only that' action is happening.","example":"ばかりなのです","pattern":"Plain past + ばかり","jlpt":"N3","meaning":"Just finished doing something; only that (and nothing else)."},{"jlpt":"N3","meaning":"To do something in such a way that...","tip":"Expresses an effort or intention to achieve a certain state or outcome.","pattern":"Dictionary form + ように","example":"直角になるように"},{"tip":"Often used by speakers to themselves or to soften an inquiry to others. Primarily used by male speakers, or by female speakers in a very casual context.","example":"してもいいかな","pattern":"Dictionary form + かな","jlpt":"N4","meaning":"I wonder if...; I suppose (softens a question or statement)."},{"tip":"Used to ask for or grant permission. The negative form is ～てはいけない (must not).","example":"おしっこをしてもいいかな","pattern":"Te-form + もいい","jlpt":"N5","meaning":"May I/Can I...?; Is it okay to...?"},{"example":"お飲みなさい","pattern":"Masu-stem + なさい","tip":"Often used by parents to children or between close friends. Can sound condescending if used improperly.","meaning":"A mild command or instruction (less direct than imperative).","jlpt":"N4"},{"tip":"Can express nostalgia or a general truth/expectation. Often accompanied by よ or ね for emphasis.","example":"したものなんだよ","pattern":"Plain past + ものだ","jlpt":"N3","meaning":"Used when recalling past habits or common occurrences; should/ought to."},{"example":"飲みにくい","pattern":"Stem + にくい","tip":"Indicates intrinsic difficulty or inconvenience of an action. The opposite is Stem + やすい (easy to do).","meaning":"Difficult to do.","jlpt":"N3"},{"jlpt":"N4","meaning":"I hear that...; It is said that...","tip":"Used to convey information heard from someone else. The source of information is external, unlike ～ようだ or ～らしい. The example implicitly uses ～そうだ with the Plain past form of 思う in the narrative.","example":"(Implicit in) ～だと思ったんだ。","pattern":"Stem + そうだ (hearsay)"},{"example":"やめるべき","pattern":"Dictionary form + べき","tip":"Expresses a strong sense of obligation or recommendation. Can also be negative: べきではない (should not).","meaning":"Should; ought to.","jlpt":"N3"}]],"original":[[{"tip":"This pattern highlights that an action 'can be done' or 'is possible' rather than an inherent skill.","example":"仕事が出来ないので","jlpt":"N4","meaning":"Expresses ability or possibility.","pattern":"Dictionary form + ことができる"},{"tip":"Often used for explanations or personal feelings, and implies that the listener understands the context.","example":"好きななので","meaning":"Indicates a reason or cause for something, softer than ～から.","jlpt":"N4","pattern":"Noun + なので"},{"example":"家で仕事をしていながらも","tip":"Distinguish between continuous action (e.g., 食べる (to eat)) and a resulting state (e.g., 結婚している (is married)).","pattern":"Te-form + いる","jlpt":"N5","meaning":"Indicates an ongoing action, a state resulting from an action, or a habitual action."},{"example":"家で仕事をしていながらも","tip":"The main action is usually the second Clause, with the first Clause describing a subsidiary action.","pattern":"Te-form + ～ながら","jlpt":"N3","meaning":"Indicates two actions happening simultaneously by the same subject."},{"pattern":"Dictionary form + こと","meaning":"Nominalizes a verb, turning it into a Noun phrase.","jlpt":"N4","example":"遊びに出る事","tip":"It's generally interchangeable with の for nominalization, but sometimes こと is preferred in formal contexts or fixed expressions."},{"example":"設ける事にしたのである","tip":"Often implies a conscious choice or resolution.","pattern":"Dictionary form + に + する","meaning":"Expresses a decision or to make something a rule or habit.","jlpt":"N3"},{"tip":"Can also be used with nouns followed by まで.","example":"いつまでも","meaning":"Indicates a limit in time or space, meaning 'until' or 'up to'.","jlpt":"N5","pattern":"Dictionary form + まで"},{"pattern":"Te-form + もらう","jlpt":"N4","meaning":"Requesting or receiving a favor from someone.","example":"弁当を作らせ","tip":"Similar to the English 'have someone do something for you' or 'get someone to do something'."},{"pattern":"Stem + たい","jlpt":"N5","meaning":"Expresses a desire to do something.","example":"遊びたくなって","tip":"This is an I-adjective and conjugates as such (e.g., ～たくない (do not want to do))."},{"example":"深夜の帰宅になる","tip":"Often used when something 'becomes' or 'turns into' something else.","pattern":"Stem + に + なる","meaning":"Indicates a change or a state being reached.","jlpt":"N4"},{"tip":"Used for past experiences, whether once or multiple times, but not for ongoing actions.","example":"あった事もあった","meaning":"Indicates having the experience of doing something.","jlpt":"N4","pattern":"Plain past + た + ことがある"},{"pattern":"Dictionary form + のような","meaning":"Indicates resemblance, 'like' or 'similar to'.","jlpt":"N3","example":"愛人とか何とか","tip":"Often used to give an example that represents a category, or to express uncertainty about the exact nature of something."},{"meaning":"Conveys hearsay or information heard from someone else.","jlpt":"N4","pattern":"Stem + そうだ","tip":"Requires the Dictionary form of a verb or adjective before そうだ to express hearsay. For visual conjecture, use the Stem + そうだ.","example":"気でいるようであった"},{"example":"信頼しているように","tip":"Context is key to differentiating its various meanings. Look for surrounding verbs or phrases that indicate purpose, appearance, or request.","pattern":"Dictionary form + ように","meaning":"Expresses similarity ('as if/like'), purpose ('in order to'), or a request ('so that').","jlpt":"N3"}],[{"jlpt":"N4","meaning":"Indicates the purpose for an action, where the Noun is the result of the action.","pattern":"Dictionary form + に + Noun","tip":"This pattern is often used for going somewhere to do something, especially with verbs like 行く (iku), 来る (kuru), or 帰る (kaeru).","example":"飲みに行く (go drinking)"},{"jlpt":"N3","meaning":"Indicates a surprising or unexpected situation, often with a nuance of complaint or dissatisfaction.","pattern":"Noun + なのに","tip":"Similar to 'but' or 'even though', highlighting a contrast between expectation and reality.","example":"寝ているのに (even though I was sleeping)"},{"pattern":"Dictionary form + ことがある","jlpt":"N4","meaning":"Indicates that something happens occasionally or has happened before.","example":"くりかえした事か (how many times have I repeated it)","tip":"Often translated as 'to have done something' or 'sometimes do something'. The 'か' at the end of the example expresses a rhetorical question."},{"example":"やるんじゃねえか (aren't you doing it too?)","tip":"Mainly used in casual conversation, especially by male speakers.","pattern":"Dictionary form + んじゃ","meaning":"A casual contraction of ～のではないか, often implying a speaker's conjecture or mild accusation.","jlpt":"N3"},{"jlpt":"N3","meaning":"A more informal or softer way of saying ～のかもしれない, expressing possibility or conjecture.","pattern":"Dictionary form + のかも","tip":"This pattern implies a high degree of uncertainty or wonder, often used when the speaker is thinking aloud.","example":"吐くのではなかろうか (I wonder if I'm going to throw up)"},{"tip":"This Conditional form implies a more definite or immediate consequence than ～ば or ～と.","example":"飲んだら、あぶないと思った (If I drink, I thought it would be dangerous)","jlpt":"N4","meaning":"Indicates a conditional statement, meaning 'if' or 'when'.","pattern":"Plain past + ら"},{"tip":"This pattern emphasizes that nothing else is happening or is desired apart from what is stated.","example":"大胆にするばかりなのである (it's only making me bolder)","jlpt":"N3","meaning":"Means 'only', 'just', or 'nothing but', emphasizing exclusivity or a single focus.","pattern":"Dictionary form + ばかり"},{"jlpt":"N3","meaning":"Indicates expectation or conviction that something is true, based on some information or reasoning.","pattern":"Dictionary form + はず","tip":"This expresses a strong presumption or a natural consequence, often translated as 'should be' or 'it is expected that'.","example":"寝ながら飲むんでしょう (you're supposed to drink while sleeping, right?)"},{"pattern":"Te-form + しまう","jlpt":"N4","meaning":"Indicates that an action is completed, often with a sense of regret, difficulty, or unintended outcome.","example":"消えてしまった (it disappeared)","tip":"When used with regret or an unwanted outcome, it can communicate 'unfortunately' or 'to end up doing'."},{"tip":"Use this pattern when you perceive something but cannot pinpoint the source directly. For example, '変な音がする' (I hear a strange sound).","example":"気がしていた (I felt as if)","jlpt":"N4","meaning":"Indicates that one perceives something through their senses (smell, sound, taste, or a general feeling).","pattern":"Noun + がする"}]]}};
